window.CLINICAL_DB["guidelines"] = [{"name": "中国高血压防治指南（2024年版）", "category": "心血管内科", "scope": "18岁以上成人高血压筛查、诊断、评估、治疗和管理。", "diagnosis": ["诊室血压：非同日3次≥140/90mmHg", "家庭自测：≥135/85mmHg", "24h动态：24h平均≥130/80，白天≥135/85，夜间≥120/70", "初诊查：血常规、尿常规、生化、心电图、眼底", "疑继发性：肾动脉超声、肾上腺CT、儿茶酚胺、醛固酮/肾素"], "staging": ["正常高值120-139/80-89", "1级140-159/90-99", "2级160-179/100-109", "3级≥180/110", "单纯收缩期：收缩≥140且舒张<90", "危险分层：低/中/高/很高危"], "key_points": ["目标：一般<140/90，能耐受<130/80；老年<140/90", "高危立即用药，中危观察4周，低危观察3个月", "生活方式干预是基础", "2级以上初始联合，优选SPC", "优先长效制剂", "同时干预血脂血糖吸烟"], "drug_recommendations": ["CCB：氨氯地平5mg qd起(最大10)、硝苯地平控释30mg qd", "ACEI：依那普利5-10mg bid、贝那普利10-20mg qd", "ARB：缬沙坦80-160mg qd、厄贝沙坦150-300mg qd", "利尿剂：氢氯噻嗪12.5-25mg qd、吲达帕胺1.5-2.5mg qd", "β阻滞剂：美托洛尔47.5-95mg qd、比索洛尔2.5-10mg qd", "SPC：缬沙坦氨氯地平、培哚普利氨氯地平", "难治性：加螺内酯20-40mg qd(eGFR≥45,K<4.5)"], "non_pharmacological": ["限盐<5g/d", "减重BMI<24，腰围男<90女<85", "每周≥150分钟中等强度有氧运动", "限酒男<25g女<15g酒精/d", "戒烟包括二手烟", "心理平衡，保证睡眠"], "complications": ["高血压急症(≥180/120+靶器官损害)：静脉降压，1h降25%，2-6h至160/100", "亚急症：口服降压，24-48h逐步降压", "合并卒中：急性期不急于降压，>220/120或溶栓>185/110才降", "合并冠心病：β阻滞剂+ACEI/ARB，目标<130/80", "合并心衰：β阻滞剂+ACEI/ARB+MRA+SGLT2i", "合并糖尿病/CKD：ACEI/ARB首选"], "monitoring": ["初诊/调药期：每周测2-3天早晚各1次", "稳定期：每周1-2天", "每次随访：血压、心率、体重、电解质、肾功能", "每年：心电图、心超、尿微量白蛋白、眼底"], "special_populations": ["老年：小剂量起始，缓慢加量，防体位性低血压", "妊娠：甲基多巴、拉贝洛尔、硝苯地平；禁用ACEI/ARB/利尿剂", "儿童青少年：优先生活方式，药物选CCB/ACEI/ARB", "继发性：针对病因治疗"], "references": "中国高血压防治指南修订委员会. 中国高血压防治指南(2024). 中华心血管病杂志", "py": "zggxyfzzn（nb）"}, {"name": "慢性冠脉综合征诊断和治疗指南（2024）", "category": "心血管内科", "scope": "冠心病稳定期(CCS)诊断、危险分层、药物治疗和血运重建决策。", "diagnosis": ["典型心绞痛：胸骨后压榨感，劳力诱发，休息/硝酸甘油缓解<15min", "不典型：女性/糖尿病/老人可胸闷气短上腹痛", "静息心电图可正常，发作时ST-T改变", "负荷试验：运动平板、负荷超声、负荷心肌灌注", "冠脉CTA：中低危首选无创", "冠脉造影：金标准，高危或无创阳性者"], "staging": ["CCS心绞痛分级：I一般活动无症状/II轻度受限/III明显受限/IV静息发作", "高危：左主干>50%、前降支近段>70%、LVEF<35%、多支病变", "SYNTAX评分：评估病变复杂度指导血运重建"], "key_points": ["药物治疗是基石，所有患者GDMT", "高危推荐PCI/CABG，中危可考虑，低危优先药物", "二级预防：抗血小板、调脂、降压、降糖、生活方式", "完全血运重建优于部分", "左主干/三支：SYNTAX≤22可选PCI，>22推荐CABG", "康复运动改善预后"], "drug_recommendations": ["抗血小板：阿司匹林75-100mg qd长期；PCI术后DAPT 6-12个月(氯吡格雷75mg qd/替格瑞洛90mg bid)", "调脂：LDL-C<1.4且降幅≥50%；阿托伐他汀20-80mg qn；不达标加依折麦布10mg；仍不达标加PCSK9i", "β阻滞剂：美托洛尔47.5-190mg qd，目标静息心率55-60", "ACEI/ARB：合并高血压/心衰/糖尿病/CKD时用", "硝酸酯：硝酸异山梨酯10mg tid(缓解症状不改善预后)", "SGLT2i：合并心衰/CKD/糖尿病时推荐", "曲美他嗪20mg tid辅助"], "non_pharmacological": ["戒烟限酒，控制体重BMI<24", "地中海饮食：多蔬果全谷物鱼类坚果，少红肉饱和脂肪", "心脏康复：每周≥150分钟中等强度有氧", "控制血压<130/80、HbA1c<7%、LDL达标", "心理调节，避免过劳情绪激动", "流感肺炎球菌疫苗"], "complications": ["急性冠脉综合征：按STEMI/NSTEMI处理，急诊PCI", "心力衰竭：按心衰GDMT", "心律失常：房颤抗凝+心率/节律控制，室性评估猝死风险", "缺血性心肌病：LVEF<35%+完全血运重建后仍低评估ICD", "支架内血栓：DAPT依从性评估"], "monitoring": ["术后1/3/6/12个月随访，之后每年", "每次：症状、血压、心率、血脂、肝肾功能、血糖", "每年：心电图、心超、运动负荷", "非侵入检查不推荐常规频繁复查，有症状变化时查"], "special_populations": ["糖尿病：目标更严，LDL<1.4，血压<130/80", "CKD：ACEI/ARB护肾，造影前水化", "老年：注意出血风险，DAPT疗程个体化", "女性：症状不典型诊断延迟，同等治疗"], "references": "中华医学会心血管病学分会. 慢性冠脉综合征诊断和治疗指南(2024). 中华心血管病杂志", "py": "mxgmzhzzdhzlzn（"}, {"name": "中国心力衰竭诊断和治疗指南（2024）", "category": "心血管内科", "scope": "成人急慢性心衰诊断、分型评估、药物和非药物治疗。", "diagnosis": ["症状：呼吸困难、乏力、水肿、端坐呼吸、夜间阵发呼吸困难", "体征：颈静脉怒张、肺部啰音、心脏扩大、S3奔马律、肝大腹水", "BNP<35或NT-proBNP<125可排除慢性心衰；急性<300可排除", "心超：LVEF、心脏结构、瓣膜、舒张功能", "胸片：肺淤血、心影增大、胸腔积液"], "staging": ["A期：高危因素无结构异常", "B期：结构异常无症状", "C期：结构异常有/曾有症状", "D期：难治性终末期", "按LVEF：HFrEF≤40%、HFmrEF41-49%、HFpEF≥50%", "NYHA I-IV级"], "key_points": ["急性：利尿、扩血管、正性肌力，稳定后启动GDMT", "慢性HFrEF：四联(ARNI/ACEI+β阻滞剂+MRA+SGLT2i)均达目标量", "HFpEF：SGLT2i推荐，利尿剂缓解症状，治合并症", "非药物：限钠限水、体重监测、运动康复", "器械：CRT(LBBB+QRS>130+LVEF<35)、ICD", "终末期：LVAD、心脏移植、姑息"], "drug_recommendations": ["ARNI：沙库巴曲缬沙坦50mg bid起，每2-4周加倍，目标200mg bid", "β阻滞剂：比索洛尔/美托洛尔/卡维地洛，小剂量起每2-4周加倍", "MRA：螺内酯10-25mg qd(eGFR≥30,K<5.0)，起始后2-3天和1周查血钾肌酐", "SGLT2i：达格列净10mg qd或恩格列净10mg qd，所有HFrEF均推荐", "利尿剂：呋塞米20-40mg qd起，按体重水肿调整", "地高辛0.125-0.25mg qd：房颤室率快或症状仍明显", "血管扩张剂：肼苯哒嗪+硝酸异山梨酯(ACEI不耐受或非洲裔)"], "non_pharmacological": ["限钠：轻度<3g/d，中重度<2g/d", "限水：严重低钠(<130)或顽固水肿<1.5L/d", "每日体重：3天增>2kg提示液体潴留，加利尿剂", "运动康复：稳定期循序渐进，从床边活动开始", "戒烟限酒，肥胖者减重", "流感肺炎球菌疫苗，避免感染"], "complications": ["急性左心衰：端坐位、吸氧、吗啡2.5-5mg iv、呋塞米20-40mg iv、硝酸甘油静滴", "心源性休克：正性肌力(多巴酚丁胺/米力农)、血管活性药(去甲肾)、IABP/ECMO", "心律失常：房颤抗凝+控制室率，室速/室颤按ACLS", "肾功恶化：调整利尿剂和RAASi，避免肾毒性药", "电解质紊乱：低钾补钾，低钠限水"], "monitoring": ["稳定期每1-3个月：症状、体重、血压、心率、电解质、肾功能", "BNP/NT-proBNP评估疗效预后", "心超每6-12个月复查", "6分钟步行、生活质量评估", "药物滴定期间密切监测血压心率血钾肌酐"], "special_populations": ["老年：小剂量起始缓慢滴定，注意体位性低血压和肾功能", "妊娠：禁用ACEI/ARB/ARNI/SGLT2i，用β阻滞剂(拉贝洛尔)、利尿剂、地高辛", "CKD：eGFR<30慎用MRA，SGLT2i在eGFR≥20可用", "房颤合并心衰：优先β阻滞剂控制室率，必要时地高辛"], "references": "中华医学会心血管病学分会. 中国心力衰竭诊断和治疗指南(2024). 中华心血管病杂志", "py": "zgxlsjzdhzlzn（"}, {"name": "心房颤动诊断和治疗中国指南（2024）", "category": "心血管内科", "scope": "成人房颤筛查、诊断、卒中预防、节律/心率控制和综合管理。", "diagnosis": ["心电图/监测记录到房颤(RR绝对不齐、无P波、f波)≥30秒", "阵发性<7天自行终止；持续性>7天；长程持续性>1年拟转复；永久性不再转复", "瓣膜性：中重度二尖瓣狭窄或机械瓣术后", "非瓣膜性：其他所有", "评估：经胸心超、甲功、肾功、血常规", "隐匿性：长程监测7天-3年"], "staging": ["CHA2DS2-VASc：心衰1、高血压1、年龄≥75=2、糖尿病1、卒中/TIA=2、血管病1、年龄65-74=1、女性1", "卒中风险：≥2(男)/≥3(女)需抗凝；1(男)/2(女)考虑抗凝", "HAS-BLED：高血压1、肝肾异常1-2、卒中1、出血1、INR不稳1、老年>65=1、药/酒1-2；≥3积极纠正可逆因素"], "key_points": ["非瓣膜性NOAC优先；瓣膜性必须华法林", "早期节律控制改善预后，导管消融一线", "心率控制：静息<80运动<110；宽松静息<110", "ABC路径：A抗凝避卒中、B更好症状控制、C合并症管理", "≥65岁常规心电图筛查，高危可穿戴设备", "左心耳封堵：抗凝禁忌或出血高危"], "drug_recommendations": ["NOAC：达比加群150mg bid(肌酐清除30-49用75)、利伐沙班20mg qd(15-49用15)、阿哌沙班5mg bid(≥80/体重≤60/肌酐≥133用2.5)、艾多沙班60mg qd", "华法林：2.5-3mg qd起，按INR调，目标2.0-3.0，每周至稳定后每月", "节律控制：胺碘酮0.2g tid×1周→bid×1周→qd维持；普罗帕酮150-300mg tid(无结构性心脏病)；索他洛尔80-160mg bid", "心率控制：美托洛尔47.5-190mg qd、地尔硫卓90-360mg/d分3次、地高辛0.125-0.25mg qd", "预激合并房颤：禁用腺苷/β阻滞剂/CCB/地高辛，首选电复律或普鲁卡因胺/伊布利特", "围术期桥接：NOAC一般不需；华法林高血栓风险(机械瓣/近期卒中)用低分子肝素桥接"], "non_pharmacological": ["导管消融：肺静脉隔离为基石，阵发性一线，持续性可考虑", "电复律：血流动力学不稳定立即；择期复律前抗凝≥3周或经食道超声排除血栓", "左心耳封堵：Watchman等，抗凝禁忌或出血高危", "外科迷宫：合并心脏手术时", "生活方式：减重、戒酒、避免咖啡因、治疗睡眠呼吸暂停(CPAP)、控制血压"], "complications": ["缺血性卒中：抗凝预防，急性期按卒中指南", "心动过速性心肌病：控制心率/节律后心功能可恢复", "血栓栓塞：肾/肠系膜/肢体系统性栓塞", "出血：抗凝相关出血，评估HAS-BLED纠正可逆因素，严重出血用拮抗剂(达比加群用依达赛珠单抗，Xa抑制剂用安德沙奈α)"], "monitoring": ["抗凝初期：每周查血常规肝肾功电解质", "华法林：INR每周至稳定后每月", "NOAC：肾功每6-12个月，eGFR<50每3个月", "心率/节律：心电图、动态心电图定期", "心超：每年评估心房大小心功能"], "special_populations": ["老年：NOAC优先，注意肾功和出血风险", "妊娠：瓣膜性用华法林，非瓣膜性用低分子肝素；禁用NOAC", "肥厚型心肌病：华法林抗凝(不论CHA2DS2-VASc)", "甲亢：β阻滞剂控制室率，治疗甲亢后多可转复"], "references": "中华医学会心血管病学分会. 心房颤动诊断和治疗中国指南(2024). 中华心血管病杂志", "py": "xfcdzdhzlzgzn（"}, {"name": "中国肺动脉高压诊断和治疗指南（2024）", "category": "心血管内科", "scope": "成人肺动脉高压(PH)诊断分类、危险分层和靶向治疗。", "diagnosis": ["右心导管：mPAP≥25mmHg(海平面静息)金标准；PAH还需PAWP≤15+PVR≥3WU", "心超筛查：三尖瓣反流速度>3.4或>2.9+其他PH征象", "病因筛查：自身抗体、HIV、肝功、甲功、BMPR2基因", "6MWD评估功能预后", "右心功能：BNP/NT-proBNP、心超(MRI更精确)", "CTEPH：V/Q扫描首选筛查，肺动脉造影确诊"], "staging": ["WHO功能分级：I无活动受限/II轻度受限/III明显受限/IV静息症状", "PAH危险分层：低危(<5%年死亡，6MWD>440、BNP<50、无心包积液、WHO I-II)、中危、高危(>10%)", "PH分类：1型动脉性(PAH)、2型左心疾病、3型肺病/缺氧、4型CTEPH、5型不明原因"], "key_points": ["一般治疗：氧疗、利尿、抗凝(特发性PAH)、避免妊娠/剧烈运动/高海拔", "PAH靶向：按危险分层选单药/联合", "低危单药口服；中危双药联合；高危三药+肠外前列环素", "CTEPH：肺动脉内膜剥脱术首选；不能手术者BPA或利奥西呱", "2型/3型：治原发病为主，靶向不常规推荐", "终末期：肺移植评估"], "drug_recommendations": ["内皮素受体拮抗剂：波生坦62.5mg bid×4周→125mg bid(监测肝功)、安立生坦5mg qd、马昔腾坦10mg qd", "PDE5抑制剂：西地那非20mg tid、他达拉非40mg qd、伐地那非5mg bid", "sGC激动剂：利奥西呱2.5mg tid起→最大2.5mg tid(PAH和CTEPH均可用)", "前列环素类：依前列醇2-16ng/kg/min持续静滴(高危)、曲前列尼尔(皮下/静滴/吸入)、伊洛前列素吸入5-20μg 6-9次/d、司来帕格0.2mg bid起→最大1.6mg bid", "利尿剂：呋塞米20-40mg qd按水肿调整", "氧疗：SpO2<91%时吸氧", "抗凝：特发性/遗传性PAH用华法林INR2.0-3.0"], "non_pharmacological": ["氧疗维持SpO2≥92%", "康复运动：专业指导下进行，避免过度劳累", "避免：妊娠(避孕)、高海拔、剧烈运动、感冒、吸烟", "心理支持：焦虑抑郁常见", "疫苗接种：流感、肺炎球菌", "营养支持避免营养不良"], "complications": ["右心衰：利尿、氧疗、靶向药，正性肌力(米力农/左西孟旦)", "心律失常：房扑房颤常见，控制室率+抗凝", "咯血：支气管动脉栓塞，防大咯血窒息", "晕厥：避免突然体位变化，评估靶向药调整"], "monitoring": ["每3-6个月：WHO分级、6MWD、BNP、心超", "右心导管：每1-2年或病情变化时", "肝功(波生坦)、血常规、肾功定期", "评估治疗反应和危险分层变化"], "special_populations": ["妊娠：PH妊娠死亡率高，严格避孕，意外妊娠多学科管理", "儿童：按体重调剂量，波生坦/西地那非可用", "结缔组织病相关PAH：同时治原发病"], "references": "中华医学会呼吸病学分会肺栓塞与肺血管病学组. 中国肺动脉高压诊断和治疗指南(2024). 中华结核和呼吸杂志", "py": "zgfdmgyzdhzlzn（"}, {"name": "慢性阻塞性肺疾病诊治指南（2024年修订版）", "category": "呼吸内科", "scope": "成人COPD诊断、评估、稳定期管理和急性加重处理。", "diagnosis": ["危险因素：吸烟(最主要)、职业粉尘/化学物、室内外空气污染、生物燃料", "持续症状：慢性咳嗽、咳痰、气短/呼吸困难", "肺功能：吸入支扩剂后FEV1/FVC<0.70为持续气流受限", "支扩试验：排除哮喘(改善>12%且>200ml提示哮喘)", "胸部CT：排除其他病，评估肺气肿类型", "评估合并症：心血管病、骨质疏松、抑郁、肺癌、代谢综合征"], "staging": ["GOLD肺功能：1级FEV1≥80%、2级50-79%、3级30-49%、4级<30%", "症状：CAT≥10或mMRC≥2为症状多", "急性加重：≥2次/年或≥1次住院为加重多", "分组：A(症状少加重少)、B(症状多加重少)、E(加重多不论症状)", "BODE指数：BMI、气流阻塞、呼吸困难、运动耐力评估预后"], "key_points": ["戒烟最有效，可延缓肺功能下降", "稳定期核心：支扩剂+肺康复+疫苗", "B组和E组基础用LABA+LAMA双支扩", "血嗜酸≥300或合并哮喘：加ICS三联", "急性加重：加支扩剂、全身激素、抗生素(有感染征象)、氧疗", "长期氧疗：静息SpO2≤88或PaO2≤55，>15h/d改善生存"], "drug_recommendations": ["A组：SABA(沙丁胺醇)按需，或LABA/LAMA维持", "B组：LABA+LAMA双支扩(茚达特罗/格隆溴铵、维兰特罗/乌美溴铵)", "E组：LABA+LAMA；嗜酸高加ICS三联(布地奈德/福莫特罗/格隆溴铵)", "急性加重：泼尼松龙40mg qd×5天；抗生素阿莫西林克拉维酸/大环内酯/呼吸喹诺酮5-7天", "雾化：沙丁胺醇2.5mg+异丙托溴铵0.5mg q4-6h", "氧疗：鼻导管1-2L/min，目标SpO2 88-92%(避免高氧致CO2潴留)", "祛痰：氨溴索30mg tid、乙酰半胱氨酸600mg bid"], "non_pharmacological": ["戒烟：药物(尼古丁替代/安非他酮/伐尼克兰)+行为干预", "肺康复：运动训练(下肢耐力+力量)、呼吸训练(缩唇/腹式)、教育、心理支持，6-8周", "营养支持：BMI<21增加蛋白热量", "疫苗：每年流感、肺炎球菌、新冠", "避免空气污染职业暴露，室内通风", "长期家庭氧疗和无创通气(CO2潴留者)"], "complications": ["急性加重：最常见，感染为主要诱因", "呼吸衰竭：II型呼衰，无创通气BiPAP，必要时插管", "肺心病/右心衰：利尿、氧疗，避免过度利尿", "气胸：肺大疱破裂，胸腔闭式引流", "骨质疏松：长期激素活动少，补钙维D，双膦酸盐"], "monitoring": ["稳定期每3-6个月：症状、急性加重、肺功能", "每年肺功能1次", "急性加重后4-6周复查评估恢复和治疗调整", "CAT/mMRC定期评估", "药物吸入技术检查纠正"], "special_populations": ["哮喘-COPD重叠(ACO)：ICS+LABA基础按哮喘管理", "老年：注意吸入装置选择(干粉需吸气流速)，简化方案", "合并心血管病：β阻滞剂心脏选择性可用，非选择性禁用", "肺癌筛查：长期吸烟者低剂量CT每年"], "references": "中华医学会呼吸病学分会. 慢性阻塞性肺疾病诊治指南(2024修订版). 中华结核和呼吸杂志", "py": "mxzsxfjbzzzn（nxdb）"}, {"name": "支气管哮喘防治指南（2024年版）", "category": "呼吸内科", "scope": "成人和儿童哮喘诊断、评估和长期管理。", "diagnosis": ["反复发作喘息/气急/胸闷/咳嗽，夜间/凌晨多发，可变呼气气流受限", "支扩试验阳性(FEV1改善>12%且>200ml)或PEF变异率>10%", "激发试验阳性(乙酰甲胆碱/组胺)", "呼出气一氧化氮(FeNO)升高提示嗜酸粒细胞性炎症", "过敏原检测：皮肤点刺或血清sIgE", "排除其他原因(COPD、心衰、气道异物)"], "staging": ["控制水平：良好控制/部分控制/未控制", "GINA阶梯：1-5级，按控制水平升/降级", "严重程度：治疗后控制水平反映(轻度/中度/重度)", "急性发作严重度：轻度/中度/重度/危重", "未来风险：急性加重、肺功能下降、药物不良反应", "表型：嗜酸粒细胞型、中性粒细胞型、少炎症型、肥胖相关型"], "key_points": ["GINA推荐所有成人/青少年首选含ICS的治疗方案", "5级阶梯治疗，根据控制水平升/降级", "急性发作：评估严重度，反复吸入SABA，全身激素，氧疗，必要时机械通气", "治疗目标：良好症状控制，维持正常活动，减少未来风险", "识别并避免诱因和过敏原", "患者教育和吸入技术是关键"], "drug_recommendations": ["第1-2级：低剂量ICS-福莫特罗按需(GINA推荐)，或低剂量ICS每天+SABA按需", "第3级：低剂量ICS-LABA维持+SABA按需，或低剂量ICS-福莫特罗维持+缓解", "第4级：中/高剂量ICS-LABA维持+SABA按需", "第5级：高剂量ICS-LABA+LAMA；评估生物制剂(抗IgE奥马珠单抗、抗IL-5美泊利单抗/瑞利珠单抗、抗IL-4Rα度普利尤单抗)", "急性发作：沙丁胺醇雾化q20min×3次；甲泼尼龙40mg iv/口服；重症加硫酸镁2g iv 20min", "重度发作：PaCO2升高、意识改变、呼吸衰竭→气管插管机械通气"], "non_pharmacological": ["避免过敏原：尘螨(防螨床罩、热水洗)、花粉(季节防护)、宠物、霉菌", "避免触发：烟雾、冷空气、剧烈运动(运动前吸入SABA)、阿司匹林/NSAIDs(阿司匹林哮喘)", "呼吸训练：缩唇呼吸、腹式呼吸", "适度运动：游泳、散步，避免剧烈运动", "体重管理：肥胖哮喘减重改善控制", "疫苗：流感、肺炎球菌"], "complications": ["哮喘持续状态：雾化SABA+激素+氧疗，无效插管", "气胸/纵隔气肿：严重发作，胸腔闭式引流", "呼吸衰竭：II型呼衰，无创或有创通气", "慢阻肺重叠(ACO)：按更积极的哮喘方案治疗", "药物不良反应：ICS口腔念珠菌(漱口)、声音嘶哑；SABA心悸手抖；生物制剂注射反应"], "monitoring": ["控制良好每3-6个月随访，未控制每2-4周", "每次：症状、急性加重、吸入技术、峰流速(PEF)", "FeNO、血嗜酸粒细胞评估表型和治疗反应", "肺功能每年1-2次", "评估治疗依从性和环境控制"], "special_populations": ["妊娠：ICS(布地奈德首选)+SABA，避免白三烯调节剂，控制不佳危害大于药物", "儿童：5岁以下用吸入储雾罐，ICS剂量按年龄", "老年：注意吸入技术和合并症，简化方案", "职业性哮喘：避免职业暴露是关键，早期脱离改善预后", "阿司匹林哮喘：白三烯调节剂效果好，禁用阿司匹林和NSAIDs"], "references": "中华医学会呼吸病学分会哮喘学组. 支气管哮喘防治指南(2024). 中华结核和呼吸杂志", "py": "zqgxcfzzn（nb）"}, {"name": "中国成人社区获得性肺炎诊断和治疗指南（2024）", "category": "呼吸内科", "scope": "成人社区获得性肺炎(CAP)诊断、严重程度评估和抗感染治疗。", "diagnosis": ["新发肺部浸润影(胸片/CT)+咳嗽咳痰/发热/胸痛/呼吸困难", "白细胞异常(>10或<4×10⁹/L)，伴或不伴核左移", "排除其他原因(肺结核、肺癌、肺水肿、肺栓塞、非感染性间质性肺病)", "病原学：痰培养、血培养、尿抗原(肺炎链球菌/军团菌)、呼吸道病毒核酸、非典型病原体抗体/核酸", "重症评估：CURB-65(意识/尿素>7/呼吸≥30/血压<90/60/年龄≥65)、PSI评分", "影像学：CT比胸片敏感，尤其老年和免疫低下者"], "staging": ["CURB-65：0-1分门诊，2分住院，≥3分考虑ICU", "PSI：I-II级门诊，III-IV级住院，V级ICU", "重症肺炎标准(任一)：需要有创机械通气；感染性休克需血管活性药", "次要标准(≥3条考虑重症)：呼吸≥30、氧合指数≤250、多肺叶浸润、意识障碍、BUN≥7、WBC<4、PLT<10、体温<36、低血压需液体复苏"], "key_points": ["尽早经验性抗感染：首剂4小时内(重症1小时内)", "根据治疗场所和危险因素选择抗生素", "疗程：一般5-7天，非典型10-14天，金葡/铜绿14-21天", "预防：流感疫苗、肺炎球菌疫苗", "支持治疗：氧疗、补液、营养、化痰", "疗效评估：用药48-72小时评估，72小时无改善考虑换药或进一步检查"], "drug_recommendations": ["门诊无基础病：阿莫西林0.5g tid或多西环素0.1g bid或大环内酯(当地耐药低时)", "门诊有基础病/近3月用抗生素：阿莫西林克拉维酸0.625g tid或呼吸喹诺酮(左氧氟沙星0.5g qd/莫西沙星0.4g qd)，或头孢+大环内酯", "住院非ICU：β内酰胺类(头孢曲松2g qd/头孢噻肟)+大环内酯(阿奇霉素0.5g qd)，或呼吸喹诺酮单药", "ICU：β内酰胺类+大环内酯/呼吸喹诺酮；怀疑铜绿用抗假单胞菌β内酰胺(哌拉西林他唑巴坦4.5g q6h/头孢吡肟2g q8h/亚胺培南)", "重症：联合治疗覆盖非典型，必要时覆盖MRSA(万古霉素/利奈唑胺)", "流感季节怀疑流感病毒性肺炎：奥司他韦75mg bid×5天(48h内最佳，重症超过48h仍用)"], "non_pharmacological": ["氧疗：鼻导管/面罩，目标SpO2 90-94%(COPD 88-92%)", "补液：脱水者静脉补液，心功能不全者限制", "化痰排痰：体位引流、拍背、雾化吸入", "营养支持：肠内营养优先，重症不能进食者肠外", "休息，多饮水，清淡饮食", "物理降温(高热时)"], "complications": ["胸腔积液/脓胸：抗感染+胸腔穿刺引流，脓胸需充分引流+胸膜剥脱", "肺脓肿：延长抗生素疗程，体位引流，必要时手术", "呼吸衰竭：I型/II型呼衰，无创或有创通气", "感染性休克：液体复苏+血管活性药+广谱抗生素，ICU", "多器官功能衰竭：ICU综合支持"], "monitoring": ["用药48-72小时评估：体温、呼吸、心率、血压、血氧、白细胞、影像学", "治疗有效：体温下降、症状改善、白细胞下降", "72小时无改善：复查CT、考虑耐药/特殊病原/并发症，调整抗生素", "疗程结束评估临床治愈，不推荐常规复查胸片", "血培养阳性者复查至阴性"], "special_populations": ["老年：症状不典型(可无发热，仅表现意识改变/食欲差)，CURB-65年龄加分，注意肾功调剂量", "孕妇：青霉素/头孢类安全，避免四环素/喹诺酮，重症需住院", "免疫低下(激素/肿瘤/移植)：覆盖特殊病原(真菌、肺孢子菌、巨细胞病毒)，尽早支气管镜检查", "吸入风险(卒中/痴呆)：覆盖厌氧菌，阿莫西林克拉维酸或克林霉素"], "references": "中华医学会呼吸病学分会. 中国成人社区获得性肺炎诊断和治疗指南(2024). 中华结核和呼吸杂志", "py": "zgcrsqhdxfyzdhzlzn（"}, {"name": "肺血栓栓塞症诊治与预防指南（2024）", "category": "呼吸内科", "scope": "成人急性肺血栓栓塞症(PTE)诊断、危险分层和治疗。", "diagnosis": ["疑诊：Wells评分/Geneva评分评估临床可能性；D-二聚体排除低危(年龄校正值)", "确诊：CT肺动脉造影(CTPA)首选；通气灌注扫描(V/Q)；肺动脉造影", "危险分层：高危(休克/低血压)、中危(右心功能不全+心肌损伤)、低危", "右心功能：心超(右室扩大/运动减弱)、CT(右室/左室直径比>0.9)", "心肌损伤：肌钙蛋白升高、BNP/NT-proBNP升高", "下肢静脉超声：寻找DVT证据"], "staging": ["高危：休克或低血压(收缩压<90或下降≥40持续>15min)，需立即再灌注", "中危：无休克低血压，但右心功能不全+心肌损伤；中高危(两者都有)需密切监测，中低危(其一)", "低危：无休克低血压，无右心功能不全和心肌损伤", "PESI/sPESI评分评估30天死亡风险", "抗凝疗程：3个月基础，根据诱因和复发风险决定延长"], "key_points": ["高危：立即再灌注(溶栓/取栓)+抗凝", "中低危：抗凝治疗，住院观察", "低危：可门诊抗凝治疗", "NOAC优先于华法林(除非瓣膜病/妊娠)", "下腔静脉滤器：抗凝禁忌或抗凝中复发", "慢性血栓栓塞性肺动脉高压(CTEPH)：肺动脉内膜剥脱术/BPA/靶向药"], "drug_recommendations": ["初始抗凝：低分子肝素(依诺肝素1mg/kg q12h)或磺达肝癸钠(体重<50:5mg,50-100:7.5mg,>100:10mg qd)或普通肝素(APTT调整)", "NOAC：利伐沙班15mg bid×21天→20mg qd；阿哌沙班10mg bid×7天→5mg bid；达比加群150mg bid(先胃肠外抗凝5天)；艾多沙班60mg qd(先胃肠外5天)", "华法林：与胃肠外重叠≥5天，INR 2.0-3.0，瓣膜性房颤/妊娠用", "溶栓：阿替普酶50-100mg 2h静滴，或尿激酶2万U/kg 2h静滴(高危)", "介入：导管碎栓/取栓/溶栓(溶栓禁忌或失败)", "疗程：可逆诱因3个月；特发性/持续危险因素≥6个月评估长期；肿瘤用低分子肝素或NOAC长期"], "non_pharmacological": ["卧床休息(急性期)，避免用力排便，患肢抬高(DVT)", "吸氧：低氧血症者", "下肢DVT：避免按摩挤压患肢，防止血栓脱落", "梯度压力弹力袜：DVT后预防血栓后综合征(PTS)", "早期活动：抗凝充分后可早期下床，不增加PE风险", "预防：术后早期活动、低分子肝素预防、间歇充气加压"], "complications": ["出血：抗凝相关，评估HAS-BLED，纠正可逆因素，严重出血用拮抗剂/输血", "肺动脉高压(CTEPH)：抗凝+评估手术/BPA/靶向药", "右心衰竭：利尿、氧疗、正性肌力药", "复发：评估抗凝依从性、恶性肿瘤、易栓症，延长/加强抗凝", "血栓后综合征(PTS)：下肢肿胀疼痛色素沉着，弹力袜+运动"], "monitoring": ["抗凝初期：每周查血常规、肝肾功能、电解质、大便潜血", "华法林：INR每周至稳定后每月", "NOAC：肾功每6-12个月，eGFR<50每3个月", "抗凝3个月评估：复发风险、出血风险、是否延长", "心超/CTPA：评估右心恢复和CTEPH"], "special_populations": ["妊娠：低分子肝素抗凝(不通过胎盘)，禁用华法林和NOAC，产后可换华法林(哺乳安全)", "恶性肿瘤：低分子肝素或NOAC长期抗凝，直至肿瘤缓解", "老年：注意肾功能和出血风险，NOAC按肌酐清除率调剂量", "严重肾功能不全(eGFR<30)：普通肝素或低分子肝素(监测抗Xa)，慎用NOAC"], "references": "中华医学会呼吸病学分会. 肺血栓栓塞症诊治与预防指南(2024). 中华结核和呼吸杂志", "py": "fxssszzzyyfzn（"}, {"name": "中国支气管扩张症诊断和治疗指南（2024）", "category": "呼吸内科", "scope": "成人支气管扩张症诊断、病因评估和治疗。", "diagnosis": ["慢性咳嗽、大量脓痰、反复咯血", "胸部HRCT：印戒征(支气管直径>伴行肺动脉)、双轨征、囊状扩张", "病因评估：既往感染(结核/百日咳/麻疹)、免疫缺陷(IgG/IgA/IgM)、囊性纤维化(汗液氯试验/基因)、纤毛运动障碍(鼻纤毛活检)、变应性支气管肺曲霉病(ABPA)、类风湿等结缔组织病", "痰培养：常规细菌+真菌+分枝杆菌，铜绿假单胞菌定植重要", "肺功能：阻塞性通气功能障碍常见", "严重程度：BSI评分、FACED评分"], "staging": ["严重程度评估：BSI评分(年龄、FEV1、BMI、既往住院、铜绿定植、大咯血、影像学累及范围)", "急性加重：痰量增加/脓性痰/呼吸困难加重，持续≥48小时", "稳定期：症状稳定", "铜绿假单胞菌定植：连续2次痰培养阳性(间隔>3个月)，提示预后差", "ABPA：哮喘+嗜酸高+曲霉sIgE/总IgE高+中心性支气管扩张+黏液栓"], "key_points": ["气道廓清是基础，每天1-2次", "长期抗生素：铜绿定植用大环内酯类或吸入抗生素", "急性加重：根据痰培养和既往用药选抗生素", "手术：局限病变+反复感染/咯血可手术切除", "咯血处理：少量止血药，大咯血介入栓塞或手术", "预防加重：疫苗、戒烟、避免感染"], "drug_recommendations": ["气道廓清：体位引流、拍背、主动循环呼吸技术(ACBT)、振荡呼气正压装置(Flutter/Acapella)", "急性加重抗生素：无铜绿风险阿莫西林克拉维酸0.625g tid或头孢曲松2g qd；有铜绿风险环丙沙星0.5-0.75g bid口服或头孢他啶2g q8h/哌拉西林他唑巴坦4.5g q6h iv", "长期口服抗生素：铜绿定植用阿奇霉素250mg 每周3次或红霉素500mg bid(注意耐药和听力)", "吸入抗生素：妥布霉素吸入溶液300mg bid(每月交替)或多黏菌素吸入(铜绿定植反复加重)", "祛痰：氨溴索30mg tid、乙酰半胱氨酸600mg bid、羧甲司坦0.5g tid", "支气管扩张剂：合并气道阻塞用LABA/LAMA", "咯血：氨甲环酸0.5g iv/口服；大咯血垂体后叶素5-10U+5%GS 250ml静滴，或支气管动脉栓塞"], "non_pharmacological": ["气道廓清技术：每天1-2次，每次20-30分钟", "运动锻炼：有氧+力量训练，改善运动耐力和生活质量", "营养支持：消瘦者增加蛋白热量", "戒烟，避免烟雾和空气污染", "疫苗：每年流感、肺炎球菌、新冠", "避免呼吸道感染，勤洗手，感染期隔离"], "complications": ["反复感染急性加重：最常见，铜绿定植者更频繁", "咯血：常见，大咯血可窒息死亡，需紧急处理", "呼吸衰竭：晚期II型呼衰，无创通气", "肺心病/右心衰：长期缺氧肺动脉高压所致", "继发真菌感染(曲霉球)：咯血常见，抗真菌或手术"], "monitoring": ["稳定期每3-6个月：症状、急性加重次数、痰培养、肺功能", "每年肺功能1次", "急性加重后4-6周复查", "痰培养：每年1-2次或急性加重时", "评估气道廓清技术掌握情况"], "special_populations": ["儿童：囊性纤维化和原发性纤毛运动障碍需排查，长期随访", "ABPA：口服激素(泼尼松0.5mg/kg/d渐减)+抗真菌(伊曲康唑200mg bid)，目标总IgE下降35-50%", "免疫缺陷：IVIG替代治疗，积极抗感染", "老年：注意吸入装置和排痰能力，简化方案"], "references": "中华医学会呼吸病学分会. 中国支气管扩张症诊断和治疗指南(2024). 中华结核和呼吸杂志", "py": "zgzqgkzzzdhzlzn（"}, {"name": "中国急性胰腺炎诊治指南（2024）", "category": "消化内科", "scope": "成人急性胰腺炎诊断、严重程度分级和治疗。", "diagnosis": ["急性、持续中上腹痛(可向背部放射)", "血清淀粉酶/脂肪酶>正常上限3倍", "影像学(CT/MRI/超声)典型改变(胰腺肿大、胰周渗出)", "满足2项即可诊断", "病因：胆石症(最常见)、酒精、高甘油三酯(>11.3mmol/L)、药物、ERCP术后、自身免疫", "增强CT：发病72小时后评估胰腺坏死"], "staging": ["轻症(MAP)：无器官衰竭，无局部/全身并发症，占80-85%", "中重症(MSAP)：一过性器官衰竭(≤48h)或局部/全身并发症", "重症(SAP)：持续性器官衰竭(>48h)，占10-20%，死亡率高", "器官衰竭：改良Marshall评分≥2分(呼吸/循环/肾)", "局部并发症：急性胰周液体积聚(APFC)、急性坏死物积聚(ANC)、胰腺假性囊肿、包裹性坏死(WON)", "全身并发症：SIRS、脓毒症、腹腔间隔室综合征"], "key_points": ["轻症：禁食、补液、止痛，早期肠内营养(48h内)", "重症：ICU监护，器官功能支持，抗感染(感染性坏死)", "胆源性胰腺炎：有胆管炎/梗阻时急诊ERCP，无梗阻保守治疗后择期胆囊切除", "高甘油三酯性：胰岛素+肝素/血液净化降甘油三酯", "不推荐预防性使用抗生素", "手术：感染性坏死经皮/内镜引流失败后微创清创"], "drug_recommendations": ["补液：乳酸林格液或生理盐水，前24h 250-500ml/h，目标BUN下降、Hct正常", "止痛：哌替啶50-100mg im(避免吗啡Oddi括约肌痉挛)，或芬太尼", "止吐：甲氧氯普胺10mg iv、昂丹司琼8mg iv", "PPI：奥美拉唑40mg iv q12h(减少胃酸刺激胰液分泌)", "生长抑素：奥曲肽0.1mg iv后25μg/h持续泵入(重症)", "抗感染(感染性坏死)：碳青霉烯(亚胺培南0.5g q6h)或喹诺酮+甲硝唑，覆盖革兰阴性和厌氧菌", "高甘油三酯：胰岛素0.1-0.3U/kg/h+葡萄糖，或低分子肝素5000U q12h，目标TG<5.65"], "non_pharmacological": ["禁食：轻症可短期禁食，症状缓解后尽早开放饮食(清流→低脂半流)", "肠内营养：48h内经鼻空肠管开始，优于肠外营养", "补液：早期积极静脉补液是关键", "监测：生命体征、尿量、血氧、电解质、血糖", "腹腔高压：胃肠减压、肛管排气、血液滤过", "血液净化：重症伴肾衰/高甘油三酯/炎症反应综合征"], "complications": ["器官衰竭：呼吸(ARDS机械通气)、循环(休克血管活性药)、肾(血液滤过)", "感染性胰腺坏死：发热、白细胞升高、CT气泡征，抗生素+引流/清创", "假性囊肿：>6cm或有症状可内镜/经皮引流", "腹腔间隔室综合征：腹压>25mmHg+器官衰竭，减压", "胰瘘：生长抑素+引流，多可自愈"], "monitoring": ["入院24h内：每4-6h生命体征、尿量、血氧", "实验室：血常规、生化、淀粉酶、脂肪酶、凝血、血气", "增强CT：72h后评估坏死，2-3周复查评估并发症", "BISAP/Ranson评分评估严重度", "营养状态评估，白蛋白"], "special_populations": ["老年：症状不典型，并发症多，预后差，积极补液注意心功能", "妊娠：胆源性常见，保守治疗为主，避免CT，必要时ERCP(铅衣保护)", "免疫低下：感染风险高，早期抗生素，积极引流", "儿童：多为病毒/创伤/药物，治疗原则相同，剂量按体重"], "references": "中华医学会消化病学分会. 中国急性胰腺炎诊治指南(2024). 中华消化杂志", "py": "zgjxyxyzzzn（"}, {"name": "中国胃食管反流病诊疗指南（2024）", "category": "消化内科", "scope": "成人胃食管反流病(GERD)诊断和治疗，包括反流性食管炎(RE)、非糜烂性反流病(NERD)和Barrett食管。", "diagnosis": ["典型症状：烧心、反酸(每周≥2次)", "不典型：胸痛、吞咽困难、慢性咳嗽、喉炎、哮喘、牙蚀", "PPI试验：标准剂量PPI bid×1-2周，症状改善≥50%支持诊断", "胃镜：RE分级(LA-A/B/C/D)，排除溃疡/肿瘤/Barrett", "24h食管pH-阻抗监测：金标准，评估酸/非酸反流", "食管测压：排除贲门失弛缓，评估LES压力，术前评估"], "staging": ["RE洛杉矶分级：A(≥1处黏膜破损≤5mm)、B(>5mm不融合)、C(融合<75%周径)、D(融合≥75%周径)", "NERD：有症状但胃镜正常，pH监测异常", "功能性烧心：症状但pH监测正常，PPI无效", "Barrett食管：鳞状上皮被柱状上皮取代，伴/不伴肠化生，癌变风险", "并发症：出血、狭窄、Barrett食管、腺癌"], "key_points": ["PPI是首选药物，早餐前30分钟服用", "NERD：PPI 8周，按需维持", "RE：PPI 8周，C/D级或并发症需长期维持", "生活方式干预是基础", "难治性GERD：优化PPI→加H2RA/促动力药→评估手术", "Barrett食管：PPI+内镜监测，低级别异型增生可消融"], "drug_recommendations": ["PPI：奥美拉唑20mg、兰索拉唑30mg、泮托拉唑40mg、雷贝拉唑10-20mg、艾司奥美拉唑20-40mg，早餐前30min qd，重症bid", "H2受体拮抗剂：法莫替丁20mg bid(夜间酸突破，PPI睡前加用)", "促动力药：莫沙必利5mg tid、多潘立酮10mg tid(餐前15-30min)", "黏膜保护剂：铝碳酸镁1g tid(咀嚼，餐后1h)、硫糖铝1g qid", "维持治疗：PPI最低有效剂量按需或间歇，RE C/D级长期维持", "难治性：艾司奥美拉唑40mg bid，加巴氯芬10mg tid(减少TLESR)，评估手术"], "non_pharmacological": ["减重：BMI>25者减重可改善", "饮食：避免高脂、巧克力、咖啡、浓茶、辛辣、酸性食物，睡前3h不进食", "抬高床头15-20cm(不是垫高枕头)", "戒烟限酒", "避免紧身衣、弯腰、腹压增高", "右侧卧位睡眠(减少反流)"], "complications": ["反流性食管炎出血：PPI大剂量，内镜止血", "食管狭窄：扩张+PPI长期维持", "Barrett食管：PPI+内镜监测(每3-5年，低级别异型增生每6-12月，高级别内镜消融/手术)", "食管腺癌：Barrett+高级别异型增生风险，早期内镜治疗", "喉炎/哮喘/慢性咳嗽：PPI试验性治疗，有效则维持"], "monitoring": ["PPI治疗4-8周评估疗效", "RE治疗8周后复查胃镜(尤其C/D级)", "Barrett食管定期内镜监测+活检", "长期PPI：监测骨密度、维生素B12、镁、肾功能", "症状复发评估依从性和诱因"], "special_populations": ["老年：注意PPI长期使用风险(骨折、感染、肾损伤)，最低有效剂量", "妊娠：生活方式为主，必要时铝碳酸镁/硫糖铝，PPI(奥美拉唑)相对安全但尽量避免前3月", "儿童：多为生理性反流，病理性需评估，PPI按体重", "肥胖：减重是关键，手术可考虑胃底折叠+减重"], "references": "中华医学会消化病学分会. 中国胃食管反流病诊疗指南(2024). 中华消化杂志", "py": "zgwsgflbzlzn（"}, {"name": "炎症性肠病诊断与治疗的共识意见（2024）", "category": "消化内科", "scope": "成人溃疡性结肠炎(UC)和克罗恩病(CD)的诊断和治疗。", "diagnosis": ["UC：持续或反复发作腹泻、黏液脓血便、腹痛，里急后重", "CD：腹痛、腹泻、体重下降、瘘管、肛周病变", "结肠镜+活检：UC连续弥漫性黏膜炎症从直肠向近端延伸；CD节段性、纵行溃疡、鹅卵石样、非干酪样肉芽肿", "小肠评估：CTE/MRE(CD)、胶囊内镜、小肠镜", "粪便钙卫蛋白：鉴别IBD和IBS，评估活动度", "排除感染(艰难梭菌、阿米巴、结核)、缺血性肠炎、肠结核"], "staging": ["UC活动度：改良Mayo评分(排便次数、便血、内镜、医师评估)，轻度≤2、中度3-5、重度6-10、暴发性>10", "UC范围：E1直肠、E2左半结肠、E3广泛结肠", "CD活动度：CDAI评分(<150缓解、150-220轻度、220-450中度、>450重度)", "CD部位：L1回肠末段、L2结肠、L3回结肠、L4上消化道；行为：B1非狭窄非穿透、B2狭窄、B3穿透、肛周P", "高危因素：CD年轻发病、广泛病变、深溃疡、肛周病变、吸烟"], "key_points": ["UC：5-ASA是轻中度基础，激素用于中重度急性发作，免疫抑制剂/生物制剂用于激素依赖/抵抗", "CD：早期使用免疫抑制剂/生物制剂(降阶梯)，激素不用于维持", "营养支持：CD尤其重要，肠内营养可诱导缓解", "手术：UC全结肠切除可治愈；CD手术切除病变但复发率高", "定期监测：UC病程>8年需结肠镜筛查癌变", "患者教育：戒烟(CD)、饮食、依从性"], "drug_recommendations": ["UC轻中度：美沙拉嗪2-4g/d分3-4次口服+栓剂1g qn(直肠炎)，8周评估", "UC中重度急性：甲泼尼龙40-60mg iv qd或泼尼松40-60mg po qd，5-7天评估，有效渐减", "UC激素抵抗：环孢素2mg/kg/d iv或英夫利昔单抗5mg/kg(0/2/6周)", "UC维持：美沙拉嗪2g/d长期，硫唑嘌呤50-100mg qd(激素依赖)，生物制剂维持", "CD诱导：全肠内营养(EEN)或激素(泼尼松40mg qd)，中重度首选生物制剂(英夫利昔5mg/kg或阿达木单抗160/80mg)", "CD维持：硫唑嘌呤1.5-2.5mg/kg/d或甲氨蝶呤15-25mg/w或生物制剂，激素不维持", "生物制剂：抗TNF(英夫利昔/阿达木)、抗整合素(维得利珠单抗)、抗IL-12/23(乌司奴单抗)、JAK抑制剂(托法替布)"], "non_pharmacological": ["营养：CD活动期全肠内营养(EEN)可诱导缓解，尤其儿童；缓解期高营养饮食", "戒烟：CD必须戒烟(加重病情和复发)，UC吸烟可能有保护但不推荐", "饮食：个体化，避免不耐受食物，活动期低渣饮食，缓解期均衡", "心理支持：焦虑抑郁常见，影响依从性和预后", "疫苗接种：免疫抑制前接种乙肝、HPV、流感、肺炎球菌，避免活疫苗", "康复：适度运动，维持体重"], "complications": ["UC中毒性巨结肠：禁食、胃肠减压、激素、抗感染，无效急诊手术", "CD瘘管/脓肿：脓肿先引流，生物制剂治疗瘘管", "CD狭窄：内镜扩张或手术", "肠穿孔：急诊手术", "癌变：UC病程>8年每年结肠镜+活检，CD结肠广泛病变同样筛查", "营养不良：定期评估，补充铁、维生素B12、维生素D、锌"], "monitoring": ["活动期每2-4周评估症状、粪便钙卫蛋白", "缓解期每3-6个月随访", "结肠镜：UC治疗8-12周复查评估黏膜愈合，之后按风险定期筛查", "硫唑嘌呤：监测血常规、肝功能(前8周每2周，之后每3月)", "生物制剂：治疗前筛查结核、乙肝，定期评估疗效和抗药抗体", "营养指标：白蛋白、铁蛋白、维生素B12、维生素D"], "special_populations": ["儿童青少年：EEN是CD一线诱导，影响生长发育需积极治疗，生物制剂可用", "妊娠：缓解期受孕风险低，5-ASA/硫唑嘌呤/抗TNF孕期可继续，甲氨蝶呤禁用", "老年：注意感染风险，生物制剂和免疫抑制剂谨慎，合并症多", "肛周CD：抗生素(甲硝唑/环丙沙星)+生物制剂+外科引流，多学科"], "references": "中华医学会消化病学分会炎症性肠病学组. 炎症性肠病诊断与治疗的共识意见(2024). 中华消化杂志", "py": "yzxcbzdyzldgsyj（"}, {"name": "中国2型糖尿病防治指南（2024年版）", "category": "内分泌科", "scope": "成人2型糖尿病筛查、诊断、治疗和并发症管理。", "diagnosis": ["糖尿病症状(多饮多尿多食体重下降)+随机血糖≥11.1", "空腹血糖≥7.0mmol/L(空腹≥8h)", "OGTT 2h血糖≥11.1mmol/L", "HbA1c≥6.5%", "无典型症状需改日复查确认", "分型：1型(自身免疫、胰岛素绝对缺乏)、2型(胰岛素抵抗+分泌不足)、特殊类型、妊娠糖尿病"], "staging": ["HbA1c目标：一般<7%，年轻/无并发症<6.5%，老年/并发症多<7.5-8%", "糖尿病前期：IFG(空腹6.1-6.9)、IGT(OGTT 2h 7.8-11.0)、HbA1c 5.7-6.4%", "并发症分期：糖尿病肾病(G1-G5/A1-A3)、视网膜病变(I-VI期)、神经病变、下肢动脉病变、足病(0-5级Wagner)", "心血管风险分层：极高危(ASCVD/CKD/靶器官损害)、高危、中危"], "key_points": ["生活方式干预贯穿全程，是基础", "二甲双胍是2型糖尿病一线首选，贯穿全程", "合并ASCVD/心衰/CKD：不论HbA1c，优先SGLT2i或GLP-1RA", "血糖控制目标个体化，避免低血糖", "综合管理：血糖、血压、血脂、抗血小板、体重", "定期筛查并发症：每年眼底、尿微量白蛋白、足部、神经"], "drug_recommendations": ["二甲双胍：0.5g bid起，渐加至1-2g/d分2-3次，最大2g/d(餐中服减少胃肠反应)", "SGLT2i：达格列净10mg qd、恩格列净10mg qd、卡格列净100mg qd(合并心衰/CKD优先，eGFR≥20可用)", "GLP-1RA：利拉鲁肽0.6→1.2-1.8mg qd皮下、司美格鲁肽0.25→0.5-1.0mg qw、度拉糖肽1.5mg qw(减重/心血管获益)", "DPP-4i：西格列汀100mg qd、沙格列汀5mg qd、利格列汀5mg qd(肾功能不全不需调量)", "磺脲类：格列美脲1-4mg qd、格列齐特80-160mg bid(低血糖风险，老年慎用)", "胰岛素：基础胰岛素(甘精/地特10U qn起始，按空腹调)、预混胰岛素(门冬30 bid)、强化治疗(三餐短效+睡前基础)", "血压目标<130/80，ACEI/ARB首选；LDL-C目标极高危<1.4，他汀+依折麦布+PCSK9i"], "non_pharmacological": ["医学营养治疗：控制总热量，碳水50-65%、蛋白15-20%、脂肪20-30%，低GI饮食", "运动：每周≥150分钟中等强度有氧+2次抗阻，避免空腹运动防低血糖", "减重：超重/肥胖者减重5-10%显著改善代谢", "戒烟限酒", "自我血糖监测：空腹+餐后2h，胰岛素治疗者更频繁", "糖尿病教育：饮食、运动、用药、低血糖识别、足部护理"], "complications": ["糖尿病酮症酸中毒(DKA)：补液(生理盐水前2h 1-2L)、小剂量胰岛素0.1U/kg/h、补钾、纠正诱因", "高渗高血糖状态(HHS)：补液(更大量)、小剂量胰岛素、抗凝", "低血糖：<3.9mmol/L，意识清楚口服15g糖，意识障碍静脉50%GS 40ml", "糖尿病肾病：ACEI/ARB，SGLT2i，控制血压<130/80，低蛋白饮食0.8g/kg/d", "糖尿病视网膜病变：控制血糖血压，激光光凝/抗VEGF注射", "糖尿病足：减压、抗感染、血运重建、清创，严重者截肢"], "monitoring": ["HbA1c：每3个月(稳定后每6个月)", "血糖：空腹/餐后/睡前，胰岛素治疗者更频繁", "每年：眼底检查、尿微量白蛋白/肌酐比、足部检查、神经病变检查、血脂、肝肾功能、心电图", "血压每次就诊测量", "体重/BMI定期"], "special_populations": ["老年(≥65岁)：目标放宽HbA1c<7.5-8%，避免低血糖，优先低血糖风险低的药物(二甲双胍/DPP-4i/SGLT2i)", "妊娠：胰岛素治疗(门冬/赖脯+地特/甘精)，目标空腹<5.3、餐后1h<7.8、2h<6.7，禁用口服降糖药", "儿童青少年2型：生活方式+二甲双胍，不达标加胰岛素，关注代谢综合征", "CKD：eGFR<30二甲双胍禁用，SGLT2i在eGFR≥20可用，胰岛素按肾功调量"], "references": "中华医学会糖尿病学分会. 中国2型糖尿病防治指南(2024). 中华糖尿病杂志", "py": "zg2xtnbfzzn（nb）"}, {"name": "中国甲状腺功能亢进症诊治指南（2024）", "category": "内分泌科", "scope": "成人甲状腺功能亢进症(甲亢)诊断和治疗，主要为Graves病。", "diagnosis": ["高代谢症状：怕热多汗、心悸、手抖、体重下降、易激动、月经紊乱", "体征：甲状腺肿大、突眼、胫前黏液水肿、心率快", "TSH降低+FT3/FT4升高(原发性甲亢)", "TSH升高+FT3/FT4升高(中枢性甲亢，罕见)", "病因鉴别：Graves病(TRAb阳性、弥漫性甲状腺肿、突眼)、毒性结节性甲状腺肿、甲状腺炎(破坏性甲亢，摄碘率低)", "甲状腺摄碘率：Graves病升高，甲状腺炎降低", "甲状腺超声：Graves弥漫性增大血流丰富(火海征)"], "staging": ["Graves眼病(GO)：活动期(CAS≥3分)、非活动期；严重度分级(轻度/中重度/威胁视力)", "甲亢性心脏病：房颤、心衰、心脏扩大", "甲亢危象：高热>39℃、心率>140、大汗、谵妄/昏迷、呕吐腹泻，死亡率高", "妊娠期甲亢：孕早期HCG相关一过性甲亢(需鉴别)、Graves病", "药物不良反应：粒细胞缺乏(0.1-0.5%)、肝损伤、皮疹、血管炎(PTU)"], "key_points": ["三种治疗：抗甲状腺药物(ATD)、放射性碘(RAI)、手术，根据患者选择", "ATD首选：甲巯咪唑(MMI)，妊娠早期/甲亢危象用丙硫氧嘧啶(PTU)", "疗程12-18个月，TRAb转阴后可停药", "RAI：适用于ATD失败/复发、甲状腺肿大、合并心脏病，禁忌妊娠/哺乳/活动期GO", "手术：甲状腺明显肿大有压迫、怀疑恶性、药物无效", "甲亢危象：PTU+碘剂+普萘洛尔+激素+降温+支持治疗"], "drug_recommendations": ["MMI：起始10-30mg/d分1-3次，4-8周减至维持5-10mg/d，疗程12-18月", "PTU：起始50-100mg tid，维持50-100mg/d(妊娠早期/危象首选)", "β阻滞剂：普萘洛尔10-40mg tid或美托洛尔25-50mg bid(控制心率，支气管哮喘/心衰慎用)", "碘剂：复方碘溶液(Lugol液)5-10滴tid(术前准备/危象，ATD后1h用，不超过2周)", "糖皮质激素：GO活动期泼尼松40-60mg qd渐减，或甲泼尼龙500mg iv每周×6周", "甲亢危象：PTU 500-1000mg负荷后250mg q4h、碘剂1h后、普萘洛尔60-80mg q4-6h、氢化可的松100mg q8h、降温(避免阿司匹林)"], "non_pharmacological": ["低碘饮食：避免海带紫菜海鱼，用无碘盐", "休息，避免劳累和精神刺激", "补充营养：高蛋白高热量高维生素，补充维生素B族", "戒烟：GO患者必须戒烟(加重突眼)", "眼部护理：戴墨镜、人工泪液、夜间眼膏，高枕卧位", "定期复查，遵医嘱不自行停药"], "complications": ["甲亢危象：紧急处理，死亡率20-30%", "甲亢性心脏病：控制甲亢后多可恢复，房颤需抗凝", "GO活动期：激素/放疗，威胁视力需眼眶减压手术", "粒细胞缺乏：发热咽痛立即查血常规，WBC<3或中性粒<1.5停药，升白细胞+抗感染", "肝损伤：MMI胆汁淤积，PTU肝细胞坏死，严重者停药换治疗方式", "低钾性周期性麻痹：男性亚洲人多见，补钾+β阻滞剂，控制甲亢后减少发作"], "monitoring": ["ATD治疗初期：每2-4周查甲功、血常规、肝功能", "甲功正常后每1-3个月复查", "TRAb：治疗6-12个月评估，停药前查(转阴可停)", "RAI后：每4-6周查甲功，监测甲减发生", "术后：查甲功、甲状旁腺功能(血钙)、声带", "GO：CAS评分、视力、突眼度"], "special_populations": ["妊娠：孕早期PTU，孕中晚期MMI，目标FT4正常上限，最小有效剂量，避免甲减影响胎儿神经发育", "哺乳期：MMI<20mg/d安全，哺乳后服药", "儿童青少年：ATD首选，疗程更长(2-3年)，缓解率低，RAI慎用", "老年：症状不典型(淡漠型甲亢)，房颤多见，积极治疗，注意药物剂量", "GO活动期：RAI可加重GO，需激素预防，优先ATD或手术"], "references": "中华医学会内分泌学分会. 中国甲状腺功能亢进症诊治指南(2024). 中华内分泌代谢杂志", "py": "zgjzxgnkjzzzzn（"}, {"name": "中国高尿酸血症与痛风诊疗指南（2024）", "category": "内分泌科", "scope": "成人高尿酸血症和痛风诊断、治疗和管理。", "diagnosis": ["高尿酸血症：非同日2次空腹血尿酸>420μmol/L(男)/>360μmol/L(女)", "痛风急性发作：关节红肿热痛，第一跖趾关节最常见，夜间突发", "痛风石：耳廓、关节周围皮下结节", "关节液/痛风石穿刺：尿酸盐结晶(针状、负性双折光)为金标准", "影像学：双能CT显示尿酸盐沉积，超声双轨征", "排除化脓性关节炎、假性痛风(焦磷酸钙结晶)、类风湿关节炎"], "staging": ["高尿酸血症：无症状期", "急性痛风性关节炎：反复发作", "间歇期：两次发作之间", "慢性痛风石性关节炎：痛风石形成、关节破坏", "痛风性肾病：尿酸性肾病、尿酸结石、慢性肾功能不全", "分期：急性期、间歇期、慢性期"], "key_points": ["急性期：抗炎止痛(秋水仙碱/NSAIDs/激素)，不启动降尿酸(已在用则不停)", "降尿酸治疗：血尿酸≥480μmol/L或有痛风发作/痛风石/肾结石，目标<360(有痛风石<300)", "降尿酸首选黄嘌呤氧化酶抑制剂(别嘌醇/非布司他)", "降尿酸同时预防急性发作(秋水仙碱0.5mg qd×3-6月)", "生活方式：低嘌呤饮食、限酒、多饮水、减重", "别嘌醇用前查HLA-B*5801(汉族人高危，阳性禁用)"], "drug_recommendations": ["急性期秋水仙碱：0.5mg每1-2h至症状缓解或腹泻，最大3mg/d；推荐低剂量0.5mg tid", "NSAIDs：依托考昔120mg qd(急性首选)、塞来昔布200mg bid、双氯芬酸50mg tid，注意胃肠/肾/心血管风险", "糖皮质激素：泼尼松10mg tid×3-5天(不能用秋水仙碱/NSAIDs时)，或关节腔注射曲安奈德", "降尿酸别嘌醇：100mg qd起，每2-4周加100mg，目标300-600mg/d，用前查HLA-B*5801", "降尿酸非布司他：20mg qd起，渐加至40-80mg qd，心血管病慎用", "促尿酸排泄：苯溴马隆25-100mg qd(eGFR≥30)，多饮水+碱化尿液", "碱化尿液：碳酸氢钠0.5-1g tid或枸橼酸钾，目标尿pH 6.2-6.9", "预防发作：秋水仙碱0.5mg qd或NSAIDs小剂量，降尿酸开始后3-6个月"], "non_pharmacological": ["低嘌呤饮食：避免动物内脏、海鲜、浓肉汤、啤酒，限制红肉", "限酒：啤酒>白酒>红酒，最好不饮", "多饮水：>2000ml/d，促进尿酸排泄", "减重：BMI<24，腹型肥胖减重", "避免含糖饮料和高果糖食物", "避免剧烈运动和突然受凉(诱发发作)", "戒烟"], "complications": ["痛风石：破溃可流出白垩样物质，感染，手术切除", "关节破坏：慢性期关节畸形功能障碍，影像学骨侵蚀", "尿酸性肾结石：腰痛血尿，多饮水+碱化尿液，必要时碎石", "痛风性肾病：间质性肾炎、肾功能不全，控制尿酸+ACEI/ARB护肾", "急性发作：最常见，夜间剧痛，影响生活质量"], "monitoring": ["降尿酸初期：每2-4周查血尿酸，调整剂量", "达标后每3-6个月复查", "肾功能、尿常规、泌尿系超声定期", "关节超声/双能CT评估尿酸盐沉积变化", "急性发作记录频率和部位"], "special_populations": ["CKD：别嘌醇按eGFR调量，非布司他不需调量但心血管慎用，苯溴马隆eGFR<30禁用", "心血管病：非布司他慎用(心血管事件风险)，别嘌醇优先", "妊娠哺乳期：不推荐降尿酸药，急性期用激素", "老年：注意肾功能和药物相互作用，小剂量起始", "儿童：罕见，多为遗传性酶缺陷，专科治疗"], "references": "中华医学会内分泌学分会. 中国高尿酸血症与痛风诊疗指南(2024). 中华内分泌代谢杂志", "py": "zggnsxzytfzlzn（"}, {"name": "中国急性缺血性脑卒中诊治指南（2024）", "category": "神经内科", "scope": "成人急性缺血性脑卒中(AIS)早期诊断和治疗。", "diagnosis": ["突发局灶性神经功能缺损(偏瘫、失语、偏盲、共济失调)或意识障碍", "头颅CT排除出血(发病早期CT可正常)", "头颅MRI DWI高信号为金标准(超早期敏感)", "评估发病时间(最后正常时间)、NIHSS评分", "血管评估：CTA/MRA/DSA明确大血管闭塞", "病因分型：TOAST分型(大动脉粥样硬化/心源性/小血管/其他/不明原因)"], "staging": ["NIHSS评分：0-42分，<4轻型、5-15中型、16-20中重型、>20重型", "时间窗：静脉溶栓4.5h内(rt-PA)，6h内(尿激酶)；机械取栓6h内，符合DAWN/DEFUSE 3标准可延长至16-24h", "大血管闭塞(LVO)：颈内动脉、大脑中动脉M1/M2、基底动脉", "轻型卒中：NIHSS<4，致残性症状仍需溶栓", "后循环卒中：基底动脉闭塞预后差，取栓时间窗可延长"], "key_points": ["时间就是大脑，尽早识别和转运", "静脉溶栓：4.5h内rt-PA，无禁忌首选", "机械取栓：大血管闭塞6h内，符合标准可延长", "抗血小板：未溶栓者尽早阿司匹林150-300mg/d，溶栓后24h开始", "他汀：尽早高强度他汀(阿托伐他汀40-80mg)", "血压管理：溶栓前<185/110，溶栓后<180/105；未溶栓>220/120才降压"], "drug_recommendations": ["静脉溶栓rt-PA：0.9mg/kg(最大90mg)，10%静推1min，90%静滴1h，4.5h内", "尿激酶：100-150万U+NS 100-200ml静滴30min，6h内", "机械取栓：支架取栓(Solitaire)或抽吸导管，首选", "抗血小板：阿司匹林150-300mg qd(未溶栓)，溶栓24h后100mg qd；轻型非致残可双抗(阿司匹林+氯吡格雷)21天", "他汀：阿托伐他汀40-80mg qn或瑞舒伐他汀20-40mg qn，目标LDL<1.8", "降压：溶栓前血压>185/110用拉贝洛尔10-20mg iv或尼卡地平5mg/h泵入", "抗凝：心源性栓塞急性期不推荐早期抗凝，2周后开始华法林/NOAC"], "non_pharmacological": ["气道管理：意识障碍/球麻痹者气道保护，必要时气管插管", "氧疗：SpO2<94%吸氧，目标≥94%", "体温：>38℃降温，查找感染源", "血糖：7.8-10mmol/L，>10用胰岛素，<3.3补糖", "营养：48h内评估吞咽功能，不能经口者鼻饲", "早期康复：病情稳定后24-48h开始肢体功能位、被动活动"], "complications": ["出血转化：溶栓/取栓后症状加重立即复查CT，出血停用抗栓，控制血压", "脑水肿/脑疝：大面积梗死，甘露醇0.25-0.5g/kg q6h、去骨瓣减压", "癫痫：卒中后癫痫，左乙拉西坦500mg bid或丙戊酸钠", "感染：肺炎(误吸)、尿路感染，抗感染+护理", "深静脉血栓：气压治疗+低分子肝素预防", "压疮：定时翻身"], "monitoring": ["溶栓/取栓后24h内：每15-30min生命体征+NIHSS，24h复查CT", "生命体征：血压、心率、血氧、体温", "神经功能：NIHSS定期评估", "颅内出血征象：头痛、呕吐、意识下降", "血糖每1-4h，电解质、血常规、凝血", "心电监护(心律失常/心肌缺血)"], "special_populations": ["老年(≥80岁)：溶栓仍可获益，取栓同样适用，注意并发症", "轻型卒中(NIHSS<4)：致残性症状仍溶栓，非致残可双抗", "后循环卒中：基底动脉闭塞取栓时间窗可延长至24h，预后差", "妊娠：MRI无辐射优先，溶栓需权衡，取栓铅衣保护", "儿童：少见，多为心源性/血管炎，治疗原则相同剂量按体重"], "references": "中华医学会神经病学分会. 中国急性缺血性脑卒中诊治指南(2024). 中华神经科杂志", "py": "zgjxqxxnzzzzzn（"}, {"name": "中国帕金森病治疗指南（2024）", "category": "神经内科", "scope": "成人帕金森病(PD)诊断和药物/手术治疗。", "diagnosis": ["运动症状：静止性震颤(4-6Hz)、肌强直、运动迟缓、姿势平衡障碍", "支持标准：单侧起病、静止性震颤、进行性加重、左旋多巴有效", "排除标准：小脑症状、核上性凝视麻痹、早发严重自主神经障碍、锥体束征、额叶痴呆", "警示征：发病5年内快速进展、发病3年内姿势不稳、球麻痹、吸气性呼吸障碍", "辅助检查：多巴胺转运体SPECT/PET( DAT减少)、超声(黑质高回声)、MIBI心肌显像(减少)", "鉴别：特发性震颤、帕金森叠加综合征(MSA/PSP/CBD)、药物性帕金森、血管性帕金森"], "staging": ["Hoehn-Yahr分期：1期单侧、2期双侧、3期姿势反射受损、4期严重残疾需扶助、5期轮椅/卧床", "运动并发症：症状波动(剂末现象、开关现象)、异动症(剂峰/双相/关期肌张力障碍)", "非运动症状：抑郁、焦虑、认知障碍/痴呆、幻觉、睡眠障碍(RBD/失眠/嗜睡)、自主神经功能障碍(便秘/体位性低血压/尿失禁)、疼痛、疲劳", "病程：早期(H-Y 1-1.5)、中期(H-Y 2-3)、晚期(H-Y 4-5)"], "key_points": ["早期诊断早期治疗，药物治疗是首选", "目标：改善症状，延缓运动并发症，提高生活质量", "用药原则：剂量滴定，细水长流不求全效，最小有效剂量", "年轻/早期无认知障碍：MAO-B抑制剂或多巴胺受体激动剂起始", "老年/认知障碍：左旋多巴起始", "中晚期运动并发症：调整药物方案，评估DBS手术", "非运动症状同样需积极管理"], "drug_recommendations": ["左旋多巴：美多芭(左旋多巴200mg+苄丝肼50mg)起始62.5mg tid，渐加至250mg tid，餐前1h或餐后1.5h；达灵复(左旋多巴+卡比多巴+恩他卡朋)", "多巴胺受体激动剂：普拉克索0.125mg tid起渐加至0.5-1mg tid；罗匹尼罗0.25mg tid起；吡贝地尔50mg qd-bid；罗替戈汀贴剂2-8mg/24h", "MAO-B抑制剂：司来吉兰2.5-5mg bid(早午)、雷沙吉兰1mg qd、沙芬酰胺50-100mg qd", "COMT抑制剂：恩他卡朋100-200mg与左旋多巴同服、托卡朋100mg tid(监测肝功)", "抗胆碱能：苯海索1-2mg tid(震颤为主，<70岁无认知障碍，老年/认知障碍禁用)", "金刚烷胺50-100mg bid-tid(异动症有效)", "DBS手术：药物治疗无效/运动并发症，STN或GPi靶点，术后仍需药物"], "non_pharmacological": ["康复训练：步态训练、平衡训练、言语训练(LSVT)、吞咽训练、太极拳", "营养：高蛋白饮食影响左旋多巴吸收，服药与高蛋白餐间隔，便秘增加膳食纤维水", "运动：规律有氧运动(快走、游泳、骑行)改善运动和非运动症状", "心理支持：抑郁焦虑常见，认知行为治疗", "睡眠卫生：RBD注意安全防护，避免镇静药", "护理：晚期防跌倒、压疮、误吸，家庭环境改造"], "complications": ["运动并发症：剂末现象(增加服药次数/加COMT抑制剂/激动剂)、开关现象(换用控释剂/DBS)、异动症(减左旋多巴单次量/加金刚烷胺/DBS)", "吞咽困难/误吸：吞咽训练，稠食，必要时胃造瘘", "认知障碍/痴呆：胆碱酯酶抑制剂(卡巴拉汀/多奈哌齐)", "精神症状：幻觉妄想，减抗胆碱能/金刚烷胺/激动剂，必要时氯氮平/喹硫平", "体位性低血压：减降压药，米多君2.5mg tid，屈昔多巴", "冻结步态：听觉/视觉提示，调整药物，DBS"], "monitoring": ["每3-6个月随访：UPDRS评分、H-Y分期、运动并发症、非运动症状", "药物不良反应：左旋多巴(异动、恶心、体位性低血压)、激动剂(冲动控制障碍、嗜睡、水肿)、抗胆碱能(认知、口干、尿潴留)", "认知功能：MMSE/MoCA定期评估", "药物依从性和服药时间", "晚期营养状态、吞咽功能、跌倒风险"], "special_populations": ["老年(≥70岁)：左旋多巴起始，避免抗胆碱能，注意认知和体位性低血压", "年轻(<60岁)：MAO-B抑制剂或激动剂起始，延缓左旋多巴使用", "妊娠：左旋多巴相对安全，其他药物慎用，多学科管理", "认知障碍/痴呆：避免抗胆碱能，左旋多巴+胆碱酯酶抑制剂", "晚期卧床：综合护理，预防并发症，姑息治疗"], "references": "中华医学会神经病学分会帕金森病及运动障碍学组. 中国帕金森病治疗指南(2024). 中华神经科杂志", "py": "zgpjsbzlzn（"}, {"name": "成人心肺复苏与心血管急救指南（2024 AHA更新）", "category": "急诊科", "scope": "成人心脏骤停心肺复苏(CPR)和心血管急救。", "diagnosis": ["心脏骤停识别：意识丧失+无正常呼吸(仅喘息/无呼吸)+大动脉搏动消失(10秒内判断)", "心电节律：室颤/无脉室速(VF/pVT)、无脉电活动(PEA)、心室停搏(asystole)", "可除颤节律：VF/pVT；不可除颤：PEA/asystole", "病因排查(4H4T)：低氧、低血容量、酸中毒、高/低钾、低体温；张力性气胸、心包填塞、血栓(冠脉/肺栓塞)、毒素", "ROSC识别：自主呼吸、意识恢复、可触及脉搏、SpO2/ETCO2上升", "目标温度管理(TTM)：ROSC后昏迷者32-36℃维持24h"], "staging": ["生存链：识别呼救→早期CPR→快速除颤→高级生命支持→复苏后综合管理", "院外心脏骤停(OHCA)：旁观者CPR+AED+EMS", "院内心脏骤停(IHCA)：快速反应团队", "复苏质量：按压深度5-6cm、频率100-120次/分、胸廓充分回弹、减少中断(<10秒)、避免过度通气", "ETCO2：持续监测，高质量CPR时≥10-20mmHg，ROSC时突然升高"], "key_points": ["立即识别，呼救，开始CPR", "C-A-B顺序：胸外按压→开放气道→人工呼吸", "尽早除颤(AED到达立即分析除颤)，除颤后立即继续CPR不检查脉搏", "每2分钟轮换按压者，检查节律(尽量缩短中断)", "高级气道建立后持续按压不中断，通气10次/分", "肾上腺素1mg每3-5分钟一次(不可除颤节律尽早用)", "ROSC后目标温度管理、冠脉造影(STEMI/疑似心源性)、神经预后评估"], "drug_recommendations": ["肾上腺素：1mg iv/io，每3-5分钟一次(所有心脏骤停)", "胺碘酮：300mg iv推(除颤+肾上腺素后VF/pVT持续)，可再给150mg；维持1mg/min×6h→0.5mg/min×18h", "利多卡因：1-1.5mg/kg iv，可再给0.5-0.75mg/kg(胺碘酮不可用时)", "镁剂：1-2g iv(尖端扭转型室速/低镁)", "碳酸氢钠：不常规使用，仅严重酸中毒(pH<7.1)、高钾、三环类抗抑郁药过量时用", "液体复苏：低血容量/分布性休克时晶体液", "血管活性药(ROSC后)：去甲肾上腺素0.05-1μg/kg/min维持MAP≥65mmHg"], "non_pharmacological": ["胸外按压：双手交叠，胸骨下半部，深度5-6cm，频率100-120次/分，充分回弹", "开放气道：仰头抬颏(无颈椎损伤)，推举下颌(可疑颈椎损伤)", "人工呼吸：球囊面罩，每次1秒见胸廓起伏，按压通气比30:2(高级气道后10次/分)", "AED：开机→贴电极→分析(不接触)→除颤(所有人离开)→立即CPR", "高级气道：气管插管/声门上气道，确认位置(ETCO2+听诊)", "目标温度管理：ROSC后昏迷者32-36℃维持24h，避免发热(>37.7℃)"], "complications": ["肋骨骨折/胸骨骨折：常见，不影响继续按压", "气胸/血胸：按压或穿刺并发症，胸腔闭式引流", "误吸/肺炎：气道管理，吸引，抗感染", "缺血缺氧性脑病：TTM，神经预后评估(72h后)，避免过早撤除生命支持", "心功能不全：正性肌力药/血管活性药，IABP/ECMO", "多器官功能衰竭：ICU综合支持"], "monitoring": ["CPR期间：ETCO2(≥10-20提示高质量)、心电节律、按压深度/频率(反馈装置)", "ROSC后：心电监护、血压(有创)、血氧、体温、ETCO2、血气、电解质、乳酸、心肌酶、心电图", "神经功能：瞳孔、GCS、脑电图(癫痫持续状态)、SSEP(72h后预后)", "冠脉造影：STEMI或疑似心源性OHCA紧急造影", "器官功能：肾功能、肝功能、凝血、DIC"], "special_populations": ["妊娠：子宫左移(20周以上)，必要时围死亡期剖宫产(4分钟内)", "老年：基础病多，预后差，但不影响复苏努力", "创伤：张力性气胸/心包填塞/低血容量为常见原因，紧急处理", "低温：核心体温<30℃除颤困难，药物间隔延长，积极复温", "溺水/窒息：先给5次人工呼吸再CPR，低体温延长复苏至复温"], "references": "American Heart Association. 2024 AHA Guidelines for CPR and ECC. Circulation", "py": "crxffsyxxgjjzn（gx）"}, {"name": "严重过敏反应急诊处理指南（2024）", "category": "急诊科", "scope": "成人和儿童严重过敏反应(过敏性休克)的识别和急诊处理。", "diagnosis": ["急性起病(数分钟至数小时)，累及皮肤黏膜(荨麻疹/血管性水肿/瘙痒/潮红)+呼吸系统(呼吸困难/喘息/低氧)或循环系统(低血压/休克)", "或暴露于已知过敏原后出现低血压/支气管痉挛/喉头水肿，即使无皮肤表现", "皮肤症状缺如不能排除严重过敏反应(20%无皮疹)", "双相反应：初始症状缓解后数小时(1-72h，多8-10h)再次发作", "常见诱因：食物(花生/坚果/海鲜/牛奶/鸡蛋)、药物(青霉素/造影剂/NSAIDs)、昆虫毒液、乳胶、运动", "鉴别：哮喘急性发作、晕厥、血管迷走反应、脓毒性休克、心源性休克、遗传性血管性水肿(无荨麻疹/瘙痒)"], "staging": ["严重程度分级：I级(皮肤黏膜)、II级(呼吸/心血管中度)、III级(严重呼吸/循环衰竭)、IV级(呼吸心跳骤停)", "过敏性休克：收缩压<90mmHg或较基线下降>30%，伴组织灌注不足", "喉头水肿：声音嘶哑、吸气性喘鸣、吞咽困难，可窒息", "支气管痉挛：喘息、呼气性呼吸困难、低氧", "双相反应风险：严重发作、延迟肾上腺素、过敏原未清除、需要多剂肾上腺素者风险高"], "key_points": ["肾上腺素是首选救命药，立即肌注(大腿前外侧)，不要延迟", "体位：平卧抬高下肢(呼吸困难者半卧位)，呕吐者侧卧", "立即呼救/拨打急救电话", "吸氧：SpO2<94%或呼吸困难", "建立静脉通路，快速补液(晶体液)", "支气管痉挛：雾化沙丁胺醇", "喉头水肿严重：气管插管/环甲膜穿刺", "观察至少6-12小时(双相反应风险)"], "drug_recommendations": ["肾上腺素：0.3-0.5mg(1:1000)肌注大腿前外侧，成人；儿童0.01mg/kg(最大0.3mg)；每5-15分钟可重复", "肾上腺素静滴：休克/肌注无效，1mg+NS 250ml，1-4μg/min(成人)，监护", "液体复苏：生理盐水或乳酸林格液，成人1-2L快速静滴，儿童20ml/kg", "抗组胺药：西替利嗪10mg iv/po或氯雷他定10mg po(辅助，非首选，不缓解气道痉挛/休克)", "糖皮质激素：甲泼尼龙40-80mg iv或氢化可的松100-200mg iv(预防双相反应，起效慢)", "支气管痉挛：沙丁胺醇雾化2.5-5mg q20min，异丙托溴铵0.5mg", "难治性休克：去甲肾上腺素0.05-1μg/kg/min，胰高血糖素1-2mg iv(β阻滞剂患者)"], "non_pharmacological": ["立即停止/移除过敏原(药物停输、昆虫刺拔出、食物停止)", "平卧抬高下肢(呼吸困难/呕吐者半卧/侧卧)", "保持气道通畅，清除分泌物", "吸氧：面罩高流量，目标SpO2≥94%", "建立静脉通路(大口径)", "心电监护、血压、血氧监测", "保暖", "严重喉头水肿：气管插管(困难时环甲膜穿刺/切开)"], "complications": ["呼吸衰竭：喉头水肿窒息/支气管痉挛，紧急气道管理", "循环衰竭/休克：补液+肾上腺素+血管活性药", "心搏骤停：CPR+肾上腺素(每3-5min)", "双相反应：观察6-12h，严重者24h，激素预防", "急性肺水肿/ARDS：正压通气", "应激性心肌病(儿茶酚胺相关)：支持治疗，多可恢复"], "monitoring": ["持续心电监护、血压(每5-15min)、血氧、呼吸频率、意识", "反复评估气道、呼吸、循环", "实验室：血气、乳酸、心肌酶、胰酶(食物过敏可升高)、类胰蛋白酶(发作后1-2h采血，诊断价值)", "尿量", "观察双相反应迹象(皮疹复发、呼吸困难、血压下降)"], "special_populations": ["妊娠：肾上腺素仍首选(剂量同)，左侧卧位，监测胎心，过敏性休克可致胎儿窘迫", "儿童：剂量按体重，肾上腺素0.01mg/kg肌注(最大0.3mg)，补液20ml/kg", "老年/心血管病：肾上腺素注意心律失常/心肌缺血，但仍首选，小剂量起始", "β阻滞剂患者：肾上腺素效果差，胰高血糖素1-2mg iv", "服用ACEI者：血管性水肿风险高，对抗组胺/激素反应差，注意气道"], "references": "World Allergy Organization. WAO Guidelines for the Assessment and Management of Anaphylaxis (2024 update)", "py": "yzgmfyjzclzn（"}, {"name": "中国慢性肾脏病早期评价与管理指南（2024）", "category": "肾内科", "scope": "成人慢性肾脏病(CKD)筛查、分期评估和管理。", "diagnosis": ["CKD定义：肾损害标志(白蛋白尿/尿沉渣异常/组织学/影像学/移植史)或eGFR<60ml/min/1.73m²，持续≥3个月", "eGFR计算：CKD-EPI公式(肌酐+年龄+性别+种族)", "白蛋白尿：ACR≥30mg/g为异常；A1<30、A2 30-300、A3>300", "尿沉渣：红细胞管型、颗粒管型提示肾小球/肾小管损伤", "影像学：肾脏大小、皮质厚度、结构异常", "肾活检：蛋白尿/血尿/肾功能快速下降，明确病理类型"], "staging": ["GFR分期：G1≥90、G2 60-89、G3a 45-59、G3b 30-44、G4 15-29、G5<15(透析)", "白蛋白尿分期：A1正常/轻度、A2中度、A3重度", "CKD进展风险：G1-2+A1低危、G1-2+A2/G3a+A1中危、G1-2+A3/G3a+A2/G3b+A1高危、G3a+A3/G3b+A2/G4+A1-2极高危、G5/G4+A3极高危", "急性肾损伤(AKI)：48h内肌酐升高≥26.5μmol/L或7天内升高≥50%，或尿量<0.5ml/kg/h×6h", "ESRD：G5期需要肾脏替代治疗(透析/移植)"], "key_points": ["早期筛查：高危人群(糖尿病、高血压、心血管病、肥胖、吸烟、家族史、老年)每年查尿常规+eGFR+ACR", "控制血压：CKD目标<130/80，ACEI/ARB首选(蛋白尿者)", "控制血糖：糖尿病CKD HbA1c<7%，SGLT2i推荐", "控制蛋白尿：ACEI/ARB减少蛋白尿，目标ACR<30", "血脂管理：LDL<2.6(极高危<1.8)，他汀治疗", "避免肾毒性药物：NSAIDs、氨基糖苷、造影剂、含马兜铃酸中药", "营养：蛋白0.8g/kg/d(G3-5未透析)，低盐<5g/d，限钾限磷(G4-5)"], "drug_recommendations": ["ACEI：贝那普利10-20mg qd、依那普利5-10mg bid(蛋白尿首选，起始后2-4周查血钾肌酐，肌酐升<30%可继续)", "ARB：缬沙坦80-160mg qd、氯沙坦50-100mg qd、厄贝沙坦150-300mg qd", "SGLT2i：达格列净10mg qd、恩格列净10mg qd(eGFR≥20可用，CKD全阶段获益)", "GLP-1RA：利拉鲁肽1.2-1.8mg qd、司美格鲁肽0.5-1.0mg qw(糖尿病CKD)", "利尿剂：呋塞米20-40mg qd(水肿/高血压)，eGFR<30噻嗪类效果差换袢利尿剂", "降磷：碳酸钙/醋酸钙(餐中嚼服)、司维拉姆800mg tid、碳酸镧500mg tid(G4-5高磷)", "纠正贫血：促红素(ESA)50-100U/kg tiw，目标Hb 100-120g/L；铁剂(静脉蔗糖铁)", "纠正酸中毒：碳酸氢钠1-3g tid(CO2CP<22)"], "non_pharmacological": ["低盐饮食：<5g/d(包括隐形盐)", "优质低蛋白：0.8g/kg/d(G3-5未透析)，透析后1.0-1.2g/kg/d，动物蛋白为主", "限钾：G4-5高钾者避免香蕉/橙子/土豆/坚果/低钠盐，蔬菜焯水去钾", "限磷：避免加工肉/可乐/坚果/动物内脏，选磷蛋白比低的食物", "限水：尿量减少/水肿/高血压者控制入量(前一日尿量+500ml)", "戒烟限酒，控制体重(BMI 18.5-24)", "适度运动：每周≥150分钟中等强度，避免剧烈运动", "避免滥用药物和偏方"], "complications": ["CKD进展至ESRD：透析(血液透析/腹膜透析)或肾移植", "心血管疾病：CKD首要死因，冠心病/心衰/心律失常/猝死，积极控制危险因素", "矿物质骨代谢异常(CKD-MBD)：高磷低钙继发性甲旁亢，肾性骨病，血管钙化", "贫血：EPO缺乏+铁缺乏+炎症，ESA+铁剂", "代谢性酸中毒：碳酸氢钠纠正", "高钾血症：危及生命，钙剂(稳定心肌)+胰岛素+葡萄糖+降钾药(聚苯乙烯磺酸钙/环硅酸锆钠)+透析", "感染：免疫功能低下，疫苗接种(乙肝/流感/肺炎球菌)"], "monitoring": ["CKD 1-2期：每6-12个月查eGFR、ACR、电解质", "CKD 3期：每3-6个月", "CKD 4期：每1-3个月", "CKD 5期：每月", "每次：血压、体重、eGFR、电解质(钾钠氯钙磷)、CO2CP、血常规、PTH(G3b起)、铁蛋白/转铁蛋白饱和度", "肾脏超声每年评估大小和结构", "血管通路准备：预计1年内透析者提前建立动静脉内瘘"], "special_populations": ["糖尿病肾病：SGLT2i+GLP-1RA+ACEI/ARB，严格控糖控压，蛋白尿是进展关键", "高血压肾损害：控制血压<130/80，ACEI/ARB，夜尿增多为早期表现", "老年：eGFR随年龄下降，避免肾毒性药，药物按eGFR调整", "妊娠：CKD妊娠风险高(高血压/子痫/早产/肾功能恶化)，需多学科，ACEI/ARB/SGLT2i禁用", "儿童：遗传性肾病多见(Alport综合征)，生长发育和营养关注"], "references": "中华医学会肾脏病学分会. 中国慢性肾脏病早期评价与管理指南(2024). 中华肾脏病杂志", "py": "zgmxszbzqpjyglzn（"}, {"name": "抗菌药物临床应用指导原则（2024年版）", "category": "感染科", "scope": "抗菌药物临床合理应用的基本原则、适应证和管理。", "diagnosis": ["细菌感染诊断：症状体征+实验室(白细胞/中性粒/CRP/PCT升高)+病原学(培养/核酸/抗原)", "病原学检查：用药前留取标本(血培养×2套、痰、尿、脑脊液、分泌物)，药敏指导用药", "感染部位：呼吸道、泌尿道、消化道、皮肤软组织、血流、中枢、腹腔等", "感染严重程度：轻症(门诊口服)、中症(住院静脉)、重症(ICU广谱联合)", "宿主因素：免疫状态、肝肾功能、年龄、妊娠、过敏史、既往抗菌药使用", "耐药风险评估：近3月抗菌药使用、住院史、护理院、侵袭性操作、当地耐药率"], "staging": ["预防用药：手术预防(术前30-60min单剂，清洁手术不超过24h)、特定感染预防(风湿热/流脑/结核暴露)", "经验治疗：未获病原前根据部位+严重程度+宿主选药，覆盖最可能病原", "目标治疗：获得病原和药敏后，降阶梯/窄谱/口服转换", "联合用药：重症/混合感染/耐药菌/协同作用(如草绿色链球菌心内膜炎青霉素+庆大)", "疗程：一般体温正常/症状消退后72-96h；特殊感染更长(感染性心内膜炎4-6周、骨髓炎4-6周、结核6-9月)", "抗菌药物分级管理：非限制级、限制级、特殊使用级(专家会诊)"], "key_points": ["诊断为细菌感染者方有指征，病毒感染不用", "尽早查明病原，根据药敏选药", "按药物抗菌谱、药代动力学、药效学选药(PK/PD)", "剂量足、疗程够，避免耐药和复发", "根据肝肾功能调整剂量", "尽量避免局部用药(除特殊情况)", "严格控制预防用药指征", "分级管理，特殊使用级需会诊"], "drug_recommendations": ["时间依赖性(β内酰胺类)：青霉素/头孢/碳青霉烯，分次给药，延长输注时间(3-4h)提高T>MIC", "浓度依赖性(氨基糖苷/喹诺酮)：每日1次给药，提高Cmax/MIC和AUC/MIC", "社区获得性肺炎：阿莫西林/头孢曲松+大环内酯或呼吸喹诺酮", "医院获得性肺炎：哌拉西林他唑巴坦/头孢吡肟/碳青霉烯，怀疑MRSA加万古霉素/利奈唑胺，怀疑铜绿覆盖", "尿路感染：呋喃妥因/磷霉素(单纯性)，头孢/喹诺酮(复杂性)", "皮肤软组织：苯唑西林/头孢唑林(金葡)，怀疑MRSA用万古霉素/达托霉素", "腹腔感染：三代头孢+甲硝唑或哌拉西林他唑巴坦/碳青霉烯", "中枢感染：三代头孢(头孢曲松/头孢噻肟)+万古霉素，李斯特菌加氨苄西林", "MRSA：万古霉素15-20mg/kg q12h(谷浓度15-20)、利奈唑胺600mg q12h、达托霉素6mg/kg qd(非肺炎)", "CRE：多黏菌素B/替加环素/头孢他啶阿维巴坦/美罗培南法硼巴坦，联合用药"], "non_pharmacological": ["感染灶引流/清除：脓肿切开、胸腔/腹腔引流、坏死组织清创、拔除感染导管", "支持治疗：补液、营养、氧疗、纠正电解质紊乱", "免疫调节：丙种球蛋白(特定免疫缺陷)、粒细胞集落刺激因子(粒缺)", "物理治疗：热敷、理疗", "隔离：多重耐药菌接触隔离，空气传播(结核/麻疹)空气隔离", "疫苗接种：流感、肺炎球菌、乙肝、HPV等预防感染"], "complications": ["抗菌药物不良反应：过敏(青霉素/头孢)、肾毒性(氨基糖苷/万古霉素)、肝毒性(四环素/大环内酯)、耳毒性(氨基糖苷)、胃肠道反应(广谱抗生素腹泻)", "艰难梭菌感染(CDI)：广谱抗生素后腹泻，甲硝唑/万古霉素/非达霉素，粪菌移植(复发)", "二重感染：真菌(念珠菌/曲霉)、耐药菌", "药物相互作用：QT延长(喹诺酮/大环内酯)、抗凝(甲硝唑/头孢哌酮)、茶碱(大环内酯/喹诺酮)", "耐药菌产生：不合理使用导致MRSA/VRE/CRE/CRAB/CRPA"], "monitoring": ["疗效评估：用药48-72h评估，体温、症状、白细胞、CRP/PCT、影像学", "血药浓度：氨基糖苷(峰谷浓度)、万古霉素(谷浓度15-20)、茶碱", "肝肾功能：用药前和用药中定期，调整剂量", "过敏反应：用药后观察30min(青霉素/头孢)，备好急救", "二重感染迹象：腹泻(艰难梭菌)、口腔白斑(真菌)", "病原学随访：血培养阳性者复查至阴性"], "special_populations": ["老年：肾功能减退，按eGFR调量，注意耳肾毒性，避免长效药物", "儿童：避免四环素(8岁以下)、喹诺酮(骨骼影响)，氨基糖苷慎用，按体重算量", "妊娠：青霉素/头孢/阿奇霉素相对安全，禁用四环素/喹诺酮/氨基糖苷/磺胺(孕晚期)", "哺乳：多数抗菌药可分泌入乳汁，注意婴儿影响(四环素/喹诺酮避免)", "肝肾功能不全：按Child-Pugh/eGFR调整，避免肝肾毒性药物", "免疫低下：经验治疗更积极广谱，覆盖真菌/病毒/肺孢子菌等特殊病原"], "references": "国家卫生健康委员会. 抗菌药物临床应用指导原则(2024年版)", "py": "kjywlcyyzdyz（nb）"}, {"name": "妊娠期高血压疾病诊治指南（2024）", "category": "妇产科", "scope": "妊娠期高血压疾病诊断、分类和处理。", "diagnosis": ["妊娠期高血压：妊娠20周后首次BP≥140/90，产后12周恢复，无蛋白尿", "子痫前期：BP≥140/90+蛋白尿≥0.3g/24h或ACR≥30mg/g，或无蛋白尿但有器官损害(血小板<100、肝酶升高、肾功损害、肺水肿、新发生脑/视觉症状)", "子痫：子痫前期基础上抽搐(不能用其他原因解释)", "慢性高血压合并妊娠：妊娠前或20周前BP≥140/90", "慢性高血压并发子痫前期：慢性高血压基础上出现蛋白尿/器官损害", "高危因素：初产、高龄(≥40)、肥胖、多胎、家族史、慢性高血压/肾病/糖尿病/自身免疫病"], "staging": ["轻度子痫前期：BP≥140/90，蛋白尿或器官损害轻", "重度子痫前期：BP≥160/110，或严重器官损害(血小板<100、肝酶>2倍、肌酐>1.1、肺水肿、脑/视觉症状、上腹痛、FGR)", "子痫：抽搐发作，产前/产时/产后", "HELLP综合征：溶血(H)、肝酶升高(EL)、血小板减少(LP)，子痫前期严重并发症", "远期风险：再次妊娠复发、慢性高血压、心血管病、肾病"], "key_points": ["降压：BP≥140/90建议降压，≥160/110紧急降压，目标130-155/80-105", "硫酸镁：子痫前期重度预防抽搐，子痫控制抽搐和预防复发", "终止妊娠是根本治疗：重度子痫前期/子痫病情稳定后终止，孕龄决定方式", "产前糖皮质激素：<34周预计早产者促胎肺成熟(地塞米松6mg im q12h×4次)", "严密监测母儿：血压、尿蛋白、器官功能、胎心、胎儿生长", "产后仍需监测：产后48h内是子痫高发期，降压继续"], "drug_recommendations": ["降压口服：拉贝洛尔100mg bid起(最大2400mg/d)、硝苯地平缓释片20mg q12h(最大120mg/d)、甲基多巴250mg tid起(最大3g/d)", "紧急降压静脉：拉贝洛尔20mg iv→40mg→80mg(每10min)，或硝苯地平10mg口服，或肼苯哒嗪5mg iv q15-20min", "硫酸镁：负荷4-6g+5%GS 100ml静滴15-20min，维持1-2g/h，24h总量≤25g；用至产后24h(子痫预防)或抽搐控制后24h(子痫)", "硫酸镁中毒：膝反射消失、呼吸<16次/分、尿量<25ml/h，钙剂解救(10%葡萄糖酸钙10ml iv慢推)", "糖皮质激素：地塞米松6mg im q12h×4次或倍他米松12mg im q24h×2次(<34周)", "镇静：地西泮10mg iv或冬眠合剂(硫酸镁无效时)", "利尿剂：不常规用，仅肺水肿/脑水肿/心衰时用"], "non_pharmacological": ["左侧卧位：减轻子宫对下腔静脉压迫，改善胎盘灌注", "休息：重度子痫前期住院卧床休息", "饮食：充足蛋白热量，不严格限盐(除非严重水肿)，补钙1.5-2g/d(高危者预防)", "监测：血压每4h(重度每15-30min)、体重、尿量、胎动", "胎儿监测：胎心监护、超声(生长/羊水/脐血流)", "心理支持：焦虑恐惧常见，解释病情"], "complications": ["子痫：抽搐→硫酸镁控制，防舌咬伤/窒息/外伤，控制后终止妊娠", "HELLP综合征：溶血(贫血/黄疸/网织红高)、肝酶升高、血小板<100，糖皮质激素+终止妊娠", "胎盘早剥：腹痛阴道出血胎心异常，紧急剖宫产", "急性肾衰：少尿无尿肌酐升高，液体管理，必要时透析", "肺水肿/心衰：呼吸困难低氧，利尿+扩血管+正压通气", "脑血管意外：脑出血/脑水肿，控制血压+脱水", "DIC：凝血功能障碍，补充凝血因子+肝素(慎用)"], "monitoring": ["血压：每4h(重度每15-30min)", "尿蛋白：24h尿蛋白或ACR", "实验室：血常规(血小板)、肝酶、肌酐、尿酸、凝血、LDH(HELLP)、电解质", "胎心监护：重度每日1-2次", "超声：胎儿生长、羊水量、脐动脉血流", "尿量：每小时记录(硫酸镁期间)", "膝反射/呼吸(硫酸镁中毒监测)"], "special_populations": ["早发型子痫前期(<34周)：尽量延长孕周(期待治疗)，严密监测，促胎肺成熟，≥34周终止", "慢性高血压合并妊娠：孕前评估，孕期用拉贝洛尔/硝苯地平/甲基多巴，ACEI/ARB禁用，监测子痫前期", "多胎妊娠：高危，加强监测，降压阈值更低", "产后：产后48h内子痫高发，继续降压和硫酸镁，产后12周复查血压(慢性高血压诊断)", "远期随访：慢性高血压、心血管病、肾病风险增加，长期管理"], "references": "中华医学会妇产科学分会妊娠期高血压疾病学组. 妊娠期高血压疾病诊治指南(2024). 中华妇产科杂志", "py": "rsqgxyjbzzzn（"}, {"name": "儿童支气管哮喘诊断与防治指南（2024）", "category": "儿科", "scope": "儿童(0-14岁)支气管哮喘诊断、评估和长期管理。", "diagnosis": ["反复发作喘息、咳嗽、气促、胸闷，夜间/凌晨加重，与接触变应原/冷空气/运动/感染有关", "发作时双肺闻及呼气相哮鸣音，呼气相延长", "支气管舒张试验阳性：吸入SABA后FEV1改善≥12%(≥6岁)", "PEF日间变异率>13%(≥6岁)", "抗炎治疗有效：ICS治疗2-4周症状显著改善", "排除其他原因：反复喘息鉴别(先天性气道畸形、异物、胃食管反流、支气管肺发育不良、囊性纤维化)", "过敏原检测：皮肤点刺或血清sIgE，辅助判断诱因"], "staging": ["病情分期：急性发作期、慢性持续期、临床缓解期(≥3个月无症状)", "控制水平分级：良好控制、部分控制、未控制(按日间症状/夜间憋醒/SABA使用/活动受限/肺功能)", "急性发作严重度：轻度、中度、重度、危重度(说话不连贯/发绀/意识改变/哮鸣音减弱消失)", "哮喘预测指数(API)：<3岁反复喘息预测未来哮喘风险(阳性：父母哮喘/特应性皮炎/吸入过敏原阳性/嗜酸高/感冒无关喘息)", "表型：婴幼儿喘息(病毒诱导型/多因素触发型)、学龄前喘息、学龄期哮喘"], "key_points": ["坚持长期、持续、规范、个体化治疗", "急性发作：快速缓解症状(SABA+全身激素+氧疗)", "慢性持续：ICS是控制治疗首选，按控制水平升/降级", "≥6岁：GINA阶梯治疗，低剂量ICS-福莫特罗按需(MART方案)", "<6岁：ICS每天控制，或白三烯调节剂", "治疗目标：良好控制症状，维持正常活动，预防急性发作和肺功能损害", "患者教育：吸入技术、峰流速监测、行动计划、避免诱因"], "drug_recommendations": ["SABA：沙丁胺醇雾化2.5mg(<20kg)/5mg(≥20kg) q20min×3次，或pMDI+储雾罐2-4揿", "ICS：布地奈德雾化0.5-1mg bid(<6岁)，丙酸氟替卡松50-100μg bid(≥4岁)，布地奈德/福莫特罗80/4.5μg 1-2吸bid(≥6岁)", "全身激素：泼尼松龙1-2mg/kg/d(最大40mg)×3-5天，重症甲泼尼龙1-2mg/kg iv q6h", "抗胆碱能：异丙托溴铵雾化250μg(<6岁)/500μg(≥6岁)，与SABA联合(中重度发作)", "白三烯调节剂：孟鲁司特4mg(2-5岁)/5mg(6-14岁) qn，ICS辅助或不能用ICS者", "茶碱：氨茶碱负荷5mg/kg iv(>20min)后0.5-1mg/kg/h维持(重症，监测血药浓度)", "生物制剂：≥6岁中重度嗜酸型/过敏型，奥马珠单抗(抗IgE)、美泊利单抗(抗IL-5)，按体重和IgE/嗜酸算剂量", "危重度发作：SABA+异丙托溴铵雾化q20min，全身激素iv，硫酸镁25-40mg/kg iv(最大2g)，无效机械通气"], "non_pharmacological": ["避免诱因：尘螨(防螨床罩/热水洗)、烟雾(包括二手三手烟)、宠物、霉菌、花粉季节防护", "呼吸道感染预防：勤洗手，流感疫苗每年接种，RSV预防(高危婴幼儿帕利珠单抗)", "运动管理：运动前吸入SABA预防，哮喘控制好可正常运动", "呼吸训练：腹式呼吸、缩唇呼吸(≥6岁)", "家庭监测：峰流速仪(≥6岁)，记录哮喘日记，识别发作先兆", "营养：均衡饮食，肥胖者减重，避免已知过敏食物"], "complications": ["哮喘持续状态/危重度发作：雾化SABA+激素+氧疗，无效插管机械通气，死亡率高", "气胸/纵隔气肿：严重发作，胸腔闭式引流", "呼吸衰竭：II型呼衰，无创或有创通气", "闭锁肺综合征：严重支气管痉挛，药物无效，紧急机械通气", "药物不良反应：ICS口腔念珠菌/声音嘶哑(漱口)、SABA心悸手抖、孟鲁司特神经精神事件(情绪/睡眠/自杀意念)", "肺功能损害：长期未控制可致气道重塑，成人后COPD风险"], "monitoring": ["控制良好每3个月随访，未控制每2-4周", "每次：症状、夜间憋醒、SABA使用、活动受限、吸入技术、峰流速(≥6岁)", "肺功能：≥6岁每年1-2次，急性发作后复查", "FeNO/血嗜酸：评估表型和ICS反应", "过敏原复查：必要时", "治疗依从性评估，环境控制评估"], "special_populations": ["婴幼儿(<3岁)：反复喘息多为病毒诱导，API阳性者按哮喘治疗，ICS或白三烯调节剂，避免过度诊断", "学龄前(3-5岁)：ICS每天控制，或孟鲁司特，吸入用储雾罐+面罩", "学龄期(≥6岁)：GINA阶梯，MART方案(低剂量ICS-福莫特罗维持+缓解)，干粉吸入器可用", "运动诱发哮喘：运动前SABA预防，控制不佳者ICS维持", "过敏性鼻炎合并哮喘：同时治疗鼻炎(鼻喷激素)，上气道下气道同治", "重症哮喘：评估依从性/吸入技术/诱因/合并症，生物制剂，多学科管理"], "references": "中华医学会儿科学分会呼吸学组. 儿童支气管哮喘诊断与防治指南(2024). 中华儿科杂志", "py": "etzqgxczdyfzzn（"}, {"name": "成人原发免疫性血小板减少症诊断与治疗中国指南（2024）", "category": "血液科", "scope": "成人原发免疫性血小板减少症(ITP)诊断和治疗。", "diagnosis": ["至少2次血常规血小板减少(<100×10⁹/L)，血涂片确认(排除假性血小板减少/EDTA依赖)", "无白细胞异常和贫血(除非出血导致)", "骨髓穿刺：巨核细胞数正常或增多伴成熟障碍，排除其他血液病", "排除继发性：自身免疫病(SLE/抗磷脂)、感染(HCV/HIV/幽门螺杆菌)、药物、淋巴增殖性疾病、骨髓增生异常", "出血表现：皮肤瘀点瘀斑、牙龈出血、鼻衄、月经过多，严重者内脏出血/颅内出血", "血小板抗体(PAIg)：敏感性高特异性低，不做常规诊断依据", "出血评分：WHO出血分级0-4级"], "staging": ["新诊断ITP：确诊后3个月内", "持续性ITP：确诊后3-12个月", "慢性ITP：病程>12个月", "重症ITP：血小板<10×10⁹/L伴活动性出血，需要急救治疗", "难治性ITP：脾切除后复发或无效，仍需治疗", "按血小板数：轻度(50-100)、中度(30-50)、重度(10-30)、极重度(<10)"], "key_points": ["治疗目标：安全血小板数(≥30×10⁹/L无出血)，不追求正常", "血小板≥30无出血：观察，不治疗", "血小板<30或有出血：一线治疗糖皮质激素", "激素无效/依赖：二线治疗(TPO受体激动剂/利妥昔单抗/脾切除)", "重症ITP/大出血：急救治疗(IVIG+大剂量激素+血小板输注)", "避免抗血小板/抗凝药物，避免外伤", "幽门螺杆菌阳性者根除治疗(部分患者血小板恢复)"], "drug_recommendations": ["一线糖皮质激素：地塞米松40mg qd×4天(口服/静滴)，或泼尼松1mg/kg/d(最大60-80mg)×2-4周渐减", "IVIG：0.4g/kg/d×5天或1g/kg/d×2天(重症/激素禁忌/术前快速提升)", "抗RhD免疫球蛋白：50-75μg/kg( Rh阳性非切脾者，注意溶血)", "二线TPO受体激动剂：艾曲泊帕25mg qd起(最大75mg，空腹)、罗米司亭1μg/kg qw皮下、阿伐曲泊帕20mg qd起", "利妥昔单抗：375mg/m²每周×4次，或100mg每周×4次(小剂量)，起效慢(4-8周)", "脾切除：药物治疗无效，术前疫苗接种(肺炎球菌/流感/嗜血杆菌)，腹腔镜优先", "急救：甲泼尼龙1g/d×3天+IVIG 1g/kg/d×2天+血小板输注，重组人活化因子VIIa(难治性出血)"], "non_pharmacological": ["避免外伤、剧烈运动、重体力劳动", "避免使用影响血小板功能的药物：阿司匹林、NSAIDs、氯吡格雷、华法林等(除非必需)", "口腔护理：软毛牙刷，避免牙签牙线，牙龈出血用明胶海绵压迫", "月经过多：妇科会诊，口服避孕药/孕激素控制", "饮食：软食，避免坚硬粗糙食物", "心理支持：慢性病程，焦虑抑郁常见"], "complications": ["颅内出血：最严重并发症，血小板<10风险高，头痛呕吐意识改变立即CT，急救治疗", "内脏出血：消化道(黑便呕血)、泌尿道(血尿)、呼吸道(咯血)，急救+专科处理", "月经过多致缺铁性贫血：补铁+妇科治疗", "激素不良反应：高血糖、高血压、骨质疏松、感染、消化道溃疡、精神症状", "脾切除后感染：暴发性肺炎球菌感染(OPSI)，术前疫苗+术后抗生素预防", "TPO受体激动剂：血栓风险(尤其有血栓危险因素者)、肝毒性(艾曲泊帕)、骨髓纤维化(长期)"], "monitoring": ["治疗初期：每周查血常规，评估疗效", "稳定期：每2-4周查血常规", "激素治疗期间：血糖、血压、骨密度、胃肠道症状", "TPO受体激动剂：肝功能(艾曲泊帕)、血小板(避免>400)、血栓征象", "脾切除后：血常规( Howell-Jolly小体)、感染征象", "出血评估：每次随访出血症状和评分"], "special_populations": ["妊娠：ITP妊娠风险(产妇出血/新生儿血小板减少)，一线糖皮质激素(泼尼松)或IVIG，避免TPO激动剂和利妥昔单抗，分娩血小板≥50(阴道)/≥80(剖宫产)", "老年：出血和血栓风险均高，治疗目标个体化，注意激素和TPO激动剂不良反应", "合并自身免疫病(SLE/抗磷脂综合征)：同时治疗原发病，注意血栓风险", "HIV/HCV相关ITP：抗病毒治疗为主，必要时IVIG/激素", "药物诱导性ITP：停用可疑药物，必要时IVIG/激素"], "references": "中华医学会血液学分会止血与血栓学组. 成人原发免疫性血小板减少症诊断与治疗中国指南(2024). 中华血液学杂志", "py": "cryfmyxxxbjszzdyzlzgzn（"}, {"name": "缺铁性贫血诊疗指南（2024）", "category": "血液科", "scope": "成人和儿童缺铁性贫血(IDA)诊断和治疗。", "diagnosis": ["贫血：男性Hb<120g/L，女性<110g/L，孕妇<100g/L", "小细胞低色素：MCV<80fl，MCH<27pg，MCHC<320g/L", "铁代谢：血清铁<8.95μmol/L，总铁结合力>64.4μmol/L，转铁蛋白饱和度<15%", "血清铁蛋白：<15μg/L(绝对缺乏)，<30μg/L伴贫血(伴炎症时<100μg/L且转铁蛋白饱和度<20%)", "骨髓铁染色：细胞外铁消失，铁粒幼细胞<15%(金标准，少用)", "病因排查：慢性失血(消化道/月经过多/咯血/血尿)、摄入不足、吸收障碍(胃切除/乳糜泻)、需求增加(妊娠/哺乳/生长发育)", "鉴别：地中海贫血(铁蛋白正常/高、血红蛋白电泳)、慢性病贫血(铁蛋白高、铁低)、铁粒幼细胞贫血"], "staging": ["铁减少期(ID)：储存铁减少(铁蛋白<30)，Hb正常", "缺铁性红细胞生成期(IDE)：铁蛋白低+转铁蛋白饱和度<15%，Hb正常", "缺铁性贫血期(IDA)：Hb降低", "贫血严重度：轻度(Hb 90-正常下限)、中度(60-90)、重度(30-60)、极重度(<30)", "病因分类：摄入不足型、吸收障碍型、慢性失血型、需求增加型"], "key_points": ["病因治疗是根本：找到并去除缺铁原因(消化道肿瘤/溃疡/月经过多等)", "补铁治疗：口服铁剂首选，无机铁(硫酸亚铁)胃肠反应大，有机铁(琥珀酸亚铁/多糖铁)耐受性好", "剂量：元素铁150-200mg/d，分2-3次，空腹吸收好(胃肠反应大可餐中)", "疗程：Hb正常后继续补铁3-6个月(补足储存铁)，或铁蛋白>50μg/L", "口服不耐受/吸收障碍/急需纠正：静脉铁剂", "饮食：富铁食物(红肉/动物肝脏/血制品)，维生素C促进吸收，茶咖啡抑制吸收(间隔1-2h)"], "drug_recommendations": ["口服铁剂：硫酸亚铁0.3g tid(元素铁60mg/片)、琥珀酸亚铁0.1-0.2g tid、多糖铁复合物150mg qd-bid、富马酸亚铁0.2g tid", "维生素C 0.2g tid：促进铁吸收(与铁剂同服)", "静脉铁剂：蔗糖铁200mg+NS 100ml静滴(每周2-3次，总量按公式)、右旋糖酐铁(需皮试)、羧基麦芽糖铁750mg单次(最大1000mg)、异麦芽糖酐铁1000mg单次", "补铁总量公式：需铁量(mg)=体重(kg)×(目标Hb-实际Hb)(g/L)×0.24+储存铁500mg", "辅助治疗：维生素B12/叶酸(合并缺乏时)、促红素(肾性贫血/慢性病贫血)", "病因治疗：消化道出血(抑酸/内镜/手术)、月经过多(妇科治疗)、钩虫病(驱虫)"], "non_pharmacological": ["饮食调整：增加血红素铁(红肉/动物肝脏/血制品)，植物铁(菠菜/木耳)吸收率低需配维生素C", "避免茶/咖啡/高钙食物与铁剂同服(间隔1-2h)", "烹饪用铁锅(增加少量铁)", "婴幼儿：及时添加富铁辅食(强化铁米粉/肉泥)，纯母乳喂养4-6月后补铁", "孕妇：常规补铁(妊娠中晚期元素铁30-60mg/d)", "老年人：注意消化道肿瘤筛查(缺铁性贫血是消化道肿瘤信号)"], "complications": ["口服铁剂不良反应：恶心、呕吐、上腹痛、便秘/腹泻、黑便(正常，需与消化道出血鉴别)", "静脉铁剂不良反应：过敏反应(皮疹/低血压/过敏性休克)、输注部位疼痛、头痛、关节痛、低血压", "铁过载：长期过量补铁导致血色病(肝/心/胰腺损害)，监测铁蛋白", "贫血性心脏病：严重长期贫血致心脏扩大/心衰，补铁后可恢复", "生长发育迟缓：儿童长期缺铁影响认知和行为发育", "异食癖：缺铁可致嗜冰/泥土/淀粉等，补铁后消失"], "monitoring": ["补铁后5-10天：网织红细胞升高(疗效最早指标)", "2周后：Hb开始上升，每2周复查", "Hb正常后：继续补铁3-6个月，复查铁蛋白>50停药", "口服铁剂4周无改善：重新评估诊断(诊断错误/未除病因/吸收障碍/依从性差/其他贫血)", "静脉铁剂：输注中监测过敏反应，输注后复查血常规和铁代谢", "病因随访：消化道出血/月经过多等病因治疗后复查"], "special_populations": ["妊娠：中晚期常规补铁30-60mg/d元素铁，贫血者100-200mg/d，口服不耐受用静脉铁(蔗糖铁安全)", "婴幼儿/儿童：按体重算剂量(元素铁2-3mg/kg/d)，及时添加辅食，筛查地中海贫血(南方地区)", "老年人：缺铁性贫血必须排查消化道肿瘤(胃镜/肠镜)，不可单纯补铁", "胃切除/乳糜泻：口服铁吸收差，首选静脉铁剂", "慢性肾病：缺铁+促红素缺乏，静脉铁+促红素联合，目标铁蛋白200-500、转铁蛋白饱和度>20%"], "references": "中华医学会血液学分会. 缺铁性贫血诊疗指南(2024). 中华血液学杂志", "py": "qtxpxzlzn（"}, {"name": "类风湿关节炎诊断及治疗指南（2024）", "category": "风湿免疫科", "scope": "成人类风湿关节炎(RA)诊断和治疗。", "diagnosis": ["2010 ACR/EULAR分类标准：关节受累(1-5分)、血清学(RF/抗CCP 0-3分)、急性期反应物(CRP/ESR 0-1分)、症状持续时间(0-1分)，总分≥6分诊断RA", "典型表现：对称性多关节炎，手足小关节为主，晨僵>30分钟，滑膜增厚/积液", "实验室：RF阳性(70-80%)、抗CCP抗体阳性(特异性>95%)、CRP/ESR升高", "影像学：X线(骨质疏松/关节间隙狭窄/骨侵蚀)、超声/核磁(滑膜炎/骨侵蚀更敏感)", "排除其他：银屑病关节炎、强直性脊柱炎、骨关节炎、痛风、反应性关节炎、结缔组织病", "关节外表现：类风湿结节、间质性肺病、心包炎、巩膜炎、血管炎、Felty综合征"], "staging": ["疾病活动度：DAS28(>5.1高活动、3.2-5.1中活动、2.6-3.2低活动、<2.6缓解)、SDAI、CDAI", "X线分期：I期(骨质疏松)、II期(骨质疏松+轻度骨侵蚀)、III期(明显骨侵蚀+关节间隙狭窄)、IV期(纤维/骨性强直)", "功能分级：I级(正常活动)、II级(中度受限但生活自理)、III级(明显受限生活不能自理)、IV级(卧床/轮椅)", "预后不良因素：抗CCP高滴度、RF高滴度、早期骨侵蚀、关节外表现、吸烟、HLA-DR4", "缓解定义：DAS28<2.6或ACR/EULAR Boolean缓解(压痛关节≤1、肿胀关节≤1、CRP≤1、患者总体评估≤1)"], "key_points": ["早期诊断早期治疗，目标治疗(treat-to-target)，目标缓解或低活动度", "DMARDs是基础，确诊后尽早启动(首选甲氨蝶呤)", "传统DMARDs单药不达标：加用生物制剂或JAK抑制剂(联合或转换)", "糖皮质激素：桥接治疗(短期小剂量)，不长期单用", "非甾体抗炎药(NSAIDs)：对症止痛，不改变病程", "关节腔注射激素：单关节炎急性发作", "康复锻炼：关节功能维持，避免废用", "定期评估疾病活动度，每1-3个月调整方案"], "drug_recommendations": ["传统DMARDs：甲氨蝶呤7.5-25mg/w(口服/皮下，首选，加叶酸5mg/w)、来氟米特10-20mg qd、柳氮磺吡啶1-3g/d、羟氯喹0.2g bid", "生物制剂：TNF抑制剂(阿达木单抗40mg q2w、英夫利昔单抗3mg/kg 0/2/6周后q8w、依那西普25mg biw/50mg qw、戈利木单抗50mg qw)、IL-6抑制剂(托珠单抗8mg/kg q4w)、T细胞共刺激抑制剂(阿巴西普)、抗CD20(利妥昔单抗1g 0/2周，B细胞清除)", "JAK抑制剂：托法替布5mg bid、巴瑞替尼2mg qd、乌帕替尼15mg qd(口服，注意感染/血栓/心血管风险)", "糖皮质激素：泼尼松5-10mg qd桥接，或甲泼尼龙40-80mg iv×3天(重症)，尽快减停", "NSAIDs：塞来昔布0.2g bid、双氯芬酸50mg tid、依托考昔60mg qd(注意胃肠/肾/心血管)", "局部：关节腔注射曲安奈德/倍他米松，外用NSAIDs乳膏"], "non_pharmacological": ["患者教育：疾病认知、用药依从性、自我管理", "休息与运动平衡：急性期休息，缓解期功能锻炼", "物理治疗：热疗、冷疗、经皮神经电刺激(TENS)、水疗", "康复锻炼：关节活动度训练、肌力训练、有氧运动(游泳/散步/太极)", "关节保护：避免过度使用小关节，使用辅助工具(开瓶器/加粗手柄)", "戒烟：吸烟加重RA病情和骨侵蚀，必须戒烟", "营养：均衡饮食，骨质疏松者补钙和维生素D", "心理支持：慢性病抑郁焦虑常见"], "complications": ["关节畸形：尺偏、天鹅颈、纽扣花、掌指关节半脱位，晚期功能丧失", "间质性肺病：RA最常见关节外表现，干咳气短，HRCT评估，免疫抑制治疗", "心血管疾病：RA患者冠心病/心衰风险增加，控制炎症+传统危险因素", "骨质疏松：炎症+激素+活动少，双能X线评估，补钙维D+双膦酸盐", "感染：DMARDs/生物制剂/JAK抑制剂免疫抑制，筛查结核乙肝，疫苗接种", "恶性肿瘤：淋巴瘤风险轻度增加(与慢性炎症相关)，长期随访", "药物不良反应：甲氨蝶呤(肝/肺/骨髓)、生物制剂(感染/结核)、JAK(血栓/心血管)"], "monitoring": ["治疗初期：每1-3个月评估DAS28、CRP/ESR，调整方案", "稳定期：每3-6个月评估", "甲氨蝶呤：用药前查血常规、肝肾功、胸片、乙肝丙肝；用药后每1-3个月查血常规肝肾功", "生物制剂：用药前筛查结核(PPD/IGRA)、乙肝、丙肝、胸片；用药后每3-6个月查血常规肝肾功", "JAK抑制剂：用药前和用药中查血常规、血脂、肝酶、血栓/心血管风险", "影像学：每年X线评估骨侵蚀进展，超声/核磁评估滑膜炎", "合并症筛查：间质性肺病(HRCT)、心血管、骨质疏松"], "special_populations": ["妊娠：甲氨蝶呤/来氟米特/利妥昔单抗禁用，羟氯喹/柳氮磺吡啶/硫唑嘌呤/TNF抑制剂(孕中晚期)可用，孕前3月停甲氨蝶呤，计划妊娠者提前调整", "老年：注意感染风险，生物制剂/JAK抑制剂谨慎，合并症多，药物相互作用", "合并间质性肺病：避免甲氨蝶呤(肺毒性)，选利妥昔单抗/阿巴西普，激素+免疫抑制剂", "难治性RA：多药联合，评估依从性/诊断/合并症，考虑新药或临床试验", "青少年特发性关节炎(JIA)：儿科风湿专科，治疗原则类似但剂量按体重"], "references": "中华医学会风湿病学分会. 类风湿关节炎诊断及治疗指南(2024). 中华风湿病学杂志", "py": "lfsgjyzdjzlzn（"}, {"name": "系统性红斑狼疮诊断及治疗指南（2024）", "category": "风湿免疫科", "scope": "成人系统性红斑狼疮(SLE)诊断和治疗。", "diagnosis": ["2019 EULAR/ACR分类标准：入围标准ANA≥1:80，附加标准(临床7项+免疫3项)总分≥10分诊断SLE", "典型表现：面部蝶形红斑、盘状红斑、光过敏、口腔溃疡、关节炎、浆膜炎(胸膜炎/心包炎)、肾脏病变、神经病变、血液学异常、免疫学异常(抗dsDNA/抗Sm/抗磷脂)、ANA阳性", "实验室：ANA阳性(>95%)、抗dsDNA(活动期)、抗Sm(特异性)、补体C3/C4降低(活动期)、抗磷脂抗体", "肾脏评估：尿常规(蛋白尿/血尿/管型)、24h尿蛋白、肾穿刺活检(明确病理类型和活动度)", "神经精神狼疮：头痛、癫痫、脑血管病、认知障碍、精神病，排除其他原因", "排除其他：类风湿关节炎、干燥综合征、混合性结缔组织病、药物性狼疮、感染"], "staging": ["疾病活动度：SLEDAI-2K评分(0-4无活动、5-9轻度、10-14中度、≥15重度)、BILAG", "狼疮肾炎分型(I型轻微系膜、II系膜增生、III局灶增生、IV弥漫增生、V膜性、VI硬化)", "器官受累：皮肤黏膜、肌肉骨骼、肾脏、神经、心血管、肺、血液、消化", "预后不良因素：狼疮肾炎(尤其IV型)、神经精神狼疮、肺动脉高压、间质性肺病、抗磷脂综合征、男性、黑人", "缓解定义：无临床活动+免疫稳定，药物缓解(用药中)和无药缓解"], "key_points": ["早期诊断早期治疗，目标治疗，目标缓解或低活动度", "羟氯喹是基础用药，所有SLE患者均应使用(除非禁忌)", "糖皮质激素：根据活动度选择剂量，尽快减至最小维持(<7.5mg/d泼尼松)", "免疫抑制剂：中重度活动加用(环磷酰胺/吗替麦考酚酯/硫唑嘌呤/他克莫司)", "狼疮肾炎：诱导缓解(激素+吗替麦考酚酯/环磷酰胺)，维持治疗(吗替麦考酚酯/硫唑嘌呤)≥3年", "生物制剂：贝利尤单抗(抗BLyS)、泰它西普(抗BLyS/APRIL)用于中重度活动", "避免日晒，戒烟，预防感染，避孕(活动期)"], "drug_recommendations": ["羟氯喹：0.2g bid(基础用药，所有患者，注意眼底检查每年)", "糖皮质激素：轻度泼尼松5-15mg/d，中度15-30mg/d，重度0.5-1mg/kg/d，冲击甲泼尼龙0.5-1g/d×3天(重症)，渐减至<7.5mg/d维持", "免疫抑制剂：吗替麦考酚酯1-2g/d分2次(狼疮肾炎首选诱导/维持)、环磷酰胺0.5-1g/m²每月冲击×6次(重症诱导)或50mg bid口服、硫唑嘌呤50-100mg/d(维持)、他克莫司2-3mg/d分2次(膜性狼疮/V型)、环孢素A 3-5mg/kg/d分2次", "生物制剂：贝利尤单抗10mg/kg 0/2/4周后每月1次、泰它西普160mg每周皮下、利妥昔单抗1g 0/2周(难治性/血细胞减少)", "抗疟药：羟氯喹(上述)", "对症：NSAIDs(关节痛)、降压(狼疮肾炎高血压ACEI/ARB)、抗凝(抗磷脂综合征)", "补钙+维生素D+双膦酸盐(激素治疗预防骨质疏松)"], "non_pharmacological": ["避光：避免日晒，防晒霜(SPF≥30)、遮阳伞、长袖衣物", "戒烟：吸烟加重病情和皮肤损害，降低羟氯喹疗效", "休息与运动：急性期休息，缓解期适度运动(散步/游泳/太极)", "饮食：均衡，光敏性食物(芹菜/香菜/无花果)适量，肾损害限盐限蛋白", "避孕：活动期避免妊娠，用避孕套或含孕激素IUD，避免含雌激素避孕药(抗磷脂阳性禁用)", "疫苗接种：流感、肺炎球菌、HPV(免疫抑制前接种，避免活疫苗)", "心理支持：慢性病容貌损害，抑郁焦虑常见", "定期随访，自我监测病情变化"], "complications": ["狼疮肾炎：最常见严重并发症，蛋白尿/血尿/肾功不全，肾穿刺指导治疗，可进展至ESRD", "神经精神狼疮：癫痫/脑血管病/认知障碍/精神病，激素冲击+免疫抑制剂，排除感染", "抗磷脂综合征：血栓/反复流产/血小板减少，抗凝治疗(华法林目标INR2-3)", "肺动脉高压：预后差，超声筛查，靶向药物+免疫抑制", "间质性肺病/肺泡出血：干咳气短，HRCT，激素+免疫抑制剂，肺泡出血危及生命", "心血管：早发动脉粥样硬化/冠心病/心包炎/心肌炎，控制炎症+危险因素", "感染：免疫抑制致感染风险高(结核/真菌/病毒)，是SLE主要死因之一", "药物不良反应：激素(骨质疏松/高血糖/感染)、环磷酰胺(骨髓抑制/出血性膀胱炎/性腺抑制/致癌)、羟氯喹(眼底/心肌)"], "monitoring": ["活动期：每2-4周查血常规、尿常规、肝肾功、补体、抗dsDNA、CRP/ESR", "稳定期：每1-3个月复查", "狼疮肾炎：尿常规、24h尿蛋白、肾功能每2-4周，肾穿刺指导治疗", "羟氯喹：用药前和每年眼底检查(视野+OCT)", "免疫抑制剂：血常规、肝肾功每1-4周(初期)，之后每1-3月", "妊娠计划：病情稳定≥6月，停用致畸药(吗替麦考酚酯/环磷酰胺/甲氨蝶呤)≥3-6月，羟氯喹/硫唑嘌呤/激素可继续", "骨密度：长期激素者每年双能X线"], "special_populations": ["妊娠：病情稳定≥6月，无重要脏器损害，停用致畸药；孕期用羟氯喹+小剂量激素+硫唑嘌呤；抗磷脂阳性者低分子肝素+小剂量阿司匹林预防流产/血栓；孕期病情活动可激素加量", "儿童SLE：起病急重，多系统受累，肾损害多见，治疗原则相同剂量按体重，注意生长发育", "老年SLE：起病隐匿，病情轻，干燥/关节/肺表现多，注意合并肿瘤和感染", "男性SLE：少见，病情重，肾损害和神经系统受累多，预后差", "药物性狼疮：停用可疑药物(肼苯哒嗪/普鲁卡因胺/异烟肼/米诺环素)，多可缓解，抗组蛋白抗体阳性"], "references": "中华医学会风湿病学分会. 系统性红斑狼疮诊断及治疗指南(2024). 中华风湿病学杂志", "py": "xtxhblczdjzlzn（"}, {"name": "肿瘤化疗所致恶心呕吐全程管理指南（2024）", "category": "肿瘤科", "scope": "肿瘤化疗所致恶心呕吐(CINV)的预防和处理。", "diagnosis": ["CINV分类：急性(化疗后24h内)、延迟性(24h后，可持续5-7天)、预期性(化疗前，条件反射)、爆发性(预防后仍发生)、难治性(既往预防失败)", "致吐风险分级：高度(>90%，如顺铂/AC方案)、中度(30-90%，如卡铂/奥沙利铂/多柔比星)、低度(10-30%，如紫杉醇/多西他赛)、极低(<10%，如贝伐珠单抗/靶向药)", "危险因素：女性、年龄<50岁、既往CINV史、晕动症、焦虑、妊娠呕吐史、酒精摄入少", "评估：MASCC止吐评价工具，记录恶心呕吐发生时间、频率、严重度、对生活影响", "鉴别：肠梗阻、脑转移、电解质紊乱(高钙/低钠)、尿毒症、阿片类药物、感染所致呕吐"], "staging": ["致吐风险分级(上述)", "CINV严重度：轻度(1-2次/24h)、中度(3-5次)、重度(6-10次)、极重度(>10次需住院)", "恶心程度：VAS评分0-10分", "功能影响：轻度(不影响进食活动)、中度(影响进食但能下床)、重度(不能进食需卧床/静脉补液)", "爆发性呕吐：预防方案下仍发生，需解救治疗", "难治性：既往多个周期预防失败"], "key_points": ["预防为主，根据致吐风险分级选择止吐方案", "高致吐：三联(5-HT3受体拮抗剂+地塞米松+NK1受体拮抗剂)，必要时加奥氮平(四联)", "中致吐：5-HT3+地塞米松，高风险者加NK1或奥氮平", "低致吐：地塞米松或胃复安/丙氯拉嗪", "极低致吐：不常规预防，必要时对症", "延迟性呕吐：地塞米松+NK1(高致吐)，5-HT3对延迟性效果差", "预期性呕吐：苯二氮䓬类(阿普唑仑)+行为干预(放松/催眠)", "爆发性：解救止吐(不同机制药物联合)+静脉补液，下一周期加强预防"], "drug_recommendations": ["5-HT3受体拮抗剂：昂丹司琼8mg iv/po(化疗前30min)、格拉司琼3mg iv、帕洛诺司琼0.25mg iv(长效，对急性和延迟性均好)、托烷司琼5mg iv", "NK1受体拮抗剂：阿瑞匹坦125mg d1(化疗前1h)+80mg d2-3 qd、福沙匹坦150mg iv d1(替代阿瑞匹坦d1)、奈妥匹坦(与帕洛诺司琼复方)", "糖皮质激素：地塞米松12mg d1(与NK1联用时减至8mg)+8mg d2-4(高致吐延迟性)，中致吐d1 8mg", "奥氮平：5-10mg qn d1-4(高致吐四联，注意嗜睡/体位性低血压)", "多巴胺受体拮抗剂：胃复安10mg iv/po q6h、丙氯拉嗪10mg iv q6h、氟哌啶醇1-2mg iv(注意锥体外系反应，苯海拉明对抗)", "苯二氮䓬类：阿普唑仑0.5-1mg q8h(预期性呕吐)、劳拉西泮0.5-1mg iv/po(焦虑/预期性)", "爆发性解救：联合不同机制(如胃复安+苯海拉明+地塞米松)，或奥氮平5-10mg，静脉补液纠正脱水电解质"], "non_pharmacological": ["饮食：少量多餐，清淡易消化，避免油腻辛辣过甜，化疗前后2h避免大量进食", "环境：避免异味(油烟/香水)，通风，室温适宜", "穴位按压：内关穴(P6)，可配合穴位电刺激", "行为干预：放松训练、音乐疗法、引导想象、催眠(预期性呕吐有效)", "生姜：姜片/姜茶(轻度恶心辅助)", "补液：呕吐明显时静脉补液纠正脱水和电解质紊乱", "口腔护理：呕吐后漱口，避免口腔异味刺激", "心理支持：焦虑加重CINV，认知行为治疗"], "complications": ["脱水/电解质紊乱：呕吐致低钾低钠低氯、代谢性碱中毒，静脉补液纠正", "营养不良：长期CINV致体重下降、白蛋白降低，营养支持(肠内/肠外)", "食管黏膜撕裂(Mallory-Weiss)：剧烈呕吐致食管贲门撕裂出血，呕血黑便，禁食+抑酸+止血", "误吸/吸入性肺炎：意识障碍者呕吐误吸，侧卧位，吸引，抗感染", "化疗药物外渗/延迟：严重呕吐影响化疗依从性，加强预防", "预期性呕吐：条件反射，后续化疗前发生，苯二氮䓬+行为干预", "生活质量下降：影响治疗信心和日常功能"], "monitoring": ["化疗期间：每4-8h评估恶心呕吐次数、严重度、进食情况、脱水征象", "记录呕吐日记：时间、次数、诱因、止吐药效果", "实验室：电解质(钾钠氯)、肾功能、白蛋白", "评估止吐方案效果，下一周期调整(爆发性者升级预防)", "评估药物不良反应：便秘(5-HT3)、头痛、呃逆(地塞米松)、嗜睡(奥氮平)、锥体外系(胃复安/丙氯拉嗪)", "患者教育：CINV预防重要性，居家呕吐处理和就医指征"], "special_populations": ["老年：注意药物相互作用和不良反应，5-HT3 QT延长(尤其昂丹司琼)，奥氮平嗜睡跌倒，简化方案", "儿童：按体重算剂量，昂丹司琼0.15mg/kg，阿瑞匹坦按体重，家长教育", "妊娠相关肿瘤：避免致畸止吐药，用胃复安/昂丹司琼(相对安全)，多学科", "脑转移：呕吐可能为颅内压增高，甘露醇+激素，鉴别CINV", "肠梗阻：肿瘤致肠梗阻呕吐，胃肠减压+生长抑素，止吐药效果差", "阿片类药物所致恶心呕吐：胃复安/昂丹司琼，耐受后多可缓解"], "references": "中国抗癌协会肿瘤临床化疗专业委员会. 肿瘤化疗所致恶心呕吐全程管理指南(2024). 中国肿瘤临床", "py": "zlhlszexotqcglzn（"}, {"name": "癌症疼痛诊疗规范（2024年版）", "category": "肿瘤科", "scope": "癌症患者疼痛评估和治疗(癌痛三阶梯止痛)。", "diagnosis": ["癌痛评估：常规、量化、全面、动态评估", "疼痛强度：数字评分法(NRS 0-10)，0无痛，1-3轻度，4-6中度，7-10重度", "疼痛性质：伤害感受性(躯体痛/内脏痛)、神经病理性(烧灼/电击/麻木)、混合性", "疼痛病因：肿瘤直接侵犯(70%)、抗肿瘤治疗相关(手术/化疗/放疗)、合并症(非癌痛)", "全面评估：疼痛部位、性质、强度、时间、加重缓解因素、既往止痛史、心理状态、阿片类物质使用史", "动态评估：止痛治疗后定期复评(口服1h、静脉15-30min)，调整剂量", "爆发痛：基础疼痛控制好后突发剧痛，需解救剂量"], "staging": ["WHO三阶梯：轻度(非阿片类±辅助)、中度(弱阿片类±非阿片±辅助)、重度(强阿片类±非阿片±辅助)", "目前趋势：弱化二阶梯，中度疼痛可直接用小剂量强阿片类", "疼痛控制目标：NRS≤3分(无痛或轻度)，24h爆发痛≤2-3次，解救药≤2-3次/d", "神经病理性疼痛：阿片类+辅助药(抗惊厥/抗抑郁)", "内脏痛：阿片类+抗胆碱能/糖皮质激素", "骨转移痛：阿片类+NSAIDs+双膦酸盐/地诺单抗+放疗"], "key_points": ["口服给药首选(简单方便经济)，不能口服选透皮贴/直肠/静脉/皮下", "按阶梯给药(轻度NSAIDs，中重度阿片类)", "按时给药(缓释制剂维持基础镇痛，不是按需)", "个体化给药(剂量滴定至有效，无天花板效应)", "注意细节(不良反应预防和处理)", "阿片类是中重度癌痛首选，剂量无上限(以镇痛和耐受为度)", "爆发痛用即释阿片类解救(剂量为日剂量的10-15%)", "辅助用药：神经病理性加抗惊厥/抗抑郁，骨转移加双膦酸盐，内脏痛加激素/抗胆碱能"], "drug_recommendations": ["非阿片类：对乙酰氨基酚0.5-1g q6h(最大4g/d，注意肝毒性)、NSAIDs(塞来昔布0.2g bid、双氯芬酸50mg tid，注意胃肠/肾/心血管，有天花板)", "弱阿片类：可待因15-60mg q4-6h、曲马多50-100mg q4-6h(最大400mg/d)", "强阿片类即释(滴定)：吗啡5-15mg po q4h(未耐受者起始5mg)，或吗啡2-5mg iv q10-15min滴定", "强阿片类缓释(维持)：吗啡缓释片10-30mg q12h、羟考酮缓释片5-10mg q12h、芬太尼透皮贴12-25μg/h q72h(阿片耐受者，不能用于未耐受/急性痛)", "爆发痛解救：即释吗啡(日剂量10-15%)，或芬太尼舌下/鼻喷雾", "辅助药神经病理性：加巴喷丁0.3g tid起渐加、普瑞巴林75mg bid、阿米替林12.5-25mg qn、度洛西汀30-60mg qd", "辅助药骨转移：唑来膦酸4mg iv每月、地诺单抗120mg皮下每月、放疗", "辅助药内脏痛/脑水肿：地塞米松4-16mg/d", "阿片不良反应预防：便秘(缓泻剂常规预防，如乳果糖15ml bid/聚乙二醇)、恶心(胃复安，耐受后多缓解)、嗜睡(耐受)、呼吸抑制(罕见，纳洛酮解救)"], "non_pharmacological": ["患者教育：癌痛可控制，阿片类成瘾罕见(癌痛患者)，按时用药不按需", "心理干预：认知行为治疗、放松训练、音乐疗法、支持性心理治疗", "物理治疗：热敷/冷敷、按摩、经皮神经电刺激(TENS)、针灸", "介入治疗：神经阻滞(腹腔神经丛阻滞治胰腺癌痛)、鞘内药物输注系统、射频消融、椎体成形术(骨转移)", "放疗：骨转移痛、脑转移痛局部放疗有效", "社会支持：家属陪伴、姑息治疗团队、志愿者", "营养支持：改善一般状况", "宗教/精神支持(患者有需求时)"], "complications": ["阿片类便秘：最常见，不会耐受，常规预防(缓泻剂+饮食+运动)，严重者灌肠", "阿片类恶心呕吐：用药初期，胃复安，1-2周耐受", "阿片类嗜睡/头晕：初期，耐受，避免驾驶", "阿片类呼吸抑制：罕见(缓慢滴定)，嗜睡先于呼吸抑制，纳洛酮解救(0.4mg iv稀释慢推)", "阿片类耐受/躯体依赖：正常药理现象，不是成瘾，逐渐减量避免戒断", "成瘾(心理依赖)：癌痛患者罕见(<0.1%)，不必因担心成瘾拒绝止痛", "NSAIDs不良反应：胃肠溃疡出血、肾损伤、心血管事件、血小板功能，有天花板效应不超量", "镇痛不全：评估疼痛性质，调整剂量/加辅助药/介入治疗"], "monitoring": ["止痛治疗后：口服1h、静脉15-30min复评疼痛强度和不良反应", "稳定期：每24h评估，调整剂量", "便秘评估和预防：每次随访", "肾功能/肝功能：NSAIDs和阿片类(肾功能不全吗啡代谢产物蓄积，换芬太尼/羟考酮)", "镇静程度：RASS评分，过度镇静提示剂量过大", "爆发痛次数和解救药使用：>3次/d提示基础剂量不足，增加缓释剂量", "患者依从性和用药正确性(缓释片不可掰开/咀嚼)", "生活质量和功能状态评估"], "special_populations": ["老年：肝肾功能减退，小剂量起始，缓慢滴定，注意便秘和认知，芬太尼透皮贴方便(依从性好)", "肾功能不全：避免吗啡(代谢产物蓄积致肌阵挛/嗜睡)，选芬太尼/羟考酮/美沙酮", "肝功能不全：阿片类清除减少，小剂量，避免对乙酰氨基酚(肝毒性)", "儿童：按体重算剂量，吗啡0.2-0.5mg/kg po q4h，家长教育", "临终关怀：舒适优先，阿片类剂量可快速滴定，缓解呼吸困难也有效", "既往物质使用障碍：多学科管理，不拒绝止痛，可能需更高剂量，监测非医疗使用"], "references": "国家卫生健康委员会. 癌症疼痛诊疗规范(2024年版)", "py": "azttzlgf（nb）"}, {"name": "急性呼吸窘迫综合征诊疗指南（2024）", "category": "重症医学科", "scope": "成人急性呼吸窘迫综合征(ARDS)诊断和治疗。", "diagnosis": ["柏林定义：1周内新发/恶化呼吸系统症状；胸部影像(胸片/CT)双肺浸润不能完全用积液/肺不张/结节解释；呼吸衰竭不能用心衰/液体过负荷解释(无危险因素时需客观评估如心超)；氧合障碍(PEEP/CPAP≥5cmH2O时PaO2/FiO2≤300)", "危险因素：肺炎(最常见)、脓毒症、误吸、胰腺炎、创伤、输血、烧伤、药物中毒、溺水", "轻度：PaO2/FiO2 200-300(PEEP≥5)；中度：100-200；重度：<100", "辅助检查：血气分析(低氧血症/呼吸性酸中毒)、胸片/CT(双肺浸润/磨玻璃/实变)、心超(排除心源性肺水肿)、B型脑钠肽(鉴别心衰)、炎症指标", "鉴别：心源性肺水肿、肺炎(可致ARDS)、弥漫性肺泡出血、急性间质性肺炎、肺血管炎", "肺损伤生物标志物：KL-6、SP-D、IL-6、ANG-2(研究阶段)"], "staging": ["柏林分级：轻度(PaO2/FiO2 200-300)、中度(100-200)、重度(<100)", "病程分期：渗出期(1-7天，肺水肿/炎症)、增生期(7-21天，Ⅱ型肺泡细胞增生/纤维化开始)、纤维化期(>21天，肺纤维化/囊性变)", "预后评估：APACHE II、SOFA评分、肺损伤评分(LIS)", "高危因素：直接肺损伤(肺炎/误吸/肺挫伤)、间接肺损伤(脓毒症/胰腺炎/输血/创伤)", "机械通气参数：潮气量、PEEP、平台压、驱动压、呼吸频率", "脱机评估：自主呼吸试验(SBT)、浅快呼吸指数"], "key_points": ["原发病治疗：控制感染(抗生素+感染灶引流)、纠正休克、停止损伤因素", "肺保护性通气：小潮气量(6ml/kg理想体重)、平台压≤30cmH2O、限制驱动压(ΔP≤15)", "PEEP滴定：根据FiO2-PEEP表或食道压，中重度用较高PEEP", "俯卧位通气：中重度ARDS(PaO2/FiO2<150)，每天≥12小时", "液体管理：保守液体策略(稳定期)，避免液体过负荷", "神经肌肉阻滞剂：中重度ARDS早期短期使用(≤48h)", "ECMO：重度ARDS常规治疗无效(PaO2/FiO2<80持续>6h或pH<7.25)，VV-ECMO", "避免高氧(PaO2 55-80/SpO2 88-95%)"], "drug_recommendations": ["抗菌药物：脓毒症/肺炎相关ARDS，经验性广谱抗生素(覆盖革兰阴性+阳性+非典型)，根据病原学降阶梯", "糖皮质激素：中重度ARDS早期(72h内)地塞米松20mg qd×5天→10mg×5天→5mg×3天，或甲泼尼龙1mg/kg/d(争议，部分研究获益)", "神经肌肉阻滞剂：顺阿曲库铵0.1-0.2mg/kg负荷后0.1-0.3mg/kg/min泵入，中重度ARDS早期≤48h", "血管活性药：脓毒症休克去甲肾上腺素0.05-1μg/kg/min维持MAP≥65", "镇静镇痛：咪达唑仑/丙泊酚+芬太尼/瑞芬太尼，目标RASS -2至-4(俯卧位/人机不同步更深)", "支气管扩张剂：合并支气管痉挛时雾化沙丁胺醇/异丙托溴铵", "抗凝：预防深静脉血栓(低分子肝素)，除非禁忌", "吸入肺血管扩张剂：一氧化氮(NO)或前列环素吸入(难治性低氧，不改善生存)"], "non_pharmacological": ["机械通气：有创通气首选，小潮气量6ml/kg理想体重，平台压≤30，PEEP滴定", "高流量氧疗/无创通气：轻度ARDS可尝试，密切监测，恶化及时插管", "俯卧位通气：中重度(PaO2/FiO2<150)，每天≥12h，注意管路安全和压疮", "肺复张：控制性肺膨胀(30-40cmH2O×30-40s)或PEEP递增法，血流动力学不稳定慎用", "保守液体策略：稳定期限制液体(入量≤出量)，利尿剂(液体过负荷时)", "ECMO：VV-ECMO(重度呼吸衰竭)，中心建立，抗凝管理", "营养支持：肠内营养优先(48h内开始)，允许性低热卡(初期)，蛋白1.2-2g/kg/d", "气道管理：密闭式吸痰，避免脱开PEEP，声门下吸引"], "complications": ["呼吸机相关肺损伤(VILI)：气压伤/容积伤/萎陷伤/生物伤，小潮气量+限制平台压预防", "呼吸机相关肺炎(VAP)：抬高床头30-45°、每日唤醒评估脱机、口腔护理、声门下吸引", "气压伤：气胸/纵隔气肿/皮下气肿，胸腔闭式引流", "深静脉血栓/肺栓塞：常规预防(低分子肝素+气压治疗)", "应激性溃疡：PPI/H2RA预防，注意增加肺炎风险", "ICU获得性肌无力：早期活动、避免过度镇静和神经肌肉阻滞剂、营养支持", "肺纤维化：晚期ARDS，激素(争议)、康复，预后差", "多器官功能衰竭：肾(血液滤过)、肝、心、凝血(DIC)，综合支持"], "monitoring": ["持续：心电、血压(有创)、血氧、呼吸频率、潮气量、气道压(平台压/PEEP/驱动压)、ETCO2", "血气分析：每4-8h或参数调整后，评估氧合和通气", "胸片/CT：每日或病情变化时，评估肺部病变和导管位置", "血流动力学：PiCCO/心超评估容量和心功能，指导液体管理", "镇静深度：RASS评分，每4h评估", "神经肌肉阻滞：TOF监测(四个成串刺激，目标1-2/4)", "器官功能：肾功能(尿量/肌酐)、肝功能、凝血、乳酸、炎症指标", "每日唤醒和脱机评估：SBT( T管/PSV)，浅快呼吸指数<105预测脱机成功"], "special_populations": ["老年：基础病多，预后差，肺保护性通气同样适用，注意容量和肾功能", "免疫低下：感染病原特殊(真菌/肺孢子菌/病毒)，积极病原学检查，覆盖特殊病原", "创伤相关ARDS：处理原发病(骨折固定/颅脑损伤)，注意容量和凝血病", "妊娠：ARDS少见但危重，左侧卧位，氧合目标更高(SpO2≥95)，必要时终止妊娠", "儿童：儿科ARDS(PARDS)定义略有不同，小潮气量3-6ml/kg，俯卧位适用", "肥胖：理想体重算潮气量，较高PEEP，注意腹压影响呼吸"], "references": "中华医学会重症医学分会. 急性呼吸窘迫综合征诊疗指南(2024). 中华内科杂志", "py": "jxhxjpzhzzlzn（"}, {"name": "ICU成人疼痛、躁动、谵妄管理指南（2024）", "category": "重症医学科", "scope": "ICU成人患者疼痛、躁动和谵妄(PAD)评估和管理。", "diagnosis": ["疼痛评估：能交流者用NRS(0-10)，不能交流者用行为疼痛量表(BPS)或重症疼痛观察工具(CPOT)", "躁动评估：RASS评分(+4攻击到-5不可唤醒)，目标轻度镇静(-2至0)", "谵妄评估：CAM-ICU或ICDSC，每日评估，分活动增多型/活动减少型/混合型", "危险因素：疼痛、睡眠剥夺、约束、机械通气、镇静药(苯二氮䓬)、感染、代谢紊乱、老年、痴呆、酒精戒断", "睡眠评估：ICU睡眠质量差，主观/客观评估(脑电双频指数BIS/脑电)", "鉴别：疼痛、躁动、谵妄、癫痫、脑器质性病变、药物不良反应、戒断综合征"], "staging": ["疼痛：轻度(NRS1-3)、中度(4-6)、重度(7-10)", "镇静深度(RASS)：+4攻击、+3非常躁动、+2躁动、+1不安、0清醒平静、-1嗜睡、-2轻度镇静、-3中度镇静、-4深度镇静、-5不可唤醒", "谵妄：CAM-ICU阳性(意识改变+注意力不集中+思维紊乱+意识水平改变)", "镇静目标：常规-2至0(清醒镇静)，特殊情况(ARDS/颅高压/难治性休克)更深(-3至-4)", "镇痛优先：先评估镇痛，镇静前先镇痛", "每日唤醒：中断镇静，评估神经功能和脱机可能性"], "key_points": ["镇痛优先：先镇痛再镇静，阿片类是ICU镇痛首选", "目标导向镇静：RASS目标-2至0，每日评估调整", "最小化镇静：避免过度镇静，每日唤醒，缩短机械通气和ICU住院", "非苯二氮䓬类优先：丙泊酚或右美托咪定优于苯二氮䓬(减少谵妄)", "谵妄预防：非药物干预为主(早期活动、睡眠改善、定向力、减少约束)", "药物治疗谵妄：氟哌啶醇或非典型抗精神病药(喹硫平)，不常规预防", "多模式镇痛：阿片类+非阿片(对乙酰氨基酚/NSAIDs/区域阻滞)，减少阿片用量", "睡眠改善：集中护理、减少夜间干扰、耳塞眼罩、模拟昼夜"], "drug_recommendations": ["镇痛阿片类：芬太尼0.3-0.5μg/kg负荷后0.7-10μg/kg/h泵入(短效)、吗啡0.05-0.1mg/kg负荷后0.07-0.28mg/kg/h、氢吗啡酮0.2-0.6mg/h、瑞芬太尼0.5-8μg/kg/h(超短效，肝外代谢)", "非阿片镇痛：对乙酰氨基酚1g q6h(肝功能正常)、NSAIDs(短期，注意肾/胃肠/出血)、氯胺酮0.1-0.3mg/kg/h(辅助镇痛，减少阿片)、区域阻滞(硬膜外/神经阻滞，术后/创伤)", "镇静丙泊酚：0.3-0.5mg/kg负荷后5-50μg/kg/min泵入，注意高脂血症/丙泊酚输注综合征", "镇静右美托咪定：0.2-0.7μg/kg/h(可不用负荷或0.5-1μg/kg 10min)，可唤醒，减少谵妄，注意心动过缓/低血压", "苯二氮䓬类：咪达唑仑0.01-0.1mg/kg负荷后0.02-0.1mg/kg/h(酒精戒断/癫痫/难治性躁动，不常规首选)、劳拉西泮0.02-0.06mg/kg q2-6h", "谵妄药物：氟哌啶醇0.5-2mg iv q4-6h(注意QT延长)、喹硫平12.5-100mg qn(非典型，活动增多型)、右美托咪定(辅助)", "神经肌肉阻滞剂：顺阿曲库铵(特定指征ARDS/颅高压/人机不同步，深度镇静+镇痛基础上)"], "non_pharmacological": ["疼痛非药物：放松训练、音乐疗法、冷敷热敷、体位调整、分散注意力", "躁动非药物：解释安慰、家属陪伴、环境优化(减少噪音光线)、早期活动、避免约束(必要时用最小约束)", "谵妄预防ABCDEF集束：A唤醒协调、B自主呼吸试验、C镇痛镇静选择、D谵妄评估管理、E早期活动、F家属参与", "睡眠改善：集中护理操作、夜间减少干扰、耳塞眼罩、模拟昼夜节律(白天亮灯夜间暗)、避免白天过度睡眠", "早期活动：病情稳定后被动/主动活动，减少ICU获得性肌无力和谵妄", "定向力：时钟日历、眼镜助听器、家属照片、频繁交流", "减少医源性刺激：尽量减少有创操作，合理约束，避免不必要的报警噪音"], "complications": ["过度镇静：延迟脱机、ICU获得性肌无力、谵妄、深静脉血栓、压疮", "镇痛不足：躁动、人机不同步、应激反应(高血糖/高血压/心动过速)、创伤后应激障碍(PTSD)", "谵妄：延长机械通气和ICU住院、增加死亡率、长期认知功能下降", "阿片类不良反应：呼吸抑制(机械通气者可控)、便秘、肠梗阻、耐受/依赖、戒断(长期用后突然停)", "丙泊酚输注综合征：长期大剂量(>4mg/kg/h>48h)致代谢性酸中毒/横纹肌溶解/心衰/死亡，监测肌酸激酶/乳酸", "苯二氮䓬类：谵妄风险、呼吸抑制、耐受戒断、老年人跌倒", "氟哌啶醇：QT延长/尖端扭转型室速，监测QTc<500ms", "神经肌肉阻滞剂：长期用致肌无力，需深度镇静+镇痛，监测TOF"], "monitoring": ["疼痛：每2-4h或操作前后评估(NRS/BPS/CPOT)", "镇静：每2-4h评估RASS，调整药物维持目标", "谵妄：每日评估CAM-ICU/ICDSC，至少每班一次", "镇静深度客观：BIS(40-60深度镇静)或脑电监测(难治性镇静/神经肌肉阻滞时)", "生命体征：血压、心率、血氧、呼吸(药物影响)", "药物不良反应：便秘、意识状态、QT间期(氟哌啶醇)、甘油三酯(丙泊酚)、乳酸/肌酸激酶(丙泊酚综合征)", "每日唤醒：中断镇静，评估神经功能、脱机可能性、药物需求", "戒断评估：长期阿片/苯二氮䓬逐渐减量，评估戒断症状(焦虑/出汗/心动过速/震颤)"], "special_populations": ["老年：谵妄风险高，避免苯二氮䓬，小剂量起始，注意药物蓄积和认知", "慢性疼痛/阿片耐受者：基础阿片需求高，按换算剂量调整，避免戒断", "酒精/药物依赖：戒断风险，苯二氮䓬类预防酒精戒断(CIWA-Ar评分指导)，阿片替代", "颅脑损伤：镇静镇痛不影响神经评估，每日唤醒，避免颅内压升高，丙泊酚/芬太尼常用", "老年痴呆/认知障碍：谵妄风险极高，非药物预防为主，小剂量抗精神病药", "肾功能不全：避免吗啡(代谢产物蓄积)，选芬太尼/瑞芬太尼/舒芬太尼", "肝功能不全：药物清除减慢，小剂量，避免劳拉西泮(溶剂丙二醇毒性)"], "references": "中华医学会重症医学分会. ICU成人疼痛、躁动、谵妄管理指南(2024). 中华内科杂志", "py": "Icrtt、zd、zwglzn（"}, {"name": "中国银屑病诊疗指南（2024）", "category": "皮肤科", "scope": "成人和儿童银屑病(牛皮癣)诊断和治疗。", "diagnosis": ["典型表现：红色丘疹/斑块，上覆银白色鳞屑，边界清楚，刮除鳞屑有薄膜现象和点状出血(Auspitz征)", "好发部位：头皮、四肢伸侧(肘膝)、腰骶部，对称分布", "特殊类型：点滴状(链球菌感染后，儿童青少年)、脓疱型(泛发性/掌跖)、红皮病型、关节病型(银屑病关节炎)", "甲银屑病：甲凹点、甲剥离、甲下角化过度、油滴征", "同形反应(Koebner)：外伤部位出现皮损，活动期常见", "组织病理：角化过度伴角化不全、棘层肥厚、真皮乳头水肿、毛细血管扩张、Munro微脓肿", "鉴别：脂溢性皮炎、玫瑰糠疹、扁平苔藓、体癣、副银屑病、湿疹", "银屑病关节炎：炎性关节痛/肿胀，远端指间关节受累，腊肠指/趾，影像学骨侵蚀/骨赘"], "staging": ["严重程度：轻度(BSA<3%或PASI<10)、中度(BSA 3-10%或PASI 10-20)、重度(BSA>10%或PASI>20)", "BSA：体表面积受累(手掌法，患者手掌=1%BSA)", "PASI：银屑病面积和严重度指数(0-72)，评估红斑/浸润/鳞屑和面积", "DLQI：皮肤病生活质量指数(0-30)，>10提示严重影响生活", "疾病分期：进行期(新疹不断/同形反应)、静止期(稳定)、消退期(减少变淡)", "特殊类型严重度：泛发性脓疱型/红皮病型为重症，需系统治疗", "关节病型：关节活动度、影像学、炎症指标"], "key_points": ["治疗目标：控制皮损，提高生活质量，减少复发，避免不良反应", "轻度：外用药物为主(糖皮质激素+维生素D3衍生物)", "中重度：系统治疗(甲氨蝶呤/阿维A/环孢素)或生物制剂", "生物制剂是中重度银屑病重大进展：TNF抑制剂、IL-17抑制剂、IL-23抑制剂", "银屑病关节炎：甲氨蝶呤或生物制剂( TNF/IL-17/IL-23抑制剂)", "避免诱因：感染(链球菌)、外伤、精神紧张、饮酒、某些药物(β阻滞剂/锂剂/NSAIDs/抗疟药)", "长期管理：慢性病，定期随访，心理支持"], "drug_recommendations": ["外用糖皮质激素：弱效(氢化可的松)用于面部/皱褶，中效(曲安奈德)躯干四肢，强效(卤米松/氯倍他索)掌跖/肥厚皮损，连续不超过2-4周", "外用维生素D3衍生物：卡泊三醇软膏0.005% bid(非面部)、他卡西醇软膏(面部可用)，与激素交替/联合", "外用复方：卡泊三醇倍他米松凝胶/软膏qd(方便，依从性好)", "外用钙调磷酸酶抑制剂：他克莫司软膏0.03-0.1%、吡美莫司乳膏1%(面部/皱褶/生殖器，无激素副作用)", "系统甲氨蝶呤：7.5-25mg/w(口服/皮下)，加叶酸5mg/w，监测肝肾功血常规", "系统阿维A：0.3-0.5mg/kg/d(脓疱型可0.5-1mg/kg)，致畸(育龄期避孕)，监测血脂肝功", "系统环孢素：2.5-5mg/kg/d分2次，短期(≤1-2年)，监测肾功血压", "生物制剂TNF抑制剂：阿达木单抗40mg q2w、英夫利昔单抗5mg/kg 0/2/6周后q8w、依那西普50mg qw", "生物制剂IL-17抑制剂：司库奇尤单抗300mg 0/1/2/3/4周后q4w、依奇珠单抗80mg 0/2周后q4w、布罗利尤单抗", "生物制剂IL-23抑制剂：古塞奇尤单抗200mg 0/4周后q8w、替拉珠单抗、瑞莎珠单抗", "光疗：窄谱UVB(NB-UVB)每周2-3次，PUVA(中重度)"], "non_pharmacological": ["患者教育：慢性病不传染，治疗可控制，避免过度焦虑", "避免诱因：预防上呼吸道感染(链球菌诱发点滴状)，避免外伤(同形反应)，避免精神紧张熬夜", "饮食：均衡，避免饮酒(加重)，肥胖者减重(改善疗效)，戒烟", "皮肤护理：保湿润肤剂(每天2次)，温和清洁，避免热水烫洗和搔抓", "光疗：NB-UVB门诊治疗，注意保护眼睛和生殖器", "温泉浴/海水浴：部分患者有效，辅助治疗", "心理支持：容貌影响致抑郁焦虑，认知行为治疗，病友支持", "避免自行使用偏方(含激素/重金属，致红皮病型/脓疱型转化)"], "complications": ["银屑病关节炎：约30%患者，关节肿痛畸形，甲银屑病患者风险高，早期风湿科会诊", "代谢综合征：银屑病患者肥胖/高血压/高血糖/高血脂风险高，心血管病风险增加，综合管理", "心理问题：抑郁焦虑自杀风险增加，心理评估和干预", "药物不良反应：激素(皮肤萎缩/毛细血管扩张/反跳)、甲氨蝶呤(肝纤维化)、阿维A(致畸/血脂升高/皮肤干燥)、环孢素(肾毒性/高血压)、生物制剂(感染/结核)", "红皮病型/脓疱型转化：不规范治疗(突然停激素/刺激性外用药)可诱发，重症需住院", "感染：生物制剂增加结核/真菌/细菌感染风险，用药前筛查"], "monitoring": ["外用治疗：每2-4周评估皮损，调整方案，激素使用时间和部位", "系统治疗前：血常规、肝肾功、血脂、乙肝丙肝、结核筛查(IGRA/PPD)、胸片、妊娠试验", "系统治疗中：甲氨蝶呤每1-3个月查血常规肝肾功；阿维A每月查血脂肝功；环孢素每月查肾功血压", "生物制剂：用药前结核/乙肝/丙肝筛查，用药中每3-6个月查血常规肝肾功，感染征象", "PASI/BSA/DLQI：每4-12周评估疗效，达标(PASI 75/90/100)维持", "关节症状：每次随访评估关节肿痛，必要时风湿科会诊", "妊娠计划：阿维A停药后避孕3年，甲氨蝶呤停药3月，生物制剂孕期可用(部分)"], "special_populations": ["儿童：弱效激素/钙调磷酸酶抑制剂为主，严重者甲氨蝶呤/生物制剂，按体重算剂量，注意生长发育", "妊娠：外用弱中效激素/保湿安全，避免阿维A/甲氨蝶呤/环孢素，生物制剂( TNF抑制剂孕中晚期可用)，IL-17/IL-23数据有限", "老年：注意合并症和药物相互作用，生物制剂感染风险，环孢素肾毒性高血压", "红皮病型/脓疱型：住院治疗，阿维A或环孢素或生物制剂，支持治疗(补液/电解质/体温)", "银屑病关节炎：风湿科联合，甲氨蝶呤或生物制剂，康复锻炼", "合并炎症性肠病：避免IL-17抑制剂(可能加重)，选TNF/IL-23抑制剂"], "references": "中华医学会皮肤性病学分会. 中国银屑病诊疗指南(2024). 中华皮肤科杂志", "py": "zgyxbzlzn（"}, {"name": "特应性皮炎诊疗指南（2024）", "category": "皮肤科", "scope": "成人和儿童特应性皮炎(AD，异位性皮炎/湿疹)诊断和治疗。", "diagnosis": ["Williams标准：瘙痒+典型形态部位(屈侧皮炎/成人手湿疹/婴儿面头皮躯干)+慢性反复发作+个人/家族特应性史(哮喘/过敏性鼻炎/AD)+皮肤干燥", "婴儿期(2岁内)：面头皮躯干四肢伸侧红斑丘疹渗出，剧烈瘙痒", "儿童期(2-12岁)：屈侧(肘窝腘窝)苔藓化斑块，瘙痒", "青少年成人期：屈侧苔藓化，手湿疹常见，可泛发", "实验室：血嗜酸粒细胞升高、总IgE升高、过敏原sIgE阳性(辅助，非必需)", "特应性标志：干皮症、鱼鳞病、掌纹症、白色糠疹、乳头湿疹、口角唇炎", "鉴别：接触性皮炎、脂溢性皮炎、银屑病、疥疮、免疫缺陷病(高IgE综合征/Wiskott-Aldrich)、淋巴瘤样丘疹病", "严重度：SCORAD评分(0-103)或EASI评分(0-72)，IGA评估"], "staging": ["疾病分期：急性期(红斑丘疹水疱渗出)、亚急性期(鳞屑结痂)、慢性期(苔藓化皮肤增厚)", "严重度：轻度(SCORAD<25或EASI<7)、中度(SCORAD 25-50或EASI 7-21)、重度(SCORAD>50或EASI>21)", "受累面积：BSA评估", "生活质量：DLQI(成人)/CDLQI(儿童)，POEM(患者定向湿疹测量)", "合并症：哮喘、过敏性鼻炎、食物过敏、过敏性结膜炎、睡眠障碍、心理问题", "控制水平：控制/部分控制/未控制(按瘙痒/睡眠/皮损/发作频率)"], "key_points": ["基础治疗是核心：保湿润肤(每天≥2次)、避免诱因、患者教育", "轻度：外用糖皮质激素(TCS)或钙调磷酸酶抑制剂(TCI)", "中度：中强效TCS+TCI，湿裹治疗，光疗", "重度：系统治疗(环孢素/甲氨蝶呤/硫唑嘌呤)或生物制剂(度普利尤单抗)", "瘙痒管理：避免搔抓，抗组胺药(夜间镇静类)，冷敷", "急性发作：短期中强效TCS控制，之后维持治疗(每周2次TCS/TCI主动维持)", "食物过敏：不盲目忌口，明确过敏才避免，婴儿母乳喂养至少4个月"], "drug_recommendations": ["外用糖皮质激素：弱效(氢化可的松)面部/皱褶/婴儿，中效(糠酸莫米松/曲安奈德)躯干四肢，强效(卤米松)肥厚苔藓化，短期2-4周，面部/皱褶≤1-2周", "外用钙调磷酸酶抑制剂：他克莫司软膏0.03%(儿童)/0.1%(成人)、吡美莫司乳膏1%，面部/皱褶/生殖器首选，无激素萎缩，初期灼热感", "外用磷酸二酯酶4抑制剂：克立硼罗软膏2%(轻中度，2岁以上)", "外用JAK抑制剂：鲁索利替尼乳膏1.5%(轻中度，12岁以上)", "系统免疫抑制剂：环孢素2.5-5mg/kg/d(短期，重度)、甲氨蝶呤7.5-25mg/w、硫唑嘌呤1-3mg/kg/d、霉酚酸酯", "生物制剂：度普利尤单抗(抗IL-4Rα)成人600mg负荷后300mg q2w，儿童按体重；JAK抑制剂口服(乌帕替尼15mg qd、阿布昔替尼100mg qd，注意感染/血栓/心血管)", "抗组胺药：西替利嗪/氯雷他定(白天)，羟嗪/扑尔敏(夜间镇静止痒)", "急性渗出：湿敷(生理盐水/3%硼酸)，氧化锌油，感染时抗生素(莫匹罗星/夫西地酸)", "保湿剂：每天≥2次，沐浴后3分钟内涂抹，含神经酰胺/尿素/甘油成分"], "non_pharmacological": ["保湿润肤：基础治疗，每天≥2次，沐浴后立即涂抹，选择无香料低敏产品", "沐浴：温水(<37℃)短时间(<10min)，温和无皂清洁剂，避免热水烫洗", "避免诱因：过敏原(尘螨/花粉/宠物)、刺激物(羊毛/化纤/香料/酒精)、温度剧烈变化、出汗、精神紧张", "衣物：纯棉宽松，新衣物洗后穿，避免羊毛化纤直接接触", "环境：尘螨控制(防螨床罩/热水洗/除湿)，避免宠物，保持湿度50-60%", "饮食：不盲目忌口，明确食物过敏才避免，婴儿添加辅食循序渐进", "心理支持：瘙痒影响睡眠和生活，焦虑加重瘙痒，放松训练/认知行为治疗", "避免搔抓：剪短指甲，夜间戴棉手套，冷敷止痒"], "complications": ["皮肤感染：金黄色葡萄球菌定植/感染(脓疱/渗出/结痂)，单纯疱疹病毒感染(疱疹性湿疹/Kaposi水痘样疹，重症)，真菌感染", "睡眠障碍：夜间瘙痒致失眠，影响儿童生长发育和学习，成人工作", "心理问题：容貌影响+慢性瘙痒致抑郁焦虑，儿童行为问题", "生长发育迟缓：儿童重度AD+长期激素+睡眠差，监测身高体重", "白内障/视网膜脱离：重度AD/长期揉眼，眼科随访", "红皮病：重度泛发，住院系统治疗", "药物不良反应：激素(皮肤萎缩/毛细血管扩张/色素改变/反跳)、TCI(初期灼热/皮肤感染风险)、系统免疫抑制剂(感染/骨髓/肝肾)、生物制剂(结膜炎/注射反应)"], "monitoring": ["治疗初期：每2-4周评估皮损(SCORAD/EASI)、瘙痒、睡眠、生活质量", "稳定期：每1-3个月随访，主动维持治疗", "外用激素：评估使用部位和时间，避免长期大面积使用", "系统治疗前：血常规、肝肾功、乙肝丙肝、结核筛查、妊娠试验", "系统治疗中：每1-3个月查血常规肝肾功，环孢素监测血压肾功", "生物制剂/JAK：用药前结核/乙肝筛查，用药中感染征象，JAK监测血常规血脂血栓", "过敏原复查：必要时，避免长期不必要忌口", "儿童生长发育：身高体重定期"], "special_populations": ["婴儿(2岁内)：面头皮为主，弱效激素+保湿，避免强效，母乳喂养，食物过敏评估", "儿童(2-12岁)：屈侧为主，中弱效激素，TCI(他克莫司0.03%)，严重者甲氨蝶呤/度普利尤单抗(按体重)", "老年：皮肤更干燥，注意激素萎缩，合并症多，系统药物谨慎", "妊娠：保湿+弱中效激素安全，避免系统免疫抑制剂，度普利尤单抗孕期可用(数据有限)", "手部AD：避免接触刺激物，强效激素+封包，保湿，必要时X光治疗", "眼睑AD：TCI首选，避免激素(青光眼/白内障风险)，眼科随访", "合并哮喘/过敏性鼻炎：特应性进程，同时治疗，度普利尤单抗对AD+哮喘均有效"], "references": "中华医学会皮肤性病学分会. 特应性皮炎诊疗指南(2024). 中华皮肤科杂志", "py": "tyxpyzlzn（"}, {"name": "中国原发性青光眼诊疗指南（2024）", "category": "眼科", "scope": "成人原发性青光眼(开角型POAG和闭角型PACG)诊断和治疗。", "diagnosis": ["POAG：眼压>21mmHg(正常眼压性青光眼眼压可正常)、青光眼性视神经损害(视盘杯盘比扩大/盘沿切迹/神经纤维层缺损)、相应视野缺损，前房角开放", "PACG：前房角关闭(虹膜周边前粘连)，眼压升高，可急性发作(眼痛头痛视力骤降/恶心呕吐/角膜水肿/前房浅/瞳孔散大)", "高危因素：POAG(近视/家族史/黑人/眼压高)、PACG(远视/小眼球/浅前房/窄角/老年女性/亚洲人)", "检查：眼压(Goldmann压平眼压计金标准)、前房角镜(区分开角/闭角)、眼底(视盘/OCT神经纤维层)、视野(标准自动视野计)、中央角膜厚度(影响眼压测量)", "正常眼压性青光眼：眼压≤21但有青光眼性视神经损害和视野缺损，需排除其他视神经病变", "鉴别：继发性青光眼(激素/外伤/色素播散/剥脱综合征/新生血管)、视神经炎/缺血性视神经病变/颅内病变"], "staging": ["POAG分期：早期(旁中心暗点/鼻侧阶梯，MD>-6dB)、中期(弓形暗点/周边视野缩小，MD -6至-12dB)、晚期(管状视野/颞侧视岛，MD<-12dB)、绝对期(失明)", "PACG：临床前期、前驱期、急性发作期、间歇期、慢性期、绝对期", "眼压分级：正常≤21、轻度升高22-25、中度26-30、重度>30", "目标眼压：根据基线眼压和分期设定，早期降20%，中期降30%，晚期降40%以上，正常眼压性青光眼降30%", "视神经损害：盘沿面积、杯盘比、神经纤维层厚度(OCT)", "视野进展：GPA分析，定期比较"], "key_points": ["POAG：降眼压是唯一证实有效的治疗，目标眼压个体化，药物→激光→手术阶梯", "PACG：解除瞳孔阻滞是关键，激光周边虹膜切除术(LPI)或白内障手术，眼压仍高加药物/小梁手术", "药物治疗：前列腺素类衍生物一线(降眼压30-33%)，每晚1次", "激光治疗：选择性激光小梁成形术(SLT)可作为POAG一线或药物辅助", "手术治疗：小梁切除术是金标准，引流阀植入术(难治性)，微创青光眼手术(MIGS)中轻度", "定期随访：眼压、视野、视神经，评估进展调整目标眼压", "患者教育：终身疾病，依从性重要，避免诱因(暗室/情绪激动/大量饮水/衣领过紧)"], "drug_recommendations": ["前列腺素类：拉坦前列素0.005% qn、曲伏前列素0.004% qn、贝美前列素0.03% qn、他氟前列素0.0015% qn(一线，降眼压30-33%，注意虹膜色素加深/睫毛增长/眶周脂肪萎缩)", "β受体阻滞剂：噻吗洛尔0.25-0.5% bid、卡替洛尔1-2% bid(降20-25%，支气管哮喘/心动过缓/心衰禁用)", "α2肾上腺素能激动剂：溴莫尼定0.1-0.2% bid-tid(降20-25%，注意口干/嗜睡/过敏，儿童禁用)", "碳酸酐酶抑制剂：布林佐胺1% bid-tid(局部)、乙酰唑胺125-250mg qid(口服，急性发作短期，注意电解质/肾结石/磺胺过敏)", "复方制剂：拉坦前列素噻吗洛尔qd、布林佐胺噻吗洛尔bid(提高依从性)", "缩瞳剂：毛果芸香碱1-2% tid-qid(PACG，开放房角，注意眉弓痛/近视加深/视网膜脱离风险)", "高渗剂：20%甘露醇1-2g/kg iv快速滴注(急性发作/术前，注意心肾功能)、50%甘油盐水口服", "急性闭角发作：综合治疗(缩瞳剂+β阻滞剂+碳酸酐酶抑制剂+高渗剂+激素)，眼压控制后激光虹膜周切或白内障手术"], "non_pharmacological": ["激光周边虹膜切除术(LPI)：PACG各期(临床前期/前驱期/间歇期)首选，解除瞳孔阻滞", "选择性激光小梁成形术(SLT)：POAG开角型，可重复，作为一线或辅助", "激光周边虹膜成形术：急性闭角发作药物控制不佳时", "手术小梁切除术：药物/激光控制不良的中晚期POAG/PACG，抗代谢药(丝裂霉素C)提高成功率", "引流阀植入术：难治性青光眼(新生血管性/外伤性/多次手术失败)", "微创青光眼手术(MIGS)：iStent/小梁网消融/ Schlemm管成形，轻中度POAG，联合白内障手术", "生活方式：避免暗室久留、情绪激动、大量饮水(一次<300ml)、衣领过紧，适度有氧运动(降眼压)，避免倒立/举重(升高眼压)", "定期随访：眼压每1-6个月，视野每6-12个月，视神经OCT每年"], "complications": ["急性闭角发作：视力骤降/眼痛头痛恶心呕吐，紧急降眼压，延误可致永久性视力丧失", "视神经萎缩/视野缺损：进行性，不可逆，晚期管状视野/失明", "白内障：青光眼患者白内障发生早/进展快，白内障手术可同时治疗闭角青光眼", "恶性青光眼：闭角术后/缩瞳剂后，前房极浅眼压高，阿托品+高渗剂+激素，无效玻璃体切割", "药物不良反应：前列腺素类(虹膜色素加深/睫毛增长/眶周萎缩)、β阻滞剂(心动过缓/支气管痉挛)、溴莫尼定(过敏/嗜睡)、口服CAI(电解质紊乱/肾结石)", "手术并发症：浅前房/低眼压、滤过泡感染/漏、白内障、出血、感染(眼内炎罕见但严重)", "低眼压性黄斑病变：术后眼压过低，黄斑皱褶视力下降"], "monitoring": ["眼压：治疗初期每2-4周，稳定后每1-6个月，24小时眼压曲线(波动评估)", "视野：每6-12个月，早期更频繁，GPA分析进展", "视神经：眼底照相/OCT神经纤维层，每6-12个月", "前房角：闭角型定期房角镜检查", "药物不良反应：每次随访询问，眼部和全身", "手术眼：滤过泡形态、眼压、前房深度、并发症", "目标眼压评估：根据视野/视神经进展调整，进展则降低目标", "患者依从性：用药频率和方法检查"], "special_populations": ["正常眼压性青光眼：目标眼压降30%，注意血压(夜间低血压加重)，改善微循环药物(辅助)", "高眼压症：眼压>21但无视神经/视野损害，危险因素(角膜薄/家族史/近视)者治疗，否则定期观察", "青少年型青光眼：药物(前列腺素类)效果差，手术(小梁切开/小梁切除)，注意鉴别发育性青光眼", "妊娠：避免前列腺素类(子宫收缩)和碳酸酐酶抑制剂，用β阻滞剂(注意新生儿)，激光/手术优先考虑", "老年：注意全身合并症(哮喘/心衰/肾功)，药物选择谨慎，手术耐受性评估", "合并白内障：白内障手术可加深前房/开放房角(闭角型)，联合MIGS或小梁切除"], "references": "中华医学会眼科学分会青光眼学组. 中国原发性青光眼诊疗指南(2024). 中华眼科杂志", "py": "zgyfxqgyzlzn（"}, {"name": "变应性鼻炎诊断和治疗指南（2024）", "category": "耳鼻喉科", "scope": "成人和儿童变应性鼻炎(过敏性鼻炎)诊断和治疗。", "diagnosis": ["典型症状：阵发性喷嚏、清水样涕、鼻痒、鼻塞(2项以上，每天≥1h)", "体征：鼻黏膜苍白水肿，鼻腔水样分泌物，可伴眼结膜充血/眼睑水肿", "过敏原检测：皮肤点刺试验(SPT)阳性或血清特异性IgE(sIgE)阳性，结合症状", "分类：按过敏原季节(季节性/常年性)，按持续时间(间歇性<4天/周或<4周/持续性)，按严重度(轻度/中重度)", "鼻激发试验：诊断困难时(过敏原阴性但高度怀疑)", "鉴别：血管运动性鼻炎、感染性鼻炎、嗜酸性粒细胞增多性非变应性鼻炎(NARES)、药物性鼻炎、脑脊液鼻漏", "合并症：变应性结膜炎、哮喘、鼻窦炎、鼻息肉、分泌性中耳炎、睡眠呼吸暂停"], "staging": ["ARIA分类：间歇性(症状<4天/周或<4周)、持续性(>4天/周且>4周)", "严重度：轻度(睡眠/日常活动/工作学习不受影响，无烦恼症状)、中重度(上述受影响)", "过敏原类型：季节性(花粉/真菌孢子)、常年性(尘螨/宠物/蟑螂)", "控制水平：控制/部分控制/未控制(按症状/用药/生活质量)", "鼻结膜炎生活质量问卷(RQLQ)：评估生活影响", "合并哮喘评估：肺功能/支气管激发试验，上下气道同治"], "key_points": ["避免过敏原是基础：尘螨(防螨床罩/热水洗/除湿)、花粉(季节防护)、宠物(避免接触)", "药物治疗阶梯：轻度间歇性→口服抗组胺药/鼻用抗组胺药；中重度/持续性→鼻用糖皮质激素(一线)", "鼻用糖皮质激素是中重度AR一线用药，疗效优于抗组胺药", "抗组胺药：第二代(西替利嗪/氯雷他定/非索非那定)，嗜睡少，鼻用起效快", "白三烯受体拮抗剂：孟鲁司特，合并哮喘者优选", "过敏原特异性免疫治疗(AIT)：唯一对因治疗，改变自然病程，适用于尘螨/花粉等，疗程3-5年", "手术治疗：药物无效的下鼻甲肥大/鼻中隔偏曲，辅助治疗"], "drug_recommendations": ["鼻用糖皮质激素：布地奈德鼻喷剂64μg qd、糠酸莫米松鼻喷剂200μg qd、丙酸氟替卡松鼻喷剂200μg qd、糠酸氟替卡松110μg qd(一线，中重度，疗程≥2周，可长期，注意鼻出血/鼻黏膜干燥)", "第二代口服抗组胺药：西替利嗪10mg qd、氯雷他定10mg qd、非索非那定120mg qd、地氯雷他定5mg qd、左西替利嗪5mg qd(轻度/间歇性，起效快，嗜睡少)", "鼻用抗组胺药：氮卓斯汀鼻喷剂1喷bid、奥洛他定鼻喷剂2喷bid(起效快，15-30min，轻中度)", "白三烯受体拮抗剂：孟鲁司特10mg qn(成人)，5mg(2-5岁)，4mg(6月-2岁)，合并哮喘优选，注意神经精神不良反应(情绪/睡眠/自杀意念)", "减充血剂：羟甲唑啉/赛洛唑啉鼻喷剂(短期≤7天，缓解鼻塞，长期用致药物性鼻炎)，口服伪麻黄碱(高血压/心脏病慎用)", "肥大细胞稳定剂：色甘酸钠鼻喷剂(预防，提前1-2周用，起效慢)", "眼用抗组胺药：奥洛他定滴眼液/氮卓斯汀滴眼液(变应性结膜炎)", "免疫治疗(AIT)：皮下注射(SCIT)或舌下含服(SLIT)，尘螨制剂/花粉制剂，疗程3-5年，起效6-12月", "鼻腔冲洗：生理盐水/海盐水冲洗鼻腔，每天1-2次，辅助治疗"], "non_pharmacological": ["过敏原避免：尘螨(防螨床罩枕套、55℃以上热水洗床品、除湿<50%、空气净化器HEPA)、花粉(季节关窗/口罩/护目镜/外出回家洗脸洗鼻/避免晾晒)、宠物(避免饲养/隔离卧室/空气净化)、霉菌(通风除湿/修复漏水)", "环境控制：戒烟(包括二手烟)，避免刺激性气味，保持室内清洁", "鼻腔冲洗：生理盐水/海盐水每天1-2次，清除过敏原和分泌物，安全可长期", "适度运动：增强体质，但花粉季节避免户外运动", "饮食：避免已知过敏食物，部分患者对花粉相关食物(交叉反应)敏感", "免疫治疗：唯一对因治疗，改变疾病自然进程，减少哮喘发生风险，适用于5岁以上", "患者教育：疾病认知、用药方法(鼻喷剂头偏向对侧)、依从性、长期管理"], "complications": ["支气管哮喘：AR患者哮喘风险增加3倍，上下气道同治，约40%AR合并哮喘", "变应性鼻窦炎/鼻息肉：长期炎症致鼻窦炎/鼻息肉，中重度AR需评估", "分泌性中耳炎：咽鼓管功能障碍，耳闷听力下降，儿童多见", "睡眠呼吸暂停：鼻塞致张口呼吸/打鼾/睡眠呼吸暂停，影响睡眠质量和白天功能", "嗅觉障碍：长期炎症/鼻息肉致嗅觉减退或丧失", "药物性鼻炎：长期用减充血剂(>7天)致反跳性鼻塞，停用减充血剂+鼻用激素", "鼻息肉：中重度持续性AR风险，CT评估，药物(激素)或手术", "结膜炎：眼痒流泪眼红，眼用抗组胺药/肥大细胞稳定剂"], "monitoring": ["治疗初期：每2-4周评估症状(喷嚏/流涕/鼻痒/鼻塞)、生活质量、用药依从性", "稳定期：每1-3个月随访，调整药物阶梯(降阶梯/维持)", "鼻喷剂使用技术：每次随访检查纠正(头微低、喷头朝向外侧、避免对着鼻中隔)", "药物不良反应：鼻出血(鼻用激素，对着外侧喷可减少)、嗜睡(抗组胺药)、神经精神事件(孟鲁司特)", "免疫治疗：每次注射后观察30min(SCIT)，过敏反应处理，定期评估疗效调整剂量", "合并症筛查：哮喘(肺功能)、鼻窦炎/鼻息肉(鼻内镜/CT)、中耳炎", "过敏原复查：必要时，环境控制评估"], "special_populations": ["儿童：鼻用激素(2岁以上糠酸莫米松/布地奈德)，口服抗组胺药按年龄，免疫治疗5岁以上，注意生长发育(鼻用激素影响小)，合并腺样体肥大/中耳炎", "妊娠：鼻用激素(布地奈德相对安全)、生理盐水冲洗，避免口服减充血剂，抗组胺药(氯雷他定/西替利嗪相对安全但尽量孕早期避免)", "老年：注意药物相互作用(抗组胺药抗胆碱/嗜睡跌倒)，鼻用激素安全，合并高血压避免口服减充血剂", "合并哮喘：孟鲁司特或鼻用激素，上下气道同治，吸入激素治疗哮喘，AIT对两者均有效", "合并鼻息肉/鼻窦炎：鼻用激素+鼻腔冲洗，必要时口服激素(短期)或手术", "职业性变应性鼻炎：避免职业暴露是关键，早期脱离，AIT部分有效"], "references": "中华耳鼻咽喉头颈外科杂志编委会. 变应性鼻炎诊断和治疗指南(2024). 中华耳鼻咽喉头颈外科杂志", "py": "byxbyzdhzlzn（"}, {"name": "中国良性前列腺增生症诊疗指南（2024）", "category": "泌尿外科", "scope": "成人良性前列腺增生(BPH)诊断和治疗。", "diagnosis": ["下尿路症状(LUTS)：储尿期(尿频/尿急/夜尿/急迫性尿失禁)、排尿期(排尿困难/尿线变细/间断/腹压排尿)、排尿后(尿不尽/滴沥)", "国际前列腺症状评分(IPSS)：0-35分，0-7轻度、8-19中度、20-35重度", "生活质量评分(QoL)：0-6分，≥4分提示患者不满意需治疗", "直肠指检(DRE)：前列腺增大、质地中等、中央沟变浅/消失，排除硬结(前列腺癌)", "辅助检查：尿常规(排除感染/血尿)、血清PSA(前列腺癌筛查，BPH可轻度升高)、前列腺超声(体积/残余尿)、尿流率(Qmax<10ml/s提示梗阻)", "侵入性检查：尿动力学(诊断困难/神经源性膀胱)、膀胱镜(血尿/结石/肿瘤怀疑)", "鉴别：前列腺癌、神经源性膀胱、尿道狭窄、膀胱颈挛缩、前列腺炎、膀胱癌(原位癌可致刺激症状)"], "staging": ["IPSS评分：轻度0-7、中度8-19、重度20-35", "前列腺体积：超声测量，<30ml、30-50ml、>50ml(大体积)", "残余尿(PVR)：<50ml正常，>50ml提示梗阻，>200ml提示膀胱功能受损", "Qmax：>15正常，10-15可疑梗阻，<10提示梗阻", "并发症：急性尿潴留、反复血尿、反复泌尿系感染、膀胱结石、肾积水/肾功能损害、疝气/痔疮(腹压排尿)", "手术指征：中重度LUTS药物无效、并发症(尿潴留/肾积水/结石/反复感染/血尿)、残余尿>50-100ml"], "key_points": ["观察等待：轻度症状(IPSS≤7)或中度但生活质量影响小，定期随访", "药物治疗：中重度症状，α1受体阻滞剂(快速缓解症状)+5α还原酶抑制剂(缩小体积，大体积前列腺)联合", "α1受体阻滞剂：坦索罗辛/特拉唑嗪，起效快(数天)，不缩小体积，注意体位性低血压/逆行射精", "5α还原酶抑制剂：非那雄胺/度他雄胺，缩小体积20-30%，减少急性尿潴留和手术风险，起效慢(3-6月)，注意性功能障碍", "M受体拮抗剂/β3激动剂：储尿期症状为主(尿急尿频)，残余尿不多者，注意尿潴留风险", "手术治疗：药物无效或有并发症，经尿道前列腺电切术(TURP)金标准，激光手术( HoLEP/绿激光)出血少，大体积可选开放/腹腔镜剜除", "定期随访：IPSS/QoL/尿流率/残余尿/PSA，药物6个月评估疗效"], "drug_recommendations": ["α1受体阻滞剂：坦索罗辛0.2mg qn(高选择性α1A，心血管副作用少)、特拉唑嗪2mg qn(起始1mg)、多沙唑嗪4mg qd、阿夫唑嗪2.5mg tid(注意体位性低血压，首剂睡前)", "5α还原酶抑制剂：非那雄胺5mg qd(Ⅱ型5α还原酶)、度他雄胺0.5mg qd(Ⅰ+Ⅱ型，起效更快)，3-6月起效，疗程≥6-12月评估", "联合治疗：α1阻滞剂+5α还原酶抑制剂(中重度+大体积前列腺>30ml，症状改善+减少进展)", "M受体拮抗剂：托特罗定2mg bid、索利那新5mg qd(储尿期症状，残余尿<50ml，注意口干/便秘/尿潴留)", "β3肾上腺素能激动剂：米拉贝隆50mg qd(储尿期症状，不影响排尿期，注意血压升高)", "植物制剂：普适泰/锯叶棕提取物(疗效不确切，可作为辅助)", "急性尿潴留：留置导尿(首选)，α1阻滞剂提高拔管成功率，拔管前试夹管训练膀胱"], "non_pharmacological": ["观察等待：轻度症状，生活方式指导(限水/避免咖啡因酒精/定时排尿/二次排尿)，定期随访", "生活方式：夜间限水，避免咖啡因/酒精(利尿刺激)，避免久坐/受凉，适度运动，定时排尿，二次排尿(减少残余尿)", "膀胱训练：延迟排尿，延长排尿间隔，改善储尿期症状", "盆底肌训练：凯格尔运动，改善控尿", "避免加重药物：抗组胺药/抗胆碱药/减充血剂/某些抗抑郁药(加重排尿困难)", "定期随访：IPSS/QoL/尿流率/残余尿/PSA/DRE，观察等待者每6-12月", "患者教育：疾病认知，药物起效时间(5α还原酶抑制剂慢)，手术指征"], "complications": ["急性尿潴留：突然不能排尿，下腹胀痛，留置导尿，反复发作需手术", "反复泌尿系感染：残余尿致感染，抗感染+解除梗阻", "膀胱结石：残余尿/感染致结石，手术同时取石+前列腺切除", "反复血尿：前列腺黏膜血管破裂，5α还原酶抑制剂减少出血，严重者手术", "肾积水/肾功能损害：长期梗阻致膀胱高压→输尿管反流→肾积水，解除梗阻可恢复(早期)", "疝气/痔疮/脱肛：长期腹压排尿所致，前列腺手术可改善", "膀胱功能损害：长期梗阻致逼尿肌肥厚/纤维化，术后排尿困难可能不恢复", "药物不良反应：α阻滞剂(体位性低血压/头晕/逆行射精)、5α还原酶抑制剂(性欲降低/勃起功能障碍/射精量减少/男性乳房发育)、M拮抗剂(口干/便秘/尿潴留)"], "monitoring": ["观察等待：每6-12个月IPSS/QoL/尿流率/残余尿/尿常规，症状加重及时就诊", "药物治疗：1个月评估症状改善(α阻滞剂起效快)，6个月评估(5α还原酶抑制剂)，调整方案", "PSA：每年检查，5α还原酶抑制剂可使PSA降低约50%，用药6月后PSA×2解读，排除前列腺癌", "DRE：每年，发现硬结进一步检查(前列腺穿刺)", "尿流率/残余尿：每6-12个月或症状变化时", "术后随访：IPSS/QoL/尿流率/残余尿/尿常规，评估手术效果和并发症(尿失禁/尿道狭窄/逆行射精)", "肾功能：有肾积水者随访肌酐和超声"], "special_populations": ["老年(>70岁)：注意合并症(心血管病/糖尿病)，α阻滞剂体位性低血压跌倒风险，选择高选择性坦索罗辛，手术耐受性评估", "前列腺癌筛查：PSA升高/DRE硬结需前列腺穿刺，BPH和前列腺癌可并存", "合并前列腺炎：抗感染+α阻滞剂，避免过度治疗", "合并膀胱过度活动症(OAB)：α阻滞剂+M拮抗剂/β3激动剂，注意残余尿", "合并勃起功能障碍：他达拉非5mg qd(PDE5抑制剂，同时改善BPH症状和ED，注意硝酸盐禁忌)", "大体积前列腺(>80-100ml)：5α还原酶抑制剂+激光剜除(HoLEP)或开放手术，TURP风险高", "术后逆行射精：常见(70-90%)，术前告知，不影响健康但影响生育(有生育需求者慎重)"], "references": "中华医学会泌尿外科学分会. 中国良性前列腺增生症诊疗指南(2024). 中华泌尿外科杂志", "py": "zglxqlxzszzlzn（"}, {"name": "原发性骨质疏松症诊疗指南（2024）", "category": "骨科", "scope": "成人原发性骨质疏松症(绝经后/老年)诊断和防治。", "diagnosis": ["脆性骨折：轻微外伤(站立高度跌倒)或日常活动发生的骨折，即可诊断骨质疏松症", "骨密度检测：双能X线吸收法(DXA)，T值≤-2.5诊断骨质疏松，-1.0至-2.5骨量减少，≥-1.0正常", "T值：(实测骨密度-正常年轻成人峰值)/标准差，用于绝经后女性和50岁以上男性", "Z值：用于绝经前女性和50岁以下男性，Z值≤-2.0为低于同年龄预期", "危险因素：不可控(年龄/女性/绝经/家族史/种族)、可控(低体重/吸烟/过量饮酒/缺乏运动/钙维D不足/跌倒)、继发性(激素/甲亢/甲旁亢/慢性肾病/胃肠疾病/药物)", "骨折风险评估：FRAX工具(10年髋部骨折和主要骨质疏松性骨折概率)", "实验室：血钙磷、碱性磷酸酶、25-羟维生素D、PTH、肝肾功能、甲功、血常规、血沉(排除继发性)", "骨转换标志物：β-CTX、PINP(评估骨转换和治疗反应)"], "staging": ["骨量正常：T值≥-1.0", "低骨量(骨量减少)：T值-1.0至-2.5", "骨质疏松症：T值≤-2.5", "严重骨质疏松症：T值≤-2.5+脆性骨折", "骨折部位：椎体(最常见，胸腰椎)、髋部(最严重，致死致残率高)、桡骨远端、肱骨近端", "椎体骨折分级：Genant半定量法(轻度20-25%高度丢失、中度25-40%、重度>40%)", "治疗反应：骨密度每年DXA，骨转换标志物3-6月"], "key_points": ["基础措施：钙和维生素D补充、生活方式、跌倒预防", "药物治疗指征：T值≤-2.5；T值-1.0至-2.5+FRAX高危；脆性骨折(椎体/髋部)", "抗骨吸收药：双膦酸盐(一线)、地舒单抗、降钙素、雌激素/SERM", "促骨形成药：特立帕肽(PTH类似物)、阿巴洛肽，用于严重骨质疏松/高骨折风险", "联合/序贯：促骨形成后抗骨吸收维持，不建议同时用两类(抵消)", "疗程：双膦酸盐3-5年后评估药物假期，地舒单抗长期用(停药需过渡双膦酸盐)", "跌倒预防：家居改造、视力检查、平衡训练、避免镇静药、髋部保护器"], "drug_recommendations": ["钙：元素钙1000-1200mg/d(饮食+补充)，碳酸钙(餐中)、枸橼酸钙(空腹/胃酸少)", "维生素D：普通成人400-800IU/d，骨质疏松/老年人800-1200IU/d，25-羟维生素D目标≥20ng/ml(最好30ng/ml)", "双膦酸盐：阿仑膦酸钠70mg qw(空腹200ml水，服后30min直立)、利塞膦酸钠35mg qw、唑来膦酸5mg iv每年(口服不耐受/依从性差)、伊班膦酸钠", "地舒单抗：60mg皮下每6个月(抗RANKL，不建议停药，停药骨量快速丢失，需过渡双膦酸盐)", "特立帕肽：20μg皮下qd(促骨形成，疗程≤2年，用于严重骨质疏松/多发椎体骨折)", "阿巴洛肽：80μg皮下qd(促骨形成，疗程≤2年)", "降钙素：鲑鱼降钙素50IU im qd或鼻喷剂200IU qd(镇痛效果好，椎体骨折急性期，不长期用)", "雌激素：绝经早期女性，个体化评估(乳腺癌/血栓/心血管风险)，最低有效剂量", "SERM：雷洛昔芬60mg qd(椎体骨折，不增加乳腺癌风险，潮热/血栓风险)、巴多昔芬", "罗莫单抗：210mg皮下每月×12月(抗硬化蛋白，促形成+抗吸收，之后过渡抗骨吸收)"], "non_pharmacological": ["钙摄入：奶制品(牛奶300ml/d约300mg钙)、豆制品、深绿叶菜、小鱼虾，不足补充剂", "维生素D：日晒(每天15-20min暴露四肢)、深海鱼/蛋黄/强化食品，不足补充剂", "运动：负重运动(快走/慢跑/爬楼)和抗阻训练(哑铃/弹力带)每周≥3次，每次30min，增加骨密度防跌倒", "戒烟限酒：吸烟降低骨密度，过量酒精(>2单位/d)增加骨折风险", "防跌倒：家居改造(防滑垫/扶手/夜灯/移除地毯)、视力检查、平衡训练(太极)、避免镇静药、穿防滑鞋", "避免低体重：BMI<19风险高，均衡营养", "避免久坐：每小时起身活动", "避免过量咖啡因/碳酸饮料(影响钙吸收)"], "complications": ["脆性骨折：椎体(身高变矮/驼背/背痛)、髋部(卧床并发症/致死致残)、桡骨远端、肱骨近端", "椎体骨折：可无症状(影像学发现)，多发致身高变矮/驼背/胸廓畸形/呼吸功能下降", "髋部骨折：1年内死亡率20-30%，致残率50%，需手术(内固定/关节置换)+康复+抗骨质疏松治疗", "骨折后急性疼痛：降钙素镇痛，椎体成形术/后凸成形术(顽固性疼痛椎体骨折)", "长期卧床并发症：肺部感染、深静脉血栓、压疮、肌肉萎缩、骨量进一步丢失", "药物不良反应：双膦酸盐(胃肠道/下颌骨坏死罕见/非典型股骨骨折罕见)、地舒单抗(感染/皮疹/停药反弹)、特立帕肽(头痛/恶心/骨肉瘤风险理论上)、雌激素(血栓/乳腺癌/心血管)"], "monitoring": ["骨密度DXA：治疗前基线，治疗后每年(腰椎+髋部)，评估疗效(骨密度不下降或升高为有效)", "骨转换标志物：β-CTX/PINP，治疗前基线，治疗后3-6月(抗骨吸收药应下降≥30-50%)", "身高体重：每年，身高下降>2cm提示椎体骨折", "椎体影像学：有症状或身高下降时胸腰椎X线", "实验室：血钙磷、25-羟维生素D、PTH、肝肾功能，每年", "药物不良反应：双膦酸盐下颌骨坏死(牙科检查，避免侵入性牙科操作)、非典型股骨骨折(大腿/腹股沟痛警惕)", "跌倒风险评估：每年，环境和平衡评估", "骨折事件记录：评估治疗失败(治疗中仍骨折需调整方案)"], "special_populations": ["绝经后女性：最常见，雌激素缺乏是主因，绝经早期可考虑雌激素，双膦酸盐一线", "老年男性(>70岁)：睾酮缺乏/年龄相关，双膦酸盐一线，睾酮水平低者可补充(前列腺癌禁忌)", "绝经前女性：多为继发性，查找病因，Z值评估，避免致畸药，钙维D基础", "糖皮质激素诱导骨质疏松：用激素≥3个月者，钙维D+双膦酸盐预防，剂量≥7.5mg泼尼松/d者", "骨折后：立即启动抗骨质疏松治疗(不要等恢复)，手术+康复+药物综合", "长期卧床/制动：快速骨量丢失，早期康复，抗骨吸收药", "合并慢性肾病：双膦酸盐(eGFR<35慎用)，地舒单抗(不需调量但低钙风险)，专科评估"], "references": "中华医学会骨质疏松和骨矿盐疾病分会. 原发性骨质疏松症诊疗指南(2024). 中华骨质疏松和骨矿盐疾病杂志", "py": "yfxgzsszzlzn（"}, {"name": "中国骨关节炎诊疗指南（2024）", "category": "骨科", "scope": "成人骨关节炎(OA，退行性骨关节病)诊断和治疗。", "diagnosis": ["症状：关节疼痛(活动后加重，休息缓解)、晨僵(<30min)、骨摩擦感、关节肿胀、活动受限、晚期畸形", "体征：关节压痛、肿胀、畸形、骨摩擦音(捻发感)、活动受限、肌萎缩", "好发部位：膝关节(最常见)、髋关节、手(远端指间关节Heberden结节/近端Bouchard结节)、脊柱、足(第一跖趾)", "影像学：X线(关节间隙狭窄、骨赘形成、软骨下骨硬化/囊性变)，Kellgren-Lawrence分级0-IV级", "MRI：软骨缺损、骨髓水肿、半月板损伤、滑膜炎(早期诊断和鉴别)", "实验室：一般正常，血沉/CRP轻度升高，排除炎症性关节炎(类风湿/痛风)", "鉴别：类风湿关节炎(对称小关节/晨僵>1h/RF抗CCP阳性)、痛风(急性红肿热痛/尿酸高)、银屑病关节炎、感染性关节炎、骨坏死"], "staging": ["Kellgren-Lawrence X线分级：0级正常、I级可疑骨赘、II级明确骨赘+关节间隙可疑狭窄、III级中等骨赘+明确关节间隙狭窄+硬化、IV级大骨赘+严重关节间隙狭窄+明显硬化+畸形", "症状严重度：VAS疼痛评分(0-10)、WOMAC评分(疼痛/僵硬/功能)、Lequesne指数(膝/髋)", "功能状态：轻度(日常活动不受限)、中度(上下楼/蹲起困难)、重度(行走受限/需助行器/夜间痛)", "炎症表现：有无滑膜炎(关节肿胀积液)、急性发作", "合并症：肥胖、高血压、糖尿病、心血管病(影响治疗选择)", "关节外影响：生活质量、工作能力、心理状态"], "key_points": ["基础治疗是核心：患者教育、运动治疗、物理治疗、行动辅助，所有患者均应接受", "阶梯治疗：基础→药物→修复性治疗→重建治疗(关节置换)", "运动治疗：有氧运动(快走/游泳/骑车)+肌力训练(股四头肌)+关节活动度，减重(肥胖者)", "药物：对乙酰氨基酚/NSAIDs(外用→口服)、关节腔注射(激素/玻璃酸钠)、慢作用药(氨基葡萄糖/双醋瑞因，疗效不确切)", "外用NSAIDs优先于口服(胃肠道副作用少)，口服NSAIDs注意胃肠/肾/心血管风险", "关节腔注射糖皮质激素：急性发作/积液，短期缓解，每年≤3-4次", "手术：保守治疗无效的终末期OA，关节置换术(膝/髋)是成熟有效方法", "避免过度医疗：不推荐长期用氨基葡萄糖/玻璃酸钠作为主要治疗"], "drug_recommendations": ["对乙酰氨基酚：0.5-1g q6h(最大4g/d)，轻中度疼痛，胃肠副作用少，注意肝毒性", "外用NSAIDs：双氯芬酸凝胶/乳胶剂、酮洛芬贴剂、氟比洛芬凝胶贴膏(轻中度，局部作用，全身副作用少，每天3-4次)", "口服NSAIDs：塞来昔布0.2g qd-bid(COX-2选择性，胃肠少)、双氯芬酸50mg tid、布洛芬400mg tid、萘普生500mg bid(注意胃肠/肾/心血管，最短疗程最低有效量，胃肠高危加PPI)", "关节腔注射糖皮质激素：曲安奈德20-40mg或倍他米松7mg，急性发作/积液，每年≤3-4次，间隔≥3月", "关节腔注射玻璃酸钠：25mg每周×5次(黏弹性补充，疗效争议，轻中度可尝试)", "关节腔注射富血小板血浆(PRP)：自体血制备，轻中度，证据有限", "慢作用药：氨基葡萄糖1500mg/d、硫酸软骨素1200mg/d、双醋瑞因50mg bid(疗效不确切，可作为辅助)", "镇痛药：曲马多50mg q12h(NSAIDs无效/禁忌，注意成瘾/便秘)、度洛西汀(慢性疼痛/抑郁)", "中成药：外用/口服，辅助治疗"], "non_pharmacological": ["患者教育：疾病认知(退行性变不可逆转)、治疗目标(缓解疼痛改善功能)、避免过度活动和负重", "减重：BMI>25者减重5-10%显著改善膝OA症状，每减1kg膝关节压力减4kg", "运动治疗：有氧运动(快走/游泳/骑自行车/椭圆机，避免爬山爬楼深蹲)、股四头肌肌力训练(直腿抬高/静蹲)、关节活动度训练，每周≥3次每次30min", "物理治疗：热疗(热敷/红外线/蜡疗)、冷疗(急性肿胀)、经皮神经电刺激(TENS)、超声波、针灸", "行动辅助：手杖(对侧手持)、助行器、护膝(髌股关节OA)、楔形鞋垫(膝内侧间室OA)", "避免诱发：避免长时间跑跳蹲、爬山爬楼、频繁上下楼、负重", "关节保护：避免同一关节长时间负重，交替活动，使用辅助工具", "康复锻炼：术后早期康复(关节置换后)是功能恢复关键"], "complications": ["关节畸形：膝内翻(O型腿)/外翻(X型腿)，屈曲挛缩，严重影响行走", "关节功能丧失：终末期行走困难/需助行器/卧床，生活质量下降", "肌肉萎缩：疼痛致活动减少，股四头肌萎缩，进一步加重关节不稳", "滑膜炎/关节积液：急性发作，肿胀疼痛，关节腔穿刺抽液+激素注射", "关节内游离体：软骨脱落，交锁症状(关节卡住)，关节镜取出", "骨坏死：罕见，长期激素/酒精/创伤", "药物不良反应：NSAIDs(胃肠溃疡出血/肾损伤/心血管事件)、对乙酰氨基酚(肝毒性)、激素注射(感染罕见/反复注射损害软骨)", "手术并发症：关节置换(感染/假体松动/深静脉血栓/脱位/神经血管损伤)"], "monitoring": ["症状评估：VAS疼痛、WOMAC/Lequesne评分，每1-3个月", "影像学：X线每1-2年或症状变化时，评估进展", "体重/BMI：肥胖者定期，减重效果评估", "药物不良反应：NSAIDs(胃肠/肾/心血管)、对乙酰氨基酚(肝功能)，定期", "运动依从性：每次随访评估，调整运动方案", "手术评估：保守治疗无效、终末期、生活质量严重受影响，转骨科手术", "术后随访：关节置换术后伤口/关节活动度/假体位置(X线)/并发症，康复指导"], "special_populations": ["老年：注意合并症(心血管/胃肠/肾)，NSAIDs选择COX-2选择性+PPI，外用优先，手术耐受性评估", "肥胖：减重是关键，减重手术可改善OA，关节置换术前减重降低风险", "合并心血管病：NSAIDs(尤其非选择性)增加心血管事件，避免长期用，外用/对乙酰氨基酚优先", "合并慢性肾病：NSAIDs禁用/慎用，对乙酰氨基酚(减量)、曲马多、关节腔注射", "手OA：外用NSAIDs/激素注射，避免冷水，康复，严重者关节融合/置换", "髋OA：避免负重，手杖，终末期全髋关节置换(效果好)", "膝OA：股四头肌训练+减重，内侧间室OA可高位胫骨截骨(年轻活动多)，终末期全膝/单髁置换"], "references": "中华医学会骨科学分会. 中国骨关节炎诊疗指南(2024). 中华骨科杂志", "py": "zgggjyzlzn（"}, {"name": "围术期患者评估与管理指南（2024）", "category": "麻醉科", "scope": "成人围术期(术前/术中/术后)评估和管理。", "diagnosis": ["术前评估：病史(合并症/手术麻醉史/过敏/用药/烟酒)、体格检查、气道评估(Mallampati/张口度/甲颏距离/颈部活动)、心肺听诊、实验室和辅助检查", "ASA分级：I级健康、II级轻度系统性疾病、III级重度系统性疾病、IV级危及生命、V级濒死、VI级脑死亡(器官捐献)", "心功能评估：NYHA分级、运动耐量(METs，>4METs低风险)、心脏风险指数(RCRI)、心电图/心脏超声/负荷试验(按需)", "肺功能评估：吸烟/COPD/哮喘，肺功能检查(FEV1/FVC)、动脉血气(严重肺病)，戒烟≥2周", "凝血/血液：血常规、凝血功能、血型、交叉配血(大手术)，抗凝/抗血小板药管理", "术前禁食：清饮料2h、母乳4h、配方奶/淀粉类固体6h、油炸/脂肪/肉类8h以上", "困难气道评估：Mallampati III-IV、张口<3cm、甲颏距离<6cm、颈部活动受限、小下颌/龅牙/短颈"], "staging": ["ASA分级(上述)", "手术风险分级：低风险(<1%死亡率，体表/乳腺/白内障)、中风险(1-5%，腹腔/胸腔/骨科大手术)、高风险(>5%，心脏大血管/急诊大手术)", "心功能NYHA：I级(无受限)、II级(一般活动受限)、III级(轻微活动受限)、IV级(静息症状)", "METs运动耐量：>10优秀、7-10良好、4-7中等、<4差(围术期心血管风险高)", "RCRI心脏风险指数：缺血性心脏病、心衰、脑血管病、胰岛素依赖糖尿病、术前肌酐>177(每项1分，0分0.4%、1分0.9%、2分6.6%、≥3分>11%)", "术后恶心呕吐(PONV)风险：女性/不吸烟/PONV史/术后阿片类(每项1分，≥3分高危)"], "key_points": ["术前优化：控制血压(<180/110)、血糖(8-10mmol/L)、纠正贫血/电解质、治疗心律失常/心衰", "抗凝药管理：华法林术前5天停，INR<1.4手术，高血栓风险桥接低分子肝素；NOAC术前24-48h停(按肾功能)；阿司匹林(心血管支架不轻易停)；氯吡格雷术前5-7天停(裸支架≥1月/药物支架≥6月不建议停)", "气道管理：困难气道准备(可视喉镜/喉罩/纤维支气管镜/环甲膜穿刺)，清醒插管指征", "麻醉选择：根据手术/患者/麻醉师，全麻/椎管内/神经阻滞/局部麻醉，联合麻醉减少全麻药用量", "术中监测：标准监测(心电/血压/血氧/ETCO2/体温)，高危加有创动脉压/CVP/尿量/麻醉深度(BIS)", "液体管理：目标导向液体治疗(GDFT)，避免过负荷或不足，大手术监测每搏量变异(SVV)", "术后管理：镇痛(多模式)、恶心呕吐预防、早期活动、营养、血栓预防"], "drug_recommendations": ["术前用药：镇静(咪达唑仑1-2mg iv，焦虑者)、抗胆碱能(东莨菪碱0.3mg im，分泌物多/小儿)、抑酸药(奥美拉唑40mg，反流高危)", "全麻诱导：咪达唑仑0.05mg/kg+丙泊酚1-2mg/kg+芬太尼1-3μg/kg+罗库溴铵0.6mg/kg(或顺阿曲库铵0.15mg/kg)", "全麻维持：丙泊酚4-12mg/kg/h+瑞芬太尼0.05-2μg/kg/min+七氟烷1-2MAC，肌松按需", "椎管内麻醉：腰麻(布比卡因10-15mg重比重)、硬膜外(2%利多卡因/0.5%罗哌卡因)，试验剂量", "神经阻滞：0.25-0.5%罗哌卡因(超声引导，臂丛/股神经/腹横肌平面等)", "血管活性药：麻黄碱5-10mg iv、去氧肾上腺素50-100μg iv、去甲肾上腺素0.05-1μg/kg/min(低血压)、硝酸甘油(高血压)", "术后镇痛：多模式(对乙酰氨基酚1g q6h+NSAIDs+阿片类PCA+区域阻滞)，阿片PCA(吗啡1mg/次锁定5min或芬太尼)", "PONV预防：高危联合(地塞米松5mg+昂丹司琼8mg+氟哌啶醇1mg)，术中丙泊酚维持，减少阿片"], "non_pharmacological": ["术前宣教：解释麻醉过程、禁食要求、术后镇痛、缓解焦虑", "术前禁食：清饮料2h(无反流风险)、固体6-8h，减少误吸风险", "戒烟：术前≥2周(最好4-8周)，减少肺部并发症", "营养支持：营养不良者术前7-10天营养支持(肠内优先)", "术前康复(prehabilitation)：运动训练+营养+心理，改善大手术预后", "术中保温：充气加温毯/液体加温，维持体温≥36℃，减少出血/感染/心血管事件", "术后早期活动：术后24h内下床，减少血栓/肺部并发症/肠麻痹", "术后疼痛管理：多模式镇痛，患者自控镇痛(PCA)，评估疼痛评分"], "complications": ["困难气道/插管失败：预充氧，可视喉镜，喉罩，纤维支气管镜，紧急环甲膜穿刺/切开", "术中低血压/高血压：调整麻醉深度，血管活性药，评估容量/失血/心功能", "术中知晓：麻醉深度监测(BIS 40-60)，足够麻醉药，高危者术中唤醒评估", "术后恶心呕吐(PONV)：高危预防，联合用药，影响恢复和满意度", "术后疼痛控制不全：多模式镇痛，PCA，区域阻滞，评估调整", "术后谵妄：老年高危，避免苯二氮䓬/抗胆碱药，早期活动，定向力，非药物预防", "深静脉血栓/肺栓塞：机械预防(气压)+药物预防(低分子肝素)，早期活动", "肺部并发症：肺不张/肺炎，术前戒烟/呼吸训练，术后镇痛+咳嗽排痰+早期活动", "急性肾损伤：避免肾毒性药，维持灌注，目标导向液体，监测尿量肌酐"], "monitoring": ["标准监测：心电(Ⅱ/V5)、无创血压(每3-5min)、脉搏血氧、ETCO2(全麻/镇静)、体温(大手术>30min)", "高危/大手术：有创动脉压(连续血压/血气)、中心静脉压(CVP)、尿量(每小时)、BIS(麻醉深度)、肌松监测(TOF)、血气/电解质/血糖/乳酸", "术前：血常规、凝血、肝肾功、电解质、血糖、心电图(>40岁或心脏病)、胸片(胸腔/上腹部手术或肺病)、肺功能(严重肺病)", "术后：生命体征(每15-30min至稳定)、疼痛评分、恶心呕吐、尿量、引流液、血氧、意识", "麻醉恢复室(PACU)：Aldrete评分(活动/呼吸/循环/意识/氧合)≥9分可回病房", "出室标准：生命体征稳定、意识清醒、疼痛控制、无活动性出血、恶心呕吐控制"], "special_populations": ["老年：器官功能减退，药物减量，注意认知/谵妄，目标导向液体，避免低血压，区域麻醉可减少肺部并发症和谵妄", "小儿：按体重算剂量，气道管理(头大颈短/喉位置高/环状软骨最窄)，体温管理(易低体温)，液体计算精确", "妊娠：仰卧低血压综合征(子宫左移)，避免致畸药(孕早期)，误吸风险高(禁食/抑酸)，区域麻醉优先(凝血正常)，胎儿监测", "肥胖：困难气道风险高，坐位预充氧，药物按理想体重/校正体重，术后呼吸监测，血栓预防", "心脏病：心内科会诊，优化心功能，维持心肌氧供需平衡(心率/血压/血氧)，有创监测，β阻滞剂继续(术前不停)", "慢性肾病：避免肾毒性药(NSAIDs/氨基糖苷)，调整药物剂量(按eGFR)，维持肾灌注，电解质(尤其钾)", "糖尿病：术前血糖控制8-10mmol/L，术中每1-2h查血糖，胰岛素静脉泵入，避免低血糖"], "references": "中华医学会麻醉学分会. 围术期患者评估与管理指南(2024). 中华麻醉学杂志", "py": "wsqhzpgyglzn（"}];
